insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('bf06d559-f1bd-53ca-8f72-bd6011ea52aa','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Mengenal Angka 1–20','petualangan-matematika-kelas-1-bab-1',1,'A','Petualangan · Bab 1','dasar','draft',20,'{"summary":"Pulau Numeria bersama Kapten Rubi: Mengenal Angka 1–20. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-matematika-1","mentor":"Kapten Rubi","chapter_number":1,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan satu benda, satu hitungan dengan contoh dan alasan.","Menjelaskan belasan sebagai sepuluh dan sisanya dengan contoh dan alasan.","Menjelaskan membandingkan dan mengurutkan dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas I","url":"https://buku.kemendikdasmen.go.id/katalog/Matematika-untuk-SDMI-Kelas-I","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan satu benda, satu hitungan dengan contoh dan alasan.\n2. Menjelaskan belasan sebagai sepuluh dan sisanya dengan contoh dan alasan.\n3. Menjelaskan membandingkan dan mengurutkan dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Siapkan dua puluh tutup botol besar atau kartu. Kapten Rubi mengajakmu mengetahui banyak benda, bukan sekadar menyanyikan urutan angka. Mintalah pendamping menjaga benda kecil agar tidak masuk mulut."},{"type":"text","heading":"A. Satu benda, satu hitungan","body":"Sentuh atau pindahkan satu benda setiap menyebut satu bilangan. Mulailah dari satu, lalu dua, tiga, dan seterusnya. Bilangan terakhir menyatakan banyak seluruh benda. Jangan menghitung benda yang sama dua kali. Susunan boleh berjajar atau melingkar; selama tidak ada benda ditambah atau diambil, banyaknya tetap."},{"type":"text","heading":"Contoh bertahap 1","body":"Pindahkan tujuh kartu ke wadah sambil menghitung. Bilangan terakhir tujuh, jadi ada 7 kartu meskipun kartunya kemudian disusun dua baris."},{"type":"text","heading":"B. Belasan sebagai sepuluh dan sisanya","body":"Buat satu kelompok berisi sepuluh benda. Bilangan sebelas sampai sembilan belas dapat dilihat sebagai sepuluh ditambah beberapa satuan. Dua puluh berarti dua kelompok sepuluh. Bentuk kelompok memudahkan pemeriksaan sehingga kamu tidak perlu selalu mengulang hitungan dari awal."},{"type":"text","heading":"Contoh bertahap 2","body":"Ada 10 kartu dalam ikatan dan 6 kartu lepas. Jumlahnya 16, dibaca enam belas. Dua ikatan sepuluh berjumlah 20."},{"type":"text","heading":"C. Membandingkan dan mengurutkan","body":"Pasangkan benda dari dua kelompok satu per satu. Kelompok yang masih mempunyai sisa lebih banyak. Jika tidak ada sisa pada kedua kelompok, keduanya sama banyak. Pada urutan bilangan, maju satu langkah berarti bertambah satu dan mundur satu langkah berarti berkurang satu. Lambang bilangan menuliskan banyak itu."},{"type":"text","heading":"Contoh bertahap 3","body":"Kelompok 12 memiliki dua benda tersisa saat dipasangkan dengan kelompok 10. Maka 12 lebih banyak dari 10. Urutan 14, 15, 16 selalu naik satu."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat toko kartu berlabel 1–20. Pendamping memilih satu label; ambil benda sebanyak labelnya, kelompokkan sepuluh jika memungkinkan, lalu jelaskan cara memeriksa jumlah. Tukar peran dan bandingkan dua pesanan."},{"type":"text","heading":"Latihan mandiri","body":"1. Tuliskan bilangan untuk satu kelompok sepuluh dan empat satuan.\n2. Urutkan 9, 6, 8 dari kecil.\n3. Ada 11 sendok dan 13 gelas. Mana lebih banyak?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. 14 10 + 4 = 14.\n2. 6, 8, 9 Enam paling sedikit, lalu delapan, kemudian sembilan.\n3. Gelas, selisih dua. Sebelas pasangan terbentuk dan dua gelas tersisa.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Hitungan terakhir menyatakan jumlah. Belasan tersusun dari sepuluh dan satuan. Bandingkan dengan pasangan dan urutkan menurut banyaknya."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jika anak menunjuk terlalu cepat, pindahkan benda yang telah dihitung. Lanjutkan dari sampai 5, kemudian 10 dan 20; pengayaan berupa mencari beberapa susunan berbeda dengan jumlah sama.\nPeriksa pemodelan, langkah hitung, hasil/satuan dan penjelasan pemeriksaan. Jawaban akhir saja tidak cukup: minta anak menunjukkan gambar, benda atau alasan. Strategi lain yang benar diterima.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('70642fd3-c467-5977-b7c6-d38d18f75bb7','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Penjumlahan & Pengurangan Benda','petualangan-matematika-kelas-1-bab-2',1,'A','Petualangan · Bab 2','dasar','draft',20,'{"summary":"Pulau Numeria bersama Kapten Rubi: Penjumlahan & Pengurangan Benda. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-matematika-1","mentor":"Kapten Rubi","chapter_number":2,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan menggabungkan dua bagian dengan contoh dan alasan.","Menjelaskan mengambil dan membandingkan dengan contoh dan alasan.","Menjelaskan strategi dan pemeriksaan dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas I","url":"https://buku.kemendikdasmen.go.id/katalog/Matematika-untuk-SDMI-Kelas-I","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan menggabungkan dua bagian dengan contoh dan alasan.\n2. Menjelaskan mengambil dan membandingkan dengan contoh dan alasan.\n3. Menjelaskan strategi dan pemeriksaan dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Penjumlahan mencari banyak setelah digabung atau ditambah. Pengurangan dapat mencari sisa atau selisih. Gunakan paling banyak dua puluh benda agar cerita dapat diperagakan sebelum ditulis dengan lambang."},{"type":"text","heading":"A. Menggabungkan dua bagian","body":"Pisahkan dua kelompok dengan warna berbeda, lalu gabungkan. Banyak seluruh benda adalah hasil penjumlahan. Tanda + dibaca tambah. Tanda = menyatakan nilai di kedua sisi sama. Menambah nol tidak mengubah jumlah karena tidak ada benda baru. Menukar urutan dua kelompok juga tidak mengubah jumlahnya."},{"type":"text","heading":"Contoh bertahap 1","body":"Enam kartu merah dan lima kartu biru menjadi 11 kartu. Tulis 6 + 5 = 11. Kita dapat memeriksa dengan 5 + 6 = 11."},{"type":"text","heading":"B. Mengambil dan membandingkan","body":"Pada cerita mengambil, buat kelompok awal, pindahkan bagian yang diambil, lalu hitung sisa. Tanda − dibaca kurang. Untuk mencari selisih dua kelompok, buat pasangan dan hitung yang tidak berpasangan. Jangan memilih operasi hanya dari satu kata; tanyakan apa yang terjadi dan apa yang ingin diketahui."},{"type":"text","heading":"Contoh bertahap 2","body":"Ada 14 kelereng besar, empat dipindahkan. Sisanya 10: 14 − 4 = 10. Dua kelompok berisi 8 dan 5 benda mempunyai selisih 3."},{"type":"text","heading":"C. Strategi dan pemeriksaan","body":"Hitung maju untuk menambah dan mundur untuk mengurangi. Jangan menghitung posisi awal sebagai langkah tambahan. Jika mendekati sepuluh, pisahkan tambahan menjadi bagian yang melengkapi sepuluh dan sisanya. Periksa pengurangan dengan menjumlahkan sisa dan bagian yang diambil; hasilnya harus sama dengan banyak semula."},{"type":"text","heading":"Contoh bertahap 3","body":"8 + 5 dapat dipikirkan 8 + 2 + 3 = 13. Untuk memeriksa 13 − 5 = 8, hitung 8 + 5 = 13."},{"type":"text","heading":"Kegiatan penerapan","body":"Mainkan cerita toko. Buat dua cerita menggabungkan dan dua cerita mengambil dengan kartu. Teman menulis kalimat matematika lalu memeriksa dengan benda. Minta teman menerangkan makna setiap bilangan, bukan hanya menyebut hasil."},{"type":"text","heading":"Latihan mandiri","body":"1. Hitung 7 + 6 dengan melengkapi sepuluh.\n2. Ada 16 buku, lima dipinjam. Berapa sisa?\n3. Apa hasil 9 + 0?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. 13 7 + 3 + 3 = 13.\n2. 11 buku 16 − 5 = 11; periksa 11 + 5 = 16.\n3. 9 Kelompok kosong tidak menambah benda.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Pahami cerita, buat model, tulis operasi, hitung, dan periksa. Nol tidak menambah atau mengambil benda. Penjumlahan dapat memeriksa pengurangan."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Bedakan bagian yang diambil dengan sisa. Jika menghitung maju masih keliru, gunakan garis bilangan dan buat satu gerakan untuk satu langkah. Pengayaan: dua operasi berbeda dengan hasil sama.\nPeriksa pemodelan, langkah hitung, hasil/satuan dan penjelasan pemeriksaan. Jawaban akhir saja tidak cukup: minta anak menunjukkan gambar, benda atau alasan. Strategi lain yang benar diterima.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('37b79d92-d6b5-5022-a4c1-342a782a8e68','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Mengenal Bangun Datar Sederhana','petualangan-matematika-kelas-1-bab-3',1,'A','Petualangan · Bab 3','dasar','draft',20,'{"summary":"Pulau Numeria bersama Kapten Rubi: Mengenal Bangun Datar Sederhana. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-matematika-1","mentor":"Kapten Rubi","chapter_number":3,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan sisi dan titik sudut dengan contoh dan alasan.","Menjelaskan segitiga, persegi, dan persegi panjang dengan contoh dan alasan.","Menjelaskan mengelompokkan dan menyusun bentuk dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas I","url":"https://buku.kemendikdasmen.go.id/katalog/Matematika-untuk-SDMI-Kelas-I","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan sisi dan titik sudut dengan contoh dan alasan.\n2. Menjelaskan segitiga, persegi, dan persegi panjang dengan contoh dan alasan.\n3. Menjelaskan mengelompokkan dan menyusun bentuk dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Amati permukaan buku, ubin, dan roda mainan. Benda nyata mempunyai ketebalan; bangun datar adalah model bentuk pada permukaannya. Kita mengelompokkan bentuk berdasarkan ciri, bukan warna atau ukuran."},{"type":"text","heading":"A. Sisi dan titik sudut","body":"Sisi adalah batas lurus pada bangun bersisi lurus. Dua sisi bertemu di titik sudut. Telusuri batas bentuk dengan jari dan tandai setiap sudut agar tidak dihitung berulang. Bentuk yang diputar tetap mempunyai banyak sisi dan sudut yang sama. Lingkaran mempunyai batas melengkung, tidak mempunyai sisi lurus dan titik sudut."},{"type":"text","heading":"Contoh bertahap 1","body":"Segitiga kertas memiliki tiga sisi lurus dan tiga sudut. Ketika diputar menghadap bawah, bentuknya tetap segitiga."},{"type":"text","heading":"B. Segitiga, persegi, dan persegi panjang","body":"Segitiga memiliki tiga sisi. Persegi mempunyai empat sisi sama panjang dan empat sudut siku-siku. Persegi panjang mempunyai empat sudut siku-siku serta pasangan sisi berhadapan sama panjang. Pada pembelajaran ini nama persegi dipakai untuk kasus empat sisi sama; persegi juga termasuk keluarga persegi panjang."},{"type":"text","heading":"Contoh bertahap 2","body":"Permukaan penggaris segitiga memberi contoh tiga sisi. Kartu persegi panjang mempunyai dua sisi panjang dan dua sisi pendek; warna kartunya tidak menentukan bentuk."},{"type":"text","heading":"C. Mengelompokkan dan menyusun bentuk","body":"Pilih satu aturan, misalnya banyak sisi atau jenis batas. Jelaskan alasan setiap benda masuk kelompok. Bentuk kecil dapat disusun menjadi gambar baru, dan bentuk besar dapat dipotong menjadi bagian. Gambar benda dengan menggabungkan bentuk tanpa menganggap nama benda sama dengan nama bangunnya."},{"type":"text","heading":"Contoh bertahap 3","body":"Dua segitiga yang tepat dapat disusun menjadi sebuah persegi. Sebuah gambar rumah dapat memakai persegi untuk badan dan segitiga untuk atap."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat kartu lingkaran, segitiga, persegi, dan persegi panjang dengan bantuan pendamping saat memotong. Kelompokkan menurut jumlah sudut, lalu susun menjadi kendaraan. Ceritakan bentuk yang dipakai dan periksa apakah bentuk berubah namanya saat diputar."},{"type":"text","heading":"Latihan mandiri","body":"1. Berapa sudut segitiga?\n2. Bentuk apa yang mempunyai batas melengkung tanpa sudut?\n3. Apakah segitiga biru yang diputar menjadi bentuk lain?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. 3 Setiap pertemuan dua sisi dihitung sekali.\n2. Lingkaran Lingkaran tidak mempunyai titik sudut.\n3. Tidak Putaran tidak mengubah jumlah sisi dan sudut.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Kenali bentuk dari sisi, sudut, dan batas melengkung. Ukuran, warna, dan arah hadap tidak mengubah jenis bentuk."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jangan hanya menampilkan segitiga dengan ujung di atas. Berikan bentuk berbagai orientasi. Pengayaan: jelaskan mengapa persegi memenuhi ciri persegi panjang.\nPeriksa pemodelan, langkah hitung, hasil/satuan dan penjelasan pemeriksaan. Jawaban akhir saja tidak cukup: minta anak menunjukkan gambar, benda atau alasan. Strategi lain yang benar diterima.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('0227de29-f957-57db-8a46-c48d344adc7f','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Membandingkan Berat & Panjang','petualangan-matematika-kelas-1-bab-4',1,'A','Petualangan · Bab 4','dasar','draft',20,'{"summary":"Pulau Numeria bersama Kapten Rubi: Membandingkan Berat & Panjang. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-matematika-1","mentor":"Kapten Rubi","chapter_number":4,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan membandingkan panjang secara langsung dengan contoh dan alasan.","Menjelaskan membandingkan berat secara aman dengan contoh dan alasan.","Menjelaskan mengurutkan dengan satuan sama dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas I","url":"https://buku.kemendikdasmen.go.id/katalog/Matematika-untuk-SDMI-Kelas-I","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan membandingkan panjang secara langsung dengan contoh dan alasan.\n2. Menjelaskan membandingkan berat secara aman dengan contoh dan alasan.\n3. Menjelaskan mengurutkan dengan satuan sama dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Dua benda dapat berbeda panjang dan beratnya. Dalam percakapan sehari-hari kita mengatakan berat; timbangan sederhana membandingkan massa benda. Kita akan membandingkan dengan cara yang adil tanpa mengangkat benda berbahaya."},{"type":"text","heading":"A. Membandingkan panjang secara langsung","body":"Letakkan dua benda lurus berdampingan dengan salah satu ujung sejajar. Benda yang ujung lainnya lebih jauh adalah yang lebih panjang. Jika ujung awal tidak sama, perbandingan bisa menipu. Untuk benda melengkung gunakan tali sebagai pembanding lalu luruskan. Gunakan kata lebih panjang, lebih pendek, atau sama panjang."},{"type":"text","heading":"Contoh bertahap 1","body":"Pita merah dan biru diletakkan mulai garis yang sama. Ujung merah melewati biru, sehingga pita merah lebih panjang walaupun pita biru lebih lebar."},{"type":"text","heading":"B. Membandingkan berat secara aman","body":"Neraca seimbang membandingkan dua benda pada kedua sisinya. Sisi yang turun menunjukkan benda lebih berat jika neraca bekerja benar. Benda besar belum tentu lebih berat: kotak kosong dapat lebih ringan daripada batu kecil. Hindari membandingkan hanya dari penampilan; gunakan alat atau benda yang aman diangkat."},{"type":"text","heading":"Contoh bertahap 2","body":"Pada neraca, sisi berisi kantong beras turun dibanding sisi kapas. Kantong beras lebih berat dalam perbandingan ini, bukan karena warnanya."},{"type":"text","heading":"C. Mengurutkan dengan satuan sama","body":"Urutkan tiga benda dengan membandingkan secara berpasangan. Panjang dapat dinyatakan dengan satuan tidak baku, misalnya balok yang sama ukuran. Susun satuan rapat tanpa celah atau tumpang tindih dari ujung awal. Hasil berbeda jika ukuran satuan berbeda, sehingga aturan satuan perlu disebutkan saat melaporkan pengukuran."},{"type":"text","heading":"Contoh bertahap 3","body":"Pensil sepanjang lima balok yang sama dan pita sepanjang tujuh balok. Karena satuannya sama, pita lebih panjang dua balok."},{"type":"text","heading":"Kegiatan penerapan","body":"Pilih tiga pensil atau pita. Sejajarkan ujungnya dan urutkan dari pendek. Ukur dengan balok sama ukuran. Pendamping memperagakan neraca memakai benda ringan dan mencatat perbandingan; anak menjelaskan bukti yang dilihat."},{"type":"text","heading":"Latihan mandiri","body":"1. Mengapa ujung awal dua pita perlu sejajar?\n2. Kotak besar kosong dan batu kecil: dapatkah berat dipastikan dari ukuran?\n3. A panjangnya 4 balok, B 6 balok sama ukuran. Mana lebih panjang?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Agar dibandingkan dari titik awal yang sama. Selisih ujung akhir lalu mewakili perbedaan panjang.\n2. Tidak Ukuran tidak selalu menentukan massa; perlu perbandingan aman.\n3. B, dua balok lebih panjang. 6 − 4 = 2 satuan yang sama.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Sejajarkan ujung saat membandingkan panjang. Bandingkan massa dengan alat aman. Gunakan satuan seukuran dan tanpa celah agar hasil dapat dibandingkan."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jangan menyimpulkan benda paling besar pasti paling berat. Pendamping menangani alat/beban. Pengayaan: ukur benda sama dengan satuan kecil dan besar lalu jelaskan perbedaan bilangannya.\nPeriksa pemodelan, langkah hitung, hasil/satuan dan penjelasan pemeriksaan. Jawaban akhir saja tidak cukup: minta anak menunjukkan gambar, benda atau alasan. Strategi lain yang benar diterima.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('71b2579e-894c-584e-a89c-e48e6b7c2a40','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Nilai Tempat Ratusan, Puluhan, Satuan','petualangan-matematika-kelas-2-bab-1',2,'A','Petualangan · Bab 1','dasar','draft',20,'{"summary":"Pulau Numeria bersama Kapten Rubi: Nilai Tempat Ratusan, Puluhan, Satuan. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-matematika-2","mentor":"Kapten Rubi","chapter_number":1,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan membentuk ratusan, puluhan, satuan dengan contoh dan alasan.","Menjelaskan nilai angka bergantung tempat dengan contoh dan alasan.","Menjelaskan mengurai dan membandingkan dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas II","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-ii","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan membentuk ratusan, puluhan, satuan dengan contoh dan alasan.\n2. Menjelaskan nilai angka bergantung tempat dengan contoh dan alasan.\n3. Menjelaskan mengurai dan membandingkan dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Kamu sudah mengenal kelompok sepuluh. Sekarang bangun kelompok seratus dari sepuluh kelompok sepuluh. Bilangan sampai ratusan pada paket ini merupakan perluasan yang perlu disesuaikan guru dengan kesiapan dan ATP kelas."},{"type":"text","heading":"A. Membentuk ratusan, puluhan, satuan","body":"Sepuluh satuan dapat ditukar satu puluhan. Sepuluh puluhan dapat ditukar satu ratusan. Pertukaran mengubah bentuk kelompok, bukan jumlah benda. Gunakan kartu atau gambar bundel untuk menunjukkan ketiga tempat. Tuliskan tempat ratusan di kiri, puluhan di tengah, dan satuan di kanan."},{"type":"text","heading":"Contoh bertahap 1","body":"Dua lembar seratus, tiga ikatan sepuluh dan empat kartu satuan menyatakan 234. Bentuk panjangnya 200 + 30 + 4."},{"type":"text","heading":"B. Nilai angka bergantung tempat","body":"Angka yang sama mempunyai nilai berbeda menurut letaknya. Dalam 343, angka 3 pertama bernilai 300, sedangkan angka 3 terakhir bernilai 3. Nol menandakan tidak ada kelompok pada tempat itu dan menjaga posisi angka lain. Saat membaca bilangan, sebut bagian ratusan, puluhan, dan satuannya dengan urut."},{"type":"text","heading":"Contoh bertahap 2","body":"Bilangan 407 mempunyai empat ratusan, nol puluhan, dan tujuh satuan. Menulisnya 47 akan menghilangkan nilai ratusannya."},{"type":"text","heading":"C. Mengurai dan membandingkan","body":"Urai bilangan menjadi jumlah nilai tempat. Untuk membandingkan dua bilangan tiga angka, mulai dari ratusan. Jika sama, bandingkan puluhan; jika masih sama, bandingkan satuan. Cara ini lebih cepat daripada menghitung semua benda. Pemeriksaan dilakukan dengan membentuk kembali bundel sesuai uraian."},{"type":"text","heading":"Contoh bertahap 3","body":"352 lebih besar daripada 329: ratusannya sama-sama 3, tetapi 5 puluhan lebih banyak daripada 2 puluhan. Pada 216 dan 219, satuanlah yang menentukan."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat toko bundel dengan kartu R, P, dan S. Satu anak memesan bilangan tiga angka, anak lain menguraikan dan menukar sepuluh satuan menjadi puluhan. Jelaskan bahwa jumlah tetap sama setelah pertukaran."},{"type":"text","heading":"Latihan mandiri","body":"1. Uraikan 582.\n2. Apa nilai angka 6 pada 461?\n3. Mana lebih besar: 405 atau 450?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. 500 + 80 + 2 Masing-masing angka dikalikan nilai tempatnya.\n2. 60 Angka 6 berada di tempat puluhan.\n3. 450 Ratusan sama; lima puluhan lebih dari nol puluhan.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Satu ratusan setara sepuluh puluhan. Nilai angka ditentukan tempat, dan nol menjaga tempat yang kosong. Bandingkan dari tempat terbesar."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Bedakan angka dengan nilainya. Gunakan bundel nyata sebelum simbol. Jika sampai 100 belum mantap, kembali ke dua tempat dahulu; lanjutkan ratusan sebagai pengayaan bertahap.\nPeriksa pemodelan, langkah hitung, hasil/satuan dan penjelasan pemeriksaan. Jawaban akhir saja tidak cukup: minta anak menunjukkan gambar, benda atau alasan. Strategi lain yang benar diterima.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('a1eb3328-2a41-58ac-9d4b-10e99a90cb77','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Penjumlahan & Pengurangan Bersusun','petualangan-matematika-kelas-2-bab-2',2,'A','Petualangan · Bab 2','dasar','draft',20,'{"summary":"Pulau Numeria bersama Kapten Rubi: Penjumlahan & Pengurangan Bersusun. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-matematika-2","mentor":"Kapten Rubi","chapter_number":2,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan menata kolom dan menjumlahkan dengan contoh dan alasan.","Menjelaskan mengurangi dengan pengelompokan ulang dengan contoh dan alasan.","Menjelaskan memeriksa dengan operasi kebalikan dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas II","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-ii","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan menata kolom dan menjumlahkan dengan contoh dan alasan.\n2. Menjelaskan mengurangi dengan pengelompokan ulang dengan contoh dan alasan.\n3. Menjelaskan memeriksa dengan operasi kebalikan dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Hitung bersusun membantu menata nilai tempat. Cara ini bukan aturan memindahkan angka tanpa makna: setiap penyimpanan atau pengelompokan ulang mewakili pertukaran sepuluh satuan dengan satu puluhan, atau sebaliknya."},{"type":"text","heading":"A. Menata kolom dan menjumlahkan","body":"Tuliskan satuan tepat di bawah satuan, puluhan di bawah puluhan dan ratusan di bawah ratusan. Mulai menjumlah dari satuan. Jika jumlah satuan mencapai sepuluh, tukarkan menjadi satu puluhan dan sisakan satuannya. Sertakan puluhan hasil pertukaran ketika menjumlah kolom berikutnya."},{"type":"text","heading":"Contoh bertahap 1","body":"Pada 158 + 126, satuan 8 + 6 = 14: tulis 4, simpan 1 puluhan. Puluhan 5 + 2 + 1 = 8. Ratusan 1 + 1 = 2. Hasil 284."},{"type":"text","heading":"B. Mengurangi dengan pengelompokan ulang","body":"Kurangi dari tempat satuan. Jika satuan yang tersedia lebih kecil daripada yang diambil, tukarkan satu puluhan menjadi sepuluh satuan. Nilai seluruh bilangan tetap sama. Jangan membalik angka kecil-besar pada tiap kolom karena itu mengubah cerita pengurangan. Catat tempat yang sudah berkurang akibat pertukaran."},{"type":"text","heading":"Contoh bertahap 2","body":"Pada 243 − 118, ubah 4 puluhan menjadi 3 puluhan dan 3 satuan menjadi 13 satuan. 13 − 8 = 5, 3 − 1 = 2, 2 − 1 = 1. Hasilnya 125."},{"type":"text","heading":"C. Memeriksa dengan operasi kebalikan","body":"Jumlahkan hasil pengurangan dengan bilangan yang dikurangkan; hasilnya harus kembali ke bilangan awal. Gunakan perkiraan untuk mendeteksi kesalahan besar. Pada penjumlahan, hitung kembali dengan urutan bagian ditukar atau model nilai tempat. Jawaban soal cerita perlu menyebut satuan atau benda yang dihitung."},{"type":"text","heading":"Contoh bertahap 3","body":"Untuk memeriksa 321 − 106 = 215, hitung 215 + 106 = 321. Jika hasil ratusan jauh dari perkiraan 300 − 100, periksa kembali kolomnya."},{"type":"text","heading":"Kegiatan penerapan","body":"Gambar tabel ratusan-puluhan-satuan. Peragakan satu penjumlahan yang perlu menyimpan dan satu pengurangan yang perlu menukar puluhan. Pasanganmu menjelaskan setiap perubahan sebelum kalian menuliskan hasil bersusunnya."},{"type":"text","heading":"Latihan mandiri","body":"1. Hitung 147 + 135.\n2. Hitung 264 − 137.\n3. Periksa 350 − 125 = 225.\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. 282 7 + 5 = 12; simpan satu puluhan, lalu 4 + 3 + 1 = 8.\n2. 127 Tukar satu puluhan: 14 − 7 = 7, 5 − 3 = 2, 2 − 1 = 1.\n3. 225 + 125 = 350 Penjumlahan hasil dan pengurang mengembalikan bilangan awal.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Sejajarkan nilai tempat, mulai satuan, dan pahami pertukaran. Simpan atau pinjam adalah pengelompokan ulang dengan nilai tetap."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jika anak menghitung 3 − 8 menjadi 5 dengan membalik urutan, kembali ke bundel. Kerjakan pengurangan tanpa pertukaran dahulu, kemudian satu pertukaran; tantangan berikutnya melibatkan nol.\nPeriksa pemodelan, langkah hitung, hasil/satuan dan penjelasan pemeriksaan. Jawaban akhir saja tidak cukup: minta anak menunjukkan gambar, benda atau alasan. Strategi lain yang benar diterima.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('a156b9fe-3472-5868-a20b-a8a00356f21e','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Membaca Jam & Waktu','petualangan-matematika-kelas-2-bab-3',2,'A','Petualangan · Bab 3','dasar','draft',20,'{"summary":"Pulau Numeria bersama Kapten Rubi: Membaca Jam & Waktu. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-matematika-2","mentor":"Kapten Rubi","chapter_number":3,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan mengenal jarum jam dengan contoh dan alasan.","Menjelaskan membaca menit dan penulisan waktu dengan contoh dan alasan.","Menjelaskan menghitung durasi sederhana dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas II","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-ii","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan mengenal jarum jam dengan contoh dan alasan.\n2. Menjelaskan membaca menit dan penulisan waktu dengan contoh dan alasan.\n3. Menjelaskan menghitung durasi sederhana dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Jam membantu menyatakan kapan kegiatan terjadi; durasi menyatakan berapa lama. Mulailah dari jam tepat, setengah jam, lalu menit. Model jam karton lebih aman daripada membongkar jam listrik."},{"type":"text","heading":"A. Mengenal jarum jam","body":"Jarum pendek menunjukkan jam dan jarum panjang menunjukkan menit. Satu putaran jarum panjang memerlukan enam puluh menit, setara satu jam. Pada jam tepat jarum panjang menunjuk 12. Jarum pendek bergerak perlahan sepanjang satu jam sehingga tidak selalu tepat pada angka."},{"type":"text","heading":"Contoh bertahap 1","body":"Pukul 08.00: jarum pendek di 8, jarum panjang di 12. Pukul 08.30: jarum panjang di 6 dan jarum pendek sudah berada di antara 8 dan 9."},{"type":"text","heading":"B. Membaca menit dan penulisan waktu","body":"Jarak antara dua angka besar pada jam analog mewakili lima menit bagi jarum panjang. Dari 12, hitung 5, 10, 15, dan seterusnya. Jam digital menunjukkan jam dan menit langsung. Sebut pagi/siang/sore jika memakai format dua belas jam agar tidak rancu. Dalam format 24 jam, pukul 14.00 berarti pukul dua siang."},{"type":"text","heading":"Contoh bertahap 2","body":"Jarum panjang di angka 3 berarti 15 menit. Jika jarum pendek sedikit lewat 10, waktunya 10.15. Pukul 18.00 adalah pukul enam sore."},{"type":"text","heading":"C. Menghitung durasi sederhana","body":"Gambarkan waktu mulai dan akhir pada garis waktu. Hitung lompatan jam lalu menit. Jika menit melewati enam puluh, tukar enam puluh menit menjadi satu jam. Tidak semua pengurangan tampilan jam boleh dilakukan seperti bilangan biasa karena basis menit adalah enam puluh, bukan seratus."},{"type":"text","heading":"Contoh bertahap 3","body":"Belajar dari 09.15 sampai 10.00: dari 09.15 ke 09.30 ada 15 menit, lalu ke 10.00 ada 30 menit. Total 45 menit."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat jadwal rekaan tiga kegiatan sehari. Atur jarum model sesuai waktu mulai, lalu tentukan waktu selesai dengan lompatan lima belas menit. Pasangan memeriksa durasinya. Tidak perlu membagikan jadwal pribadi atau alamat."},{"type":"text","heading":"Latihan mandiri","body":"1. Jarum panjang di 6 menunjukkan berapa menit?\n2. Berapa durasi 07.30 sampai 08.00?\n3. Tuliskan 3 sore dengan format 24 jam.\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. 30 menit Enam langkah angka besar ×5 menit.\n2. 30 menit Setengah putaran menit menuju jam tepat.\n3. 15.00 Jam sore setelah 12 ditambah tiga jam.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Satu jam adalah 60 menit. Bedakan waktu dengan durasi, baca kedua jarum, dan gunakan lompatan pada garis waktu."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jangan membaca jarum panjang di 4 sebagai empat menit: nilainya 20 menit. Pengayaan: durasi melintasi pergantian jam dengan menit tidak bulat.\nPeriksa pemodelan, langkah hitung, hasil/satuan dan penjelasan pemeriksaan. Jawaban akhir saja tidak cukup: minta anak menunjukkan gambar, benda atau alasan. Strategi lain yang benar diterima.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('8fd1b8fe-76bb-5085-ae13-0f80c6906754','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Mengenal Diagram Gambar (Piktogram)','petualangan-matematika-kelas-2-bab-4',2,'A','Petualangan · Bab 4','dasar','draft',20,'{"summary":"Pulau Numeria bersama Kapten Rubi: Mengenal Diagram Gambar (Piktogram). Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-matematika-2","mentor":"Kapten Rubi","chapter_number":4,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan mengumpulkan dan mengelompokkan data dengan contoh dan alasan.","Menjelaskan menggambar piktogram dan membaca kunci dengan contoh dan alasan.","Menjelaskan membandingkan dan menyimpulkan dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas II","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-ii","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan mengumpulkan dan mengelompokkan data dengan contoh dan alasan.\n2. Menjelaskan menggambar piktogram dan membaca kunci dengan contoh dan alasan.\n3. Menjelaskan membandingkan dan menyimpulkan dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Data adalah catatan yang membantu menjawab pertanyaan. Piktogram memakai gambar untuk menyatakan banyaknya data. Gambar perlu keterangan nilai agar pembaca tahu apakah satu gambar berarti satu, dua, atau lebih benda."},{"type":"text","heading":"A. Mengumpulkan dan mengelompokkan data","body":"Tentukan pertanyaan yang jelas, misalnya buah pilihan sekelompok anak. Setiap jawaban dicatat satu kali sesuai aturan. Kelompokkan jawaban yang sejenis dan hitung frekuensinya. Jangan mengubah pilihan agar sesuai dugaan kita. Data pilihan kelompok kecil hanya menceritakan kelompok yang diamati."},{"type":"text","heading":"Contoh bertahap 1","body":"Lima anak memilih pisang dan tiga memilih jeruk. Tabel mencatat pisang 5, jeruk 3. Jumlah responden adalah delapan, bukan hanya banyaknya jenis buah."},{"type":"text","heading":"B. Menggambar piktogram dan membaca kunci","body":"Gunakan gambar sejenis dan ukuran sama. Cantumkan judul, kategori, dan kunci nilai satu gambar. Jika satu gambar mewakili dua anak, tiga gambar berarti enam anak. Bila jumlah tidak habis dibagi nilai gambar, pilih kunci yang sesuai atau jelaskan gambar sebagian; pada latihan awal gunakan jumlah yang habis dibagi."},{"type":"text","heading":"Contoh bertahap 2","body":"Kunci satu bintang = 2 suara. Baris apel mempunyai empat bintang, sehingga apel mendapat 4 × 2 = 8 suara."},{"type":"text","heading":"C. Membandingkan dan menyimpulkan","body":"Baca nilai kategori sebelum mencari jumlah atau selisih. Terbanyak berarti frekuensi paling tinggi; paling sedikit berarti frekuensi paling rendah. Gunakan angka pada diagram untuk mendukung pernyataan. Diagram tidak memberitahukan alasan seseorang memilih kecuali alasan itu juga dikumpulkan."},{"type":"text","heading":"Contoh bertahap 3","body":"Dengan kunci satu lingkaran = satu anak, mangga 6 lingkaran dan salak 4 lingkaran berbeda dua anak. Kita tidak dapat menyimpulkan semua anak di sekolah memilih mangga."},{"type":"text","heading":"Kegiatan penerapan","body":"Tanyakan pilihan dua warna pada anggota kelompok belajar tanpa mencatat nama. Buat tabel dan piktogram dengan kunci satu gambar satu suara. Pasangan membaca kategori terbanyak dan membuktikan total gambar sama dengan jumlah jawaban."},{"type":"text","heading":"Latihan mandiri","body":"1. Satu gambar = 2 buku. Lima gambar berarti?\n2. Data A=7 dan B=4. Berapa selisihnya?\n3. Apa yang wajib dijelaskan agar gambar dapat dihitung?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. 10 buku 5 × 2 = 10.\n2. 3 7 − 4 = 3.\n3. Kunci nilai satu gambar. Tanpa kunci, jumlah yang diwakili tiap gambar belum jelas.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Data dicatat dan dikelompokkan. Piktogram mempunyai judul, kategori, dan kunci. Hitung nilai gambar sebelum menyimpulkan."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Anak sering menghitung gambar tanpa membaca kunci. Minta anak menulis nilai tiap gambar dahulu. Pengayaan: tampilkan data sama dengan kunci satu gambar dua suara.\nPeriksa pemodelan, langkah hitung, hasil/satuan dan penjelasan pemeriksaan. Jawaban akhir saja tidak cukup: minta anak menunjukkan gambar, benda atau alasan. Strategi lain yang benar diterima.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('8270a317-52f4-5970-8aea-b265432e7022','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Operasi Hitung Bilangan sampai 1.000','petualangan-matematika-kelas-3-bab-1',3,'B','Petualangan · Bab 1','sedang','draft',25,'{"summary":"Pulau Numeria bersama Kapten Rubi: Operasi Hitung Bilangan sampai 1.000. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-matematika-3","mentor":"Kapten Rubi","chapter_number":1,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan membaca dan membandingkan bilangan dengan contoh dan alasan.","Menjelaskan menjumlahkan dan mengurangkan dengan contoh dan alasan.","Menjelaskan menyelesaikan masalah dua langkah dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas III","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-iii","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan membaca dan membandingkan bilangan dengan contoh dan alasan.\n2. Menjelaskan menjumlahkan dan mengurangkan dengan contoh dan alasan.\n3. Menjelaskan menyelesaikan masalah dua langkah dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Bilangan sampai seribu dapat dibentuk dari ratusan, puluhan, dan satuan. Bacalah cerita sebelum memilih operasi. Tuliskan satuan benda dan perkirakan hasil agar kesalahan nilai tempat mudah ditemukan."},{"type":"text","heading":"A. Membaca dan membandingkan bilangan","body":"Nilai angka ditentukan tempatnya. Urai bilangan menjadi jumlah ratusan, puluhan, dan satuan; seribu adalah sepuluh ratusan. Bandingkan dari tempat paling besar, lalu bergerak ke kanan jika nilainya sama. Nol menjaga tempat kosong dan tidak boleh dihapus sesuka hati."},{"type":"text","heading":"Contoh bertahap 1","body":"706 = 700 + 0 + 6. Bilangan 760 lebih besar daripada 706 karena puluhannya lebih besar, walaupun kedua bilangan mempunyai angka yang sama."},{"type":"text","heading":"B. Menjumlahkan dan mengurangkan","body":"Sejajarkan kolom. Pada penjumlahan, sepuluh satuan ditukar menjadi satu puluhan; pada pengurangan pertukaran dapat dibalik. Catat perubahan pada kolom yang dipakai. Kerjakan dari satuan agar pertukaran masuk ke kolom berikutnya. Gunakan operasi kebalikan untuk memeriksa, bukan mengandalkan hafalan prosedur."},{"type":"text","heading":"Contoh bertahap 2","body":"368 + 257 = 625: 8 + 7 = 15, 6 + 5 + 1 = 12 puluhan, lalu 3 + 2 + 1 = 6 ratusan. Periksa dengan 625 − 257 = 368."},{"type":"text","heading":"C. Menyelesaikan masalah dua langkah","body":"Tandai apa yang diketahui dan ditanyakan. Jika ada dua kejadian, ikuti urutannya atau buat diagram. Hitung satu langkah, tulis maknanya, lalu lanjutkan. Tanda kurung membantu menampilkan bagian yang digabung. Perkiraan menggunakan ratusan terdekat dapat memberi pemeriksaan kasar tetapi bukan mengganti hasil tepat."},{"type":"text","heading":"Contoh bertahap 3","body":"Perpustakaan mempunyai 450 buku, menerima 125 buku lalu meminjamkan 80. Setelah tambahan ada 575; setelah dipinjam tersisa 495 buku. Ceritanya 450 + 125 − 80."},{"type":"text","heading":"Kegiatan penerapan","body":"Rancang toko buku rekaan dengan stok di bawah seribu. Catat stok awal, tambahan, dan buku keluar. Tukar catatan dengan teman untuk dihitung dan diperiksa memakai operasi kebalikan serta perkiraan."},{"type":"text","heading":"Latihan mandiri","body":"1. Uraikan 809.\n2. Hitung 476 + 218.\n3. Stok 600, terjual 135 lalu masuk 40. Berapa stok akhir?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. 800 + 0 + 9 Nol menyatakan tidak ada puluhan.\n2. 694 Satuan 14 menambah satu ke puluhan; hasilnya 694.\n3. 505 600 − 135 = 465; 465 + 40 = 505.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Nilai tempat membantu membaca, membandingkan, dan berhitung. Pada cerita dua langkah, urutkan kejadian dan periksa hasil dengan cara lain."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jika operasi melintasi nol sulit, gambarkan pertukaran satu ratusan menjadi sepuluh puluhan. Pengayaan: buat dua cerita berbeda dengan operasi dan hasil yang sama.\nPeriksa pemodelan, langkah hitung, hasil/satuan dan penjelasan pemeriksaan. Jawaban akhir saja tidak cukup: minta anak menunjukkan gambar, benda atau alasan. Strategi lain yang benar diterima.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('37abccf0-b215-56bf-9cfd-f9890b54f424','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Konsep Perkalian Dasar','petualangan-matematika-kelas-3-bab-2',3,'B','Petualangan · Bab 2','sedang','draft',25,'{"summary":"Pulau Numeria bersama Kapten Rubi: Konsep Perkalian Dasar. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-matematika-3","mentor":"Kapten Rubi","chapter_number":2,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan kelompok sama banyak dengan contoh dan alasan.","Menjelaskan susunan baris dan kolom dengan contoh dan alasan.","Menjelaskan mengurai perkalian dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas III","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-iii","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan kelompok sama banyak dengan contoh dan alasan.\n2. Menjelaskan susunan baris dan kolom dengan contoh dan alasan.\n3. Menjelaskan mengurai perkalian dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Perkalian merangkum penjumlahan kelompok sama banyak. Dalam bab ini a × b dimaknai a kelompok, tiap kelompok berisi b. Gunakan gambar kelompok sebelum menghafal hasilnya."},{"type":"text","heading":"A. Kelompok sama banyak","body":"Sebuah situasi dapat dinyatakan sebagai perkalian jika setiap kelompok berisi sama banyak. Tentukan banyak kelompok dan isi tiap kelompok. Jika isinya berbeda, penjumlahan biasa lebih tepat. Menyebut satuan pada jawaban menjaga hubungan antara operasi dengan cerita."},{"type":"text","heading":"Contoh bertahap 1","body":"Empat kantong masing-masing berisi tiga jeruk berarti 3 + 3 + 3 + 3 = 12, atau 4 × 3 = 12 jeruk."},{"type":"text","heading":"B. Susunan baris dan kolom","body":"Gambar benda sebagai baris yang sama panjang. Banyak seluruh benda dapat dihitung menurut baris atau kolom. Pertukaran faktor memberi hasil sama, meski makna kelompok dalam cerita dapat berbeda. Satu kelompok berisi b benda berjumlah b; kelompok kosong atau nol kelompok memberikan jumlah nol."},{"type":"text","heading":"Contoh bertahap 2","body":"Tiga baris masing-masing lima titik berisi 15 titik. Jika dilihat sebagai lima kolom masing-masing tiga, hasil 5 × 3 juga 15."},{"type":"text","heading":"C. Mengurai perkalian","body":"Gunakan hasil yang sudah dikenal untuk mencari yang baru. Pecah salah satu faktor menjadi dua bagian yang mudah. Hitung hasil tiap bagian lalu gabungkan. Strategi ini disebut sifat distributif dan dapat dibuktikan dengan membagi gambar persegi panjang menjadi dua bagian tanpa kehilangan titik."},{"type":"text","heading":"Contoh bertahap 3","body":"6 × 7 = 6 × (5 + 2). Bagian pertama 30, kedua 12; total 42. Periksa dengan enam kelompok tujuh benda."},{"type":"text","heading":"Kegiatan penerapan","body":"Susun kartu dalam empat baris yang masing-masing berisi enam. Baca menurut baris dan kolom. Tutup dua kolom lalu jelaskan bagaimana jumlah keseluruhan diperoleh dari dua bagian yang tidak saling tumpang tindih."},{"type":"text","heading":"Latihan mandiri","body":"1. Lima piring masing-masing empat kue. Berapa kue?\n2. Jelaskan 7 × 3 dengan dua bagian.\n3. Apakah kelompok berisi 2, 3, dan 4 dapat langsung ditulis 3 × 3?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. 20 kue 5 × 4 = 4 + 4 + 4 + 4 + 4.\n2. 5 × 3 + 2 × 3 = 21 15 + 6 = 21.\n3. Tidak sebagai model kelompoknya. Isinya tidak sama; jumlah 2 + 3 + 4 memang 9, tetapi model kelompok berbeda.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Perkalian menggunakan kelompok sama banyak. Baris-kolom menjelaskan pertukaran faktor; penguraian faktor memudahkan perhitungan."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Bedakan faktor dengan hasil. Minta anak menggambar dua faktor sebelum berhitung. Pengayaan: periksa satu perkalian dengan dua penguraian berbeda.\nPeriksa pemodelan, langkah hitung, hasil/satuan dan penjelasan pemeriksaan. Jawaban akhir saja tidak cukup: minta anak menunjukkan gambar, benda atau alasan. Strategi lain yang benar diterima.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('8ccb7c28-2227-5d95-af01-ac89702411da','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Konsep Pembagian Sama Rata','petualangan-matematika-kelas-3-bab-3',3,'B','Petualangan · Bab 3','sedang','draft',25,'{"summary":"Pulau Numeria bersama Kapten Rubi: Konsep Pembagian Sama Rata. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-matematika-3","mentor":"Kapten Rubi","chapter_number":3,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan berbagi rata dengan contoh dan alasan.","Menjelaskan membuat kelompok dan menghubungkan perkalian dengan contoh dan alasan.","Menjelaskan sisa dan aturan dasar dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas III","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-iii","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan berbagi rata dengan contoh dan alasan.\n2. Menjelaskan membuat kelompok dan menghubungkan perkalian dengan contoh dan alasan.\n3. Menjelaskan sisa dan aturan dasar dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Pembagian menjawab dua pertanyaan: berapa isi setiap kelompok jika banyak kelompok diketahui, atau berapa kelompok dapat dibentuk jika isi tiap kelompok diketahui. Keduanya membutuhkan kelompok yang sama banyak."},{"type":"text","heading":"A. Berbagi rata","body":"Bagikan benda satu per satu bergiliran ke sejumlah wadah. Setelah semua habis dibagikan, periksa setiap wadah berisi sama banyak. Lambang ÷ dibaca dibagi. Bilangan pertama menyatakan jumlah awal, pembagi menyatakan banyak penerima pada cerita berbagi, dan hasil menyatakan bagian tiap penerima."},{"type":"text","heading":"Contoh bertahap 1","body":"Dua puluh kartu dibagi rata ke lima anak. Setiap putaran membagikan lima kartu. Setelah empat putaran setiap anak mendapat empat: 20 ÷ 5 = 4."},{"type":"text","heading":"B. Membuat kelompok dan menghubungkan perkalian","body":"Jika setiap kelompok harus berisi jumlah tertentu, bentuk kelompok itu sampai benda habis. Hasilnya adalah banyak kelompok. Perkalian dapat memeriksa pembagian: banyak kelompok dikali isi harus sama dengan jumlah awal. Jelaskan satuan hasil agar banyak kelompok tidak tertukar dengan isi tiap kelompok."},{"type":"text","heading":"Contoh bertahap 2","body":"Ada 24 kancing; tiap kantong diisi enam. Terbentuk empat kantong: 24 ÷ 6 = 4. Pemeriksaan 4 × 6 = 24."},{"type":"text","heading":"C. Sisa dan aturan dasar","body":"Tidak semua jumlah habis dibagi. Sisa harus lebih kecil daripada pembagi; jika masih cukup membuat satu kelompok, pembagian belum selesai. Nol benda dibagi ke jumlah kelompok bukan nol menghasilkan nol. Pembagian dengan nol tidak didefinisikan dan tidak boleh dijawab nol. Dalam cerita tertentu benda boleh dipecah, tetapi di sini hitung benda utuh."},{"type":"text","heading":"Contoh bertahap 3","body":"Tujuh belas pensil dimasukkan tiga per kotak. Terbentuk lima kotak penuh dan sisa dua, sebab 5 × 3 + 2 = 17 dan 2 lebih kecil dari 3."},{"type":"text","heading":"Kegiatan penerapan","body":"Gunakan 18 kartu. Pertama bagikan kepada tiga boneka; kemudian susun menjadi kelompok berisi tiga. Bandingkan arti hasil enam pada kedua cerita. Ulangi dengan 19 kartu dan jelaskan sisanya."},{"type":"text","heading":"Latihan mandiri","body":"1. 28 stiker dibagi rata ke 4 anak.\n2. Berapa kelompok isi 5 dari 23 kartu?\n3. Mengapa 12 ÷ 0 tidak boleh dijawab 0?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. 7 stiker per anak 4 × 7 = 28.\n2. 4 kelompok, sisa 3 4 × 5 + 3 = 23 dan sisa kurang dari 5.\n3. Tidak ada hasil yang memenuhi. 0 dikali bilangan apa pun bukan 12.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Pembagian memakai kelompok sama banyak. Hasil harus sesuai arti pertanyaan dan dapat diperiksa dengan perkalian; sisa lebih kecil daripada pembagi."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Minta anak menamai hasil: anak, kantong, atau benda per anak. Jika bingung, kembali ke berbagi konkret. Pengayaan: satu jumlah dapat memberi sisa berbeda untuk pembagi berbeda.\nPeriksa pemodelan, langkah hitung, hasil/satuan dan penjelasan pemeriksaan. Jawaban akhir saja tidak cukup: minta anak menunjukkan gambar, benda atau alasan. Strategi lain yang benar diterima.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('7ca72cf0-618c-5606-bd86-230948859261','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Mengenal Pecahan Sederhana','petualangan-matematika-kelas-3-bab-4',3,'B','Petualangan · Bab 4','sedang','draft',25,'{"summary":"Pulau Numeria bersama Kapten Rubi: Mengenal Pecahan Sederhana. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-matematika-3","mentor":"Kapten Rubi","chapter_number":4,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan membagi sama besar dengan contoh dan alasan.","Menjelaskan pembilang dan penyebut dengan contoh dan alasan.","Menjelaskan membandingkan pecahan satuan dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas III","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-iii","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan membagi sama besar dengan contoh dan alasan.\n2. Menjelaskan pembilang dan penyebut dengan contoh dan alasan.\n3. Menjelaskan membandingkan pecahan satuan dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Pecahan menyatakan bagian dari keseluruhan yang dibagi sama besar. Keseluruhannya harus jelas: setengah satu pita tidak dapat dibandingkan langsung dengan setengah pita lain yang panjangnya berbeda."},{"type":"image","url":"/assets/petualangan-pecahan.svg","caption":"Dua pita sama panjang membandingkan setengah dengan seperempat."},{"type":"text","heading":"A. Membagi sama besar","body":"Lipat gambar persegi panjang menjadi dua, tiga, atau empat bagian sama luas. Satu dari dua bagian ditulis 1/2, satu dari tiga 1/3, dan satu dari empat 1/4. Banyak potongan saja tidak cukup; setiap bagian harus sama besar. Dua bagian tidak sama besar tidak otomatis disebut dua setengah."},{"type":"text","heading":"Contoh bertahap 1","body":"Satu kertas dibagi empat kotak sama luas. Mewarnai satu kotak berarti mewarnai 1/4 kertas. Mewarnai tiga berarti 3/4."},{"type":"text","heading":"B. Pembilang dan penyebut","body":"Angka di bawah garis pecahan adalah penyebut: banyak bagian sama besar pada satu keseluruhan. Angka di atas adalah pembilang: banyak bagian yang dipilih. Jika pembilang sama dengan penyebut, semua bagian terambil sehingga nilainya satu utuh. Gambarkan dahulu sebelum menghubungkan ke lambang."},{"type":"text","heading":"Contoh bertahap 2","body":"Pada 2/3, keseluruhan dibagi tiga bagian sama besar dan dua dipilih. Pada 4/4, keempat bagian dipilih, sehingga sama dengan satu."},{"type":"text","heading":"C. Membandingkan pecahan satuan","body":"Untuk keseluruhan yang sama, semakin banyak bagian pembagiannya, semakin kecil satu bagiannya. Karena itu 1/2 lebih besar daripada 1/3, dan 1/3 lebih besar daripada 1/4. Gunakan pita sama panjang atau garis bilangan 0 sampai 1. Jangan menyimpulkan penyebut lebih besar selalu membuat nilai pecahan lebih besar."},{"type":"text","heading":"Contoh bertahap 3","body":"Dua pita sama panjang masing-masing dibagi dua dan empat. Satu bagian dari pita pertama menutupi dua bagian pita kedua: 1/2 = 2/4."},{"type":"text","heading":"Kegiatan penerapan","body":"Lipat dua kertas sama ukuran menjadi dua dan empat bagian. Warnai satu bagian masing-masing, bandingkan luasnya, lalu tunjukkan dua bagian seperempat yang menutupi satu setengah. Gunting hanya dengan bantuan pendamping."},{"type":"text","heading":"Latihan mandiri","body":"1. Apa arti 3/4?\n2. Mana lebih besar: 1/3 atau 1/4 dari kertas sama ukuran?\n3. Tuliskan pecahan seluruh tiga potong dari tiga bagian.\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Tiga dari empat bagian sama besar. Penyebut menunjukkan empat bagian, pembilang tiga yang dipilih.\n2. 1/3 Tiga bagian membuat tiap bagian lebih besar daripada empat bagian.\n3. 3/3 = 1 Semua bagian dari satu keseluruhan diambil.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Pecahan memerlukan bagian sama besar dan keseluruhan jelas. Pembilang memilih bagian, penyebut menyatakan pembagian keseluruhan."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jika anak memilih 1/4 lebih besar dari 1/2 karena angka 4, kembali ke pita sama panjang. Pengayaan: temukan pecahan senilai melalui lipatan.\nPeriksa pemodelan, langkah hitung, hasil/satuan dan penjelasan pemeriksaan. Jawaban akhir saja tidak cukup: minta anak menunjukkan gambar, benda atau alasan. Strategi lain yang benar diterima.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('8a1af13c-a1f9-59e5-a308-560e4b552067','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Faktor & Kelipatan Bilangan (FPB & KPK Dasar)','petualangan-matematika-kelas-4-bab-1',4,'B','Petualangan · Bab 1','sedang','draft',25,'{"summary":"Pulau Numeria bersama Kapten Rubi: Faktor & Kelipatan Bilangan (FPB & KPK Dasar). Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-matematika-4","mentor":"Kapten Rubi","chapter_number":1,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan mencari faktor dan kelipatan dengan contoh dan alasan.","Menjelaskan faktor persekutuan terbesar dengan contoh dan alasan.","Menjelaskan kelipatan persekutuan terkecil dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas IV","url":"https://buku.kemendikdasmen.go.id/katalog/Matematika-untuk-SDMI-Kelas-IV","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan mencari faktor dan kelipatan dengan contoh dan alasan.\n2. Menjelaskan faktor persekutuan terbesar dengan contoh dan alasan.\n3. Menjelaskan kelipatan persekutuan terkecil dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Faktor membagi suatu bilangan sampai habis. Kelipatan diperoleh dari perkalian dengan bilangan bulat. FPB berguna untuk membagi menjadi kelompok terbesar yang sama, sedangkan KPK dapat mencari pertemuan jadwal berulang."},{"type":"text","heading":"A. Mencari faktor dan kelipatan","body":"Buat pasangan perkalian untuk menemukan faktor positif. Faktor dari 12 muncul pada 1 × 12, 2 × 6, dan 3 × 4. Kelipatan positif 12 diperoleh dari 12 × 1, 12 × 2, dan seterusnya. Daftar faktor terbatas, sedangkan kelipatan dapat diteruskan. Nol dapat dipandang kelipatan, tetapi tidak dipakai saat mencari KPK positif."},{"type":"text","heading":"Contoh bertahap 1","body":"Faktor 12 adalah 1, 2, 3, 4, 6, 12. Beberapa kelipatan positif 4 adalah 4, 8, 12, 16, 20."},{"type":"text","heading":"B. Faktor persekutuan terbesar","body":"Daftarkan faktor kedua bilangan, pilih yang sama, lalu ambil yang paling besar. FPB dapat menunjukkan banyak paket identik maksimum yang dapat dibuat dari dua jenis benda tanpa sisa. Setiap paket harus mempunyai komposisi yang sama, bukan sekadar total benda yang sama."},{"type":"text","heading":"Contoh bertahap 2","body":"Faktor 18: 1, 2, 3, 6, 9, 18. Faktor 24: 1, 2, 3, 4, 6, 8, 12, 24. Faktor sama terbesar adalah 6. Jadi 18 kartu dan 24 stiker dapat menjadi enam paket identik."},{"type":"text","heading":"C. Kelipatan persekutuan terkecil","body":"Tuliskan kelipatan positif kedua bilangan sampai menemukan yang sama paling kecil. Pada cerita jadwal, tetapkan titik mulai yang sama dan cari lama sampai kedua kejadian bertemu lagi. Tidak semua cerita menggunakan KPK; periksa apakah situasinya pengulangan waktu atau pembentukan kelompok."},{"type":"text","heading":"Contoh bertahap 3","body":"Lampu A berkedip tiap 4 detik, B tiap 6 detik, mulai bersama. Kelipatan 4: 4, 8, 12; kelipatan 6: 6, 12. Keduanya bersama lagi setelah 12 detik."},{"type":"text","heading":"Kegiatan penerapan","body":"Gunakan kartu bilangan 1–30. Tandai faktor dua bilangan dengan warna berbeda dan cari irisannya. Pada garis waktu terpisah tandai lompatan dua jadwal untuk mencari pertemuan pertama. Jelaskan perbedaan kedua proses."},{"type":"text","heading":"Latihan mandiri","body":"1. Tuliskan faktor 16.\n2. Tentukan FPB 12 dan 20.\n3. Tentukan KPK 3 dan 5.\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. 1, 2, 4, 8, 16 Pasangannya 1×16, 2×8, dan 4×4.\n2. 4 Faktor sama 1, 2, 4; terbesar 4.\n3. 15 Kelipatan positif pertama yang sama adalah 15.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Faktor membagi habis, kelipatan berasal dari perkalian. FPB memilih faktor sama terbesar; KPK memilih kelipatan positif sama terkecil."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Gunakan daftar faktor untuk pembagian paket dan daftar kelipatan untuk jadwal. Jangan menentukan operasi hanya dari kata bersama; jelaskan besaran yang dicari.\nPeriksa pemodelan, langkah hitung, hasil/satuan dan penjelasan pemeriksaan. Jawaban akhir saja tidak cukup: minta anak menunjukkan gambar, benda atau alasan. Strategi lain yang benar diterima.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('3dd55558-3d71-5014-9b56-867364f661ef','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Pecahan Senilai, Desimal, & Persen','petualangan-matematika-kelas-4-bab-2',4,'B','Petualangan · Bab 2','sedang','draft',25,'{"summary":"Pulau Numeria bersama Kapten Rubi: Pecahan Senilai, Desimal, & Persen. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-matematika-4","mentor":"Kapten Rubi","chapter_number":2,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan pecahan senilai dengan contoh dan alasan.","Menjelaskan desimal persepuluhan dan perseratusan dengan contoh dan alasan.","Menjelaskan persen sebagai per seratus dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas IV","url":"https://buku.kemendikdasmen.go.id/katalog/Matematika-untuk-SDMI-Kelas-IV","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan pecahan senilai dengan contoh dan alasan.\n2. Menjelaskan desimal persepuluhan dan perseratusan dengan contoh dan alasan.\n3. Menjelaskan persen sebagai per seratus dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Pecahan, desimal, dan persen adalah cara berbeda menuliskan nilai. Gunakan satu keseluruhan yang sama, misalnya satu persegi seratus petak, agar hubungan nilainya terlihat."},{"type":"text","heading":"A. Pecahan senilai","body":"Kalikan atau bagi pembilang dan penyebut dengan bilangan bukan nol yang sama. Nilainya tetap karena keseluruhan dan bagian dipotong dengan perbandingan yang sama. Menambah angka sama pada pembilang dan penyebut bukan aturan pecahan senilai. Sederhanakan dengan membagi oleh faktor persekutuan."},{"type":"text","heading":"Contoh bertahap 1","body":"2/3 = 4/6 karena pembilang dan penyebut dikali 2. Pecahan 6/8 disederhanakan menjadi 3/4 dengan membagi keduanya oleh 2."},{"type":"text","heading":"B. Desimal persepuluhan dan perseratusan","body":"Angka pertama setelah koma menyatakan persepuluhan, yang kedua perseratusan. Pecahan 3/10 ditulis 0,3 dan 7/100 ditulis 0,07. Nol di akhir desimal tidak mengubah nilai: 0,5 = 0,50. Bandingkan dengan menyamakan banyak tempat desimal atau memakai model petak."},{"type":"text","heading":"Contoh bertahap 2","body":"Pada 0,46 ada empat persepuluhan dan enam perseratusan, total 46/100. Nilai 0,6 lebih besar daripada 0,46 karena 60/100 > 46/100."},{"type":"text","heading":"C. Persen sebagai per seratus","body":"Simbol % berarti per seratus. Ubah pecahan ke penyebut 100 jika memungkinkan, lalu tulis persennya. Ubah desimal ke persen dengan mengalikan nilai dengan 100 dan memberi simbol persen. Persen harus terkait suatu keseluruhan; 50% dari dua jumlah berbeda dapat memberi banyak yang berbeda."},{"type":"text","heading":"Contoh bertahap 3","body":"3/4 = 75/100 = 0,75 = 75%. Setengah dari 20 benda adalah 10 benda, sedangkan setengah dari 40 adalah 20 benda; keduanya tetap 50% kelompoknya."},{"type":"text","heading":"Kegiatan penerapan","body":"Warnai 25 dari seratus petak, lalu tulis sebagai pecahan sederhana, desimal, dan persen. Buat dua contoh lain dan minta pasangan menempatkannya pada garis bilangan 0–1."},{"type":"text","heading":"Latihan mandiri","body":"1. Sederhanakan 8/12.\n2. Ubah 0,4 ke persen.\n3. Mana lebih besar: 0,35 atau 0,5?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. 2/3 Bagi pembilang dan penyebut dengan 4.\n2. 40% 0,4 = 40/100.\n3. 0,5 0,5 = 0,50; 50 perseratus lebih besar dari 35 perseratus.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Pecahan senilai memakai perkalian/pembagian faktor sama. Desimal bergantung nilai tempat, dan persen berarti bagian dari seratus."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jangan membandingkan hanya jumlah digit: 0,8 lebih besar daripada 0,75. Kembali ke petak seratus. Pengayaan: persen suatu kumpulan dengan keseluruhan berbeda.\nPeriksa pemodelan, langkah hitung, hasil/satuan dan penjelasan pemeriksaan. Jawaban akhir saja tidak cukup: minta anak menunjukkan gambar, benda atau alasan. Strategi lain yang benar diterima.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('d667a1fa-8213-55a8-87c8-ad4066b47faf','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Keliling & Luas Bangun Datar','petualangan-matematika-kelas-4-bab-3',4,'B','Petualangan · Bab 3','sedang','draft',25,'{"summary":"Pulau Numeria bersama Kapten Rubi: Keliling & Luas Bangun Datar. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-matematika-4","mentor":"Kapten Rubi","chapter_number":3,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan keliling sebagai perjalanan di tepi dengan contoh dan alasan.","Menjelaskan luas dengan petak satuan dengan contoh dan alasan.","Menjelaskan segitiga dan bangun gabungan dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas IV","url":"https://buku.kemendikdasmen.go.id/katalog/Matematika-untuk-SDMI-Kelas-IV","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan keliling sebagai perjalanan di tepi dengan contoh dan alasan.\n2. Menjelaskan luas dengan petak satuan dengan contoh dan alasan.\n3. Menjelaskan segitiga dan bangun gabungan dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Keliling mengukur panjang batas, sedangkan luas mengukur daerah di dalam batas. Dua bangun dapat berkeliling sama namun luasnya berbeda. Tuliskan satuan yang sesuai agar kedua besaran tidak tertukar."},{"type":"text","heading":"A. Keliling sebagai perjalanan di tepi","body":"Telusuri seluruh batas satu kali dan jumlahkan panjang tiap sisi. Persegi dengan sisi s mempunyai keliling 4 × s. Persegi panjang dengan panjang p dan lebar l mempunyai keliling 2 × (p + l). Semua panjang harus dalam satuan yang sama sebelum dijumlahkan."},{"type":"text","heading":"Contoh bertahap 1","body":"Kebun persegi panjang 8 m × 5 m mempunyai batas 8 + 5 + 8 + 5 = 26 m. Angka 40 bukan kelilingnya karena 8 × 5 menghitung luas."},{"type":"text","heading":"B. Luas dengan petak satuan","body":"Tutupi daerah dengan petak sama besar tanpa celah atau tumpang tindih. Persegi panjang berisi l baris dengan p petak tiap baris sehingga luas p × l. Satuan luas ditulis persegi, misalnya cm². Persegi merupakan kasus p dan l sama: luas s × s."},{"type":"text","heading":"Contoh bertahap 2","body":"Kertas 7 cm × 4 cm dapat ditutup 28 petak masing-masing satu cm². Jadi luasnya 28 cm²; kelilingnya 22 cm."},{"type":"text","heading":"C. Segitiga dan bangun gabungan","body":"Dua segitiga kongruen dapat membentuk satu persegi panjang atau jajargenjang. Luas segitiga adalah setengah alas kali tinggi tegak lurus. Untuk daerah gabungan, pecah menjadi bagian tidak tumpang tindih, hitung lalu jumlahkan atau kurangi bagian yang hilang. Tinggi harus tegak lurus alas, bukan sembarang sisi miring."},{"type":"text","heading":"Contoh bertahap 3","body":"Segitiga dengan alas 10 cm dan tinggi 6 cm luasnya 1/2 × 10 × 6 = 30 cm². Memiringkan gambar tidak mengubah aturan alas-tinggi."},{"type":"text","heading":"Kegiatan penerapan","body":"Pada kertas petak, gambar dua persegi panjang berkeliling 20 satuan, misalnya 6×4 dan 7×3. Hitung luasnya dan jelaskan mengapa keliling sama tidak menjamin luas sama. Uji dengan menghitung petak."},{"type":"text","heading":"Latihan mandiri","body":"1. Persegi sisi 9 cm: keliling dan luas?\n2. Persegi panjang 12 m × 3 m: luas?\n3. Segitiga alas 8 cm tinggi 5 cm: luas?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. 36 cm dan 81 cm² Keliling 4×9; luas 9×9.\n2. 36 m² 12×3 petak persegi meter.\n3. 20 cm² Setengah dari 8×5.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Keliling menjumlah panjang batas. Luas menghitung petak daerah. Rumus berasal dari susunan bentuk, dan satuannya berbeda."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Minta siswa menyebut apakah pagar atau ubin yang dicari. Gunakan benang untuk batas dan petak untuk luas. Pengayaan: daerah berbentuk L dengan sisi yang belum tertulis.\nPeriksa pemodelan, langkah hitung, hasil/satuan dan penjelasan pemeriksaan. Jawaban akhir saja tidak cukup: minta anak menunjukkan gambar, benda atau alasan. Strategi lain yang benar diterima.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('53d82864-1fee-5115-a32f-bf1024de9e50','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Membaca Diagram Batang','petualangan-matematika-kelas-4-bab-4',4,'B','Petualangan · Bab 4','sedang','draft',25,'{"summary":"Pulau Numeria bersama Kapten Rubi: Membaca Diagram Batang. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-matematika-4","mentor":"Kapten Rubi","chapter_number":4,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan dari tabel ke diagram dengan contoh dan alasan.","Menjelaskan membaca skala dengan teliti dengan contoh dan alasan.","Menjelaskan membuat kesimpulan berbukti dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas IV","url":"https://buku.kemendikdasmen.go.id/katalog/Matematika-untuk-SDMI-Kelas-IV","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan dari tabel ke diagram dengan contoh dan alasan.\n2. Menjelaskan membaca skala dengan teliti dengan contoh dan alasan.\n3. Menjelaskan membuat kesimpulan berbukti dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Diagram batang menyajikan banyak data dengan panjang batang. Kita perlu membaca judul, sumbu, satuan, dan skala sebelum membandingkan. Tinggi batang saja belum cukup tanpa tahu angka skalanya."},{"type":"text","heading":"A. Dari tabel ke diagram","body":"Tentukan kategori pada satu sumbu dan frekuensi pada sumbu lainnya. Gunakan batang dengan lebar sama dan jarak yang konsisten. Untuk data kategori, batang terpisah membantu membedakan kelompok. Tuliskan judul dan satuan. Mulai skala frekuensi dari nol pada diagram sederhana supaya perbandingan panjang tidak menyesatkan."},{"type":"text","heading":"Contoh bertahap 1","body":"Tabel tanaman: cabai 8, tomat 6, terung 4. Buat tiga batang dengan tinggi 8, 6, dan 4 pada skala satu kotak satu tanaman."},{"type":"text","heading":"B. Membaca skala dengan teliti","body":"Lihat selisih dua tanda angka berurutan. Jika tanda sumbu adalah 0, 5, 10, 15, tiap interval bernilai lima. Hitung posisi ujung batang sesuai skala, bukan banyak garis tanpa memperhatikan nilainya. Sumbu yang dipotong atau tidak berawal nol perlu dijelaskan karena dapat memperbesar perbedaan tampak."},{"type":"text","heading":"Contoh bertahap 2","body":"Batang mencapai tanda ketiga setelah nol pada skala 0, 2, 4, 6. Nilainya 6, bukan 3. Skala satu kotak dua harus diterapkan untuk semua batang."},{"type":"text","heading":"C. Membuat kesimpulan berbukti","body":"Cari kategori terbesar/terkecil, total, dan selisih menggunakan nilai yang terbaca. Pisahkan temuan dari dugaan penyebab. Diagram penjualan tidak langsung menjelaskan mengapa suatu hari lebih laku. Batas sampel dan waktu pengumpulan perlu disebut supaya kesimpulan tidak meluas ke kelompok yang tidak diamati."},{"type":"text","heading":"Contoh bertahap 3","body":"Senin 12 buku, Selasa 18 buku, Rabu 10 buku. Total 40; Selasa terbanyak dan enam lebih banyak dari Senin. Alasan kenaikan belum diketahui dari diagram saja."},{"type":"text","heading":"Kegiatan penerapan","body":"Catat jumlah tiga jenis benda kelas tanpa data pribadi. Buat tabel dan dua diagram dengan skala satu dan dua jika sesuai. Minta pasangan membaca keduanya; hasil numeriknya harus tetap sama walau tinggi dalam kotak berbeda."},{"type":"text","heading":"Latihan mandiri","body":"1. Data A=14, B=8, C=10. Berapa total?\n2. Apa selisih A dan B?\n3. Satu interval bernilai 5. Batang empat interval dari nol bernilai?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. 32 14 + 8 + 10 = 32.\n2. 6 14 − 8 = 6.\n3. 20 4×5 = 20, bukan 4.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Judul, sumbu, skala dan satuan memberi makna diagram. Kesimpulan yang baik menyebut angka dan batas data."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jika siswa menghitung garis sebagai satuan, tuliskan nilai setiap tanda sumbu. Pengayaan: bandingkan dua diagram data sama dengan skala berbeda dan temukan potensi pembacaan menyesatkan.\nPeriksa pemodelan, langkah hitung, hasil/satuan dan penjelasan pemeriksaan. Jawaban akhir saja tidak cukup: minta anak menunjukkan gambar, benda atau alasan. Strategi lain yang benar diterima.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('e1c3d093-99ff-5cd2-994d-6f9d9c011050','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Penjumlahan & Pengurangan Pecahan Beda Penyebut','petualangan-matematika-kelas-5-bab-1',5,'C','Petualangan · Bab 1','sedang','draft',25,'{"summary":"Pulau Numeria bersama Kapten Rubi: Penjumlahan & Pengurangan Pecahan Beda Penyebut. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-matematika-5","mentor":"Kapten Rubi","chapter_number":1,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan mencari satuan pecahan bersama dengan contoh dan alasan.","Menjelaskan menjumlah dan mengurangi pembilang dengan contoh dan alasan.","Menjelaskan pecahan campuran dan pemeriksaan dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas V","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-v","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan mencari satuan pecahan bersama dengan contoh dan alasan.\n2. Menjelaskan menjumlah dan mengurangi pembilang dengan contoh dan alasan.\n3. Menjelaskan pecahan campuran dan pemeriksaan dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Menjumlahkan pecahan memerlukan satuan bagian yang sama. Setengah dan sepertiga tidak dapat langsung dihitung sebagai bagian sejenis. Gunakan pita atau petak untuk melihat mengapa penyebut perlu disamakan."},{"type":"text","heading":"A. Mencari satuan pecahan bersama","body":"Pecahan senilai mempunyai nilai sama walaupun tulisan berbeda. Pilih kelipatan bersama penyebut, kemudian kalikan pembilang dan penyebut dengan faktor yang sama. KPK biasanya memberi penyebut bersama terkecil sehingga hitungan lebih sederhana. Mengubah penyebut saja akan mengubah nilai."},{"type":"text","heading":"Contoh bertahap 1","body":"Untuk 1/4 dan 1/6, gunakan penyebut 12. Nilainya menjadi 3/12 dan 2/12. Keduanya sekarang memakai bagian berukuran seperdua belas."},{"type":"text","heading":"B. Menjumlah dan mengurangi pembilang","body":"Setelah penyebut sama, jumlahkan atau kurangi pembilangnya dan pertahankan penyebut. Penyebut menyatakan ukuran satu bagian, bukan banyak bagian yang terkumpul. Sederhanakan hasil jika mungkin. Pada pengurangan dalam bab ini pilih bilangan pertama tidak lebih kecil jika belum mempelajari pecahan negatif."},{"type":"text","heading":"Contoh bertahap 2","body":"2/3 + 1/4 = 8/12 + 3/12 = 11/12. Sementara 5/6 − 1/3 = 5/6 − 2/6 = 3/6 = 1/2."},{"type":"text","heading":"C. Pecahan campuran dan pemeriksaan","body":"Pecahan campuran terdiri atas bagian bulat dan pecahan. Ubah ke pecahan biasa dengan mengalikan bilangan bulat oleh penyebut lalu menambahkan pembilang. Hitung memakai penyebut bersama, lalu ubah kembali jika diperlukan. Perkirakan hasil dan bandingkan dengan pecahan awal agar kesalahan mudah terlihat."},{"type":"text","heading":"Contoh bertahap 3","body":"1 1/2 + 2/3 = 3/2 + 2/3 = 9/6 + 4/6 = 13/6 = 2 1/6. Hasil harus lebih besar dari 1 1/2 karena ditambah bilangan positif."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat dua pita satuan sama panjang. Tandai seperdua dan seperempat, lalu bagilah pita menjadi bagian yang sama untuk menunjukkan penjumlahan. Tuliskan perhitungan di bawah gambar dan jelaskan mengapa penyebut hasil bukan jumlah penyebut."},{"type":"text","heading":"Latihan mandiri","body":"1. Hitung 1/2 + 1/3.\n2. Hitung 3/4 − 1/6.\n3. Hitung 1 1/4 + 1/2.\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. 5/6 3/6 + 2/6 = 5/6.\n2. 7/12 9/12 − 2/12 = 7/12.\n3. 1 3/4 5/4 + 2/4 = 7/4.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Samakan ukuran bagian dengan pecahan senilai, operasikan pembilang, pertahankan penyebut, lalu sederhanakan dan periksa."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Kesalahan 1/2 + 1/3 = 2/5 dapat diuji dengan gambar: hasilnya harus lebih dari setengah, sedangkan 2/5 kurang dari setengah. Mulai dari penyebut berkelipatan dahulu.\nPeriksa pemodelan, langkah hitung, hasil/satuan dan penjelasan pemeriksaan. Jawaban akhir saja tidak cukup: minta anak menunjukkan gambar, benda atau alasan. Strategi lain yang benar diterima.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('6e4f72e4-241e-5cad-aff6-4349402da3a7','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Perkalian & Pembagian Pecahan','petualangan-matematika-kelas-5-bab-2',5,'C','Petualangan · Bab 2','sedang','draft',25,'{"summary":"Pulau Numeria bersama Kapten Rubi: Perkalian & Pembagian Pecahan. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-matematika-5","mentor":"Kapten Rubi","chapter_number":2,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan sebagian dari sebagian dengan contoh dan alasan.","Menjelaskan pembagian dan kebalikan dengan contoh dan alasan.","Menjelaskan menyederhanakan dan memeriksa dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas V","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-v","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan sebagian dari sebagian dengan contoh dan alasan.\n2. Menjelaskan pembagian dan kebalikan dengan contoh dan alasan.\n3. Menjelaskan menyederhanakan dan memeriksa dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Perkalian pecahan dapat dimaknai mengambil sebagian dari sebagian. Pembagian pecahan menanyakan berapa kali suatu bagian termuat. Model gambar membantu memahami prosedur sebelum memakai aturan hitung."},{"type":"text","heading":"A. Sebagian dari sebagian","body":"Untuk mengalikan dua pecahan, kalikan pembilang dengan pembilang dan penyebut dengan penyebut. Model persegi panjang menunjukkan daerah irisan dua pembagian. Jika faktor positif kurang dari satu, hasil perkalian lebih kecil dari bilangan yang dikalikan; perkalian tidak selalu memperbesar."},{"type":"text","heading":"Contoh bertahap 1","body":"Setengah dari tiga perempat kertas adalah 1/2 × 3/4 = 3/8. Bagi kertas menjadi empat kolom lalu dua baris; irisan mencakup tiga dari delapan petak."},{"type":"text","heading":"B. Pembagian dan kebalikan","body":"Membagi dengan pecahan bukan nol sama dengan mengalikan kebalikannya. Kebalikan a/b adalah b/a jika a bukan nol. Alasannya, kita mencari berapa kelompok berukuran pembagi yang termuat pada jumlah awal. Tidak perlu menyamakan penyebut untuk memakai aturan ini, walau model bagian sama dapat membantu pembuktian."},{"type":"text","heading":"Contoh bertahap 2","body":"Dua liter dibagi ke gelas berisi 1/4 liter menghasilkan 8 gelas: 2 ÷ 1/4 = 2 × 4 = 8. Membagi bilangan positif dengan bagian kurang dari satu dapat memperbesar hasil."},{"type":"text","heading":"C. Menyederhanakan dan memeriksa","body":"Ubah pecahan campuran menjadi pecahan biasa sebelum operasi. Sederhanakan faktor pembilang dan penyebut yang mempunyai faktor bersama, lalu kalikan. Pada pembagian balik hanya pecahan pembagi, bukan keduanya. Periksa dengan mengalikan hasil bagi oleh pembagi untuk kembali ke jumlah awal."},{"type":"text","heading":"Contoh bertahap 3","body":"1 1/2 ÷ 3/4 = 3/2 × 4/3 = 2. Pemeriksaan: 2 × 3/4 = 3/2 = 1 1/2."},{"type":"text","heading":"Kegiatan penerapan","body":"Gambar pita dua satuan dan tandai bagian seperdua. Hitung berapa bagian seperdua di dalam dua satuan, kemudian bandingkan dengan setengah dari dua. Jelaskan mengapa pembagian dan perkalian menghasilkan jawaban berbeda."},{"type":"text","heading":"Latihan mandiri","body":"1. Hitung 2/3 × 3/5.\n2. Hitung 3 ÷ 1/2.\n3. Hitung 5/6 ÷ 5/3.\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. 2/5 6/15 disederhanakan menjadi 2/5.\n2. 6 Ada enam bagian setengah dalam tiga satuan.\n3. 1/2 5/6 × 3/5 = 15/30.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Perkalian menghitung bagian dari bagian. Pembagian dengan pecahan bukan nol mengalikan kebalikan pembagi. Periksa makna dan ukuran hasil."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jangan membalik pecahan pertama pada pembagian. Jika hasil terasa aneh, gambarkan banyak gelas kecil dalam sejumlah liter. Pengayaan: soal campuran dengan satuan yang konsisten.\nPeriksa pemodelan, langkah hitung, hasil/satuan dan penjelasan pemeriksaan. Jawaban akhir saja tidak cukup: minta anak menunjukkan gambar, benda atau alasan. Strategi lain yang benar diterima.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('6cc2ce28-88d9-51c8-90b9-5dc3aa21375e','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Kecepatan, Jarak, dan Waktu','petualangan-matematika-kelas-5-bab-3',5,'C','Petualangan · Bab 3','sedang','draft',25,'{"summary":"Pulau Numeria bersama Kapten Rubi: Kecepatan, Jarak, dan Waktu. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-matematika-5","mentor":"Kapten Rubi","chapter_number":3,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan makna kecepatan rata-rata dengan contoh dan alasan.","Menjelaskan hubungan jarak, waktu, dan kecepatan dengan contoh dan alasan.","Menjelaskan konversi dan kewajaran hasil dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas V","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-v","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan makna kecepatan rata-rata dengan contoh dan alasan.\n2. Menjelaskan hubungan jarak, waktu, dan kecepatan dengan contoh dan alasan.\n3. Menjelaskan konversi dan kewajaran hasil dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Kecepatan rata-rata membandingkan jarak dengan waktu tempuh total. Gunakan cerita perjalanan rekaan; tidak perlu menguji kecepatan di jalan. Satuan jarak dan waktu harus sesuai sebelum dihitung."},{"type":"text","heading":"A. Makna kecepatan rata-rata","body":"Kecepatan rata-rata dihitung jarak total dibagi waktu total. Satuan km/jam menyatakan banyak kilometer yang setara ditempuh tiap jam secara rata-rata. Kecepatan sesaat dapat berubah sepanjang perjalanan. Jika soal memasukkan berhenti dalam waktu total, waktu berhenti harus ikut dihitung."},{"type":"text","heading":"Contoh bertahap 1","body":"Sebuah bus menempuh 120 km dalam 3 jam, termasuk waktu berhenti yang disebut soal. Kecepatan rata-ratanya 120 ÷ 3 = 40 km/jam."},{"type":"text","heading":"B. Hubungan jarak, waktu, dan kecepatan","body":"Jika kecepatan dianggap tetap, jarak = kecepatan × waktu dan waktu = jarak ÷ kecepatan. Rumus berasal dari pengulangan jarak setiap satuan waktu, bukan dari hafalan letak huruf. Tuliskan apa yang diketahui dan ditanya agar operasi yang dipilih sesuai."},{"type":"text","heading":"Contoh bertahap 2","body":"Sepeda bergerak rata-rata 12 km/jam selama 2 jam. Jarak 24 km. Untuk jarak 18 km pada laju sama, waktunya 18/12 = 1,5 jam."},{"type":"text","heading":"C. Konversi dan kewajaran hasil","body":"Satu jam sama dengan 60 menit, sehingga 30 menit adalah 1/2 jam dan 15 menit adalah 1/4 jam. Satu kilometer sama dengan 1000 meter. Jangan memakai 30 sebagai jam ketika satuan kecepatan km/jam. Periksa: pada laju sama, waktu dua kali lebih lama memberi jarak dua kali lebih jauh."},{"type":"text","heading":"Contoh bertahap 3","body":"Berjalan 6 km/jam selama 20 menit berarti 20/60 = 1/3 jam. Jaraknya 6 × 1/3 = 2 km, bukan 120 km."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat tabel perjalanan tokoh dengan laju tetap pada 15, 30, dan 60 menit. Gambar grafik jarak sederhana dan bandingkan pengaruh durasi. Jelaskan asumsi tidak ada perubahan laju pada model tersebut."},{"type":"text","heading":"Latihan mandiri","body":"1. Jarak 150 km dalam 3 jam. Kecepatan rata-rata?\n2. Laju 8 km/jam selama 45 menit. Jarak?\n3. Jarak 24 km pada 16 km/jam. Waktu?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. 50 km/jam 150 ÷ 3 = 50.\n2. 6 km 45/60 = 3/4 jam; 8×3/4 = 6.\n3. 1,5 jam 24 ÷ 16 = 1,5; setara 90 menit.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Kecepatan rata-rata = jarak total/waktu total. Samakan satuan, pilih hubungan yang sesuai, lalu periksa kewajaran hasil."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"0,5 jam bukan lima menit tetapi 30 menit. Pengayaan: kecepatan rata-rata dua ruas tidak selalu rata-rata aritmetika dua kecepatannya; gunakan jarak total dan waktu total.\nPeriksa pemodelan, langkah hitung, hasil/satuan dan penjelasan pemeriksaan. Jawaban akhir saja tidak cukup: minta anak menunjukkan gambar, benda atau alasan. Strategi lain yang benar diterima.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('6caaab65-b762-52ff-a5ea-aba5082fba75','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Volume Kubus dan Balok','petualangan-matematika-kelas-5-bab-4',5,'C','Petualangan · Bab 4','sedang','draft',25,'{"summary":"Pulau Numeria bersama Kapten Rubi: Volume Kubus dan Balok. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-matematika-5","mentor":"Kapten Rubi","chapter_number":4,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan kubus satuan dan lapisan dengan contoh dan alasan.","Menjelaskan kubus dan rusuk dengan contoh dan alasan.","Menjelaskan satuan dan ukuran yang belum diketahui dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas V","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-v","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan kubus satuan dan lapisan dengan contoh dan alasan.\n2. Menjelaskan kubus dan rusuk dengan contoh dan alasan.\n3. Menjelaskan satuan dan ukuran yang belum diketahui dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Volume mengukur ruang yang ditempati bangun. Satuan kubik berasal dari kubus satuan. Amati kotak tanpa memanjat atau membawa beban berat; buat model dengan balok ringan."},{"type":"text","heading":"A. Kubus satuan dan lapisan","body":"Isi model kotak dengan kubus berukuran sama tanpa celah. Hitung banyak kubus di dasar, lalu kalikan banyak lapisan. Balok panjang p, lebar l dan tinggi t mempunyai volume p × l × t karena tiap lapisan berisi p × l satuan dan ada t lapisan. Satuan panjang harus sama."},{"type":"text","heading":"Contoh bertahap 1","body":"Balok 5 cm × 3 cm × 4 cm memuat 15 kubus per lapisan dan empat lapisan. Volumenya 60 cm³."},{"type":"text","heading":"B. Kubus dan rusuk","body":"Kubus adalah balok dengan seluruh rusuk sama panjang. Jika rusuk s, volumenya s × s × s atau s³. Pangkat tiga bukan berarti mengalikan angka dengan tiga. Volume berbeda dari luas permukaan: volume mengisi bagian dalam, luas permukaan menutupi sisi luarnya."},{"type":"text","heading":"Contoh bertahap 2","body":"Kubus rusuk 4 cm bervolume 4×4×4 = 64 cm³, bukan 12 cm³. Satu lapis berisi 16 kubus dan ada empat lapis."},{"type":"text","heading":"C. Satuan dan ukuran yang belum diketahui","body":"Satu liter setara satu dm³ dan 1000 cm³. Ketika mencari tinggi, bagi volume oleh luas alas yang sesuai. Bedakan ukuran luar kotak dengan kapasitas dalam jika ketebalan dinding diketahui. Dalam soal dasar kita menggunakan ukuran ruang dalam atau mengabaikan ketebalan jika dinyatakan demikian."},{"type":"text","heading":"Contoh bertahap 3","body":"Kotak volume 120 cm³ mempunyai alas 6 cm × 5 cm. Tinggi = 120 ÷ 30 = 4 cm. Kapasitas 2000 cm³ setara 2 liter."},{"type":"text","heading":"Kegiatan penerapan","body":"Susun 24 kubus satuan menjadi beberapa balok, misalnya 6×2×2 dan 4×3×2. Catat ukuran dan volume. Jelaskan mengapa bentuk berubah tetapi volume tetap 24 satuan kubik."},{"type":"text","heading":"Latihan mandiri","body":"1. Balok 8 cm × 3 cm × 2 cm: volume?\n2. Kubus sisi 5 cm: volume?\n3. Volume 72 cm³, alas 6×4 cm. Tinggi?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. 48 cm³ 8×3 kubus per lapis, dua lapis.\n2. 125 cm³ 5×5×5 = 125.\n3. 3 cm 72 ÷ 24 = 3.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Volume balok = p×l×t, kubus = s³. Volume bersatuan kubik; kapasitas liter dapat dikonversi dengan hubungan 1 liter = 1000 cm³."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Minta siswa menunjuk satuan kubus, petak dan ruas untuk membedakan volume, luas dan panjang. Pengayaan: dua balok bervolume sama tetapi ukuran berbeda.\nPeriksa pemodelan, langkah hitung, hasil/satuan dan penjelasan pemeriksaan. Jawaban akhir saja tidak cukup: minta anak menunjukkan gambar, benda atau alasan. Strategi lain yang benar diterima.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('a99a50cd-6a45-5cc0-99dc-83c49694fa6e','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Operasi Hitung Bilangan Bulat (Positif & Negatif)','petualangan-matematika-kelas-6-bab-1',6,'C','Petualangan · Bab 1','sedang','draft',25,'{"summary":"Pulau Numeria bersama Kapten Rubi: Operasi Hitung Bilangan Bulat (Positif & Negatif). Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-matematika-6","mentor":"Kapten Rubi","chapter_number":1,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan garis bilangan dan urutan dengan contoh dan alasan.","Menjelaskan penjumlahan dan pengurangan dengan contoh dan alasan.","Menjelaskan perkalian, pembagian, dan urutan operasi dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas VI","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-vi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan garis bilangan dan urutan dengan contoh dan alasan.\n2. Menjelaskan penjumlahan dan pengurangan dengan contoh dan alasan.\n3. Menjelaskan perkalian, pembagian, dan urutan operasi dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Bilangan negatif membantu memodelkan nilai di bawah titik acuan, misalnya suhu atau lantai bawah tanah. Paket bilangan bulat negatif ini adalah topik pilihan aplikasi; penempatannya harus disesuaikan guru dengan CP dan kesiapan anak."},{"type":"text","heading":"A. Garis bilangan dan urutan","body":"Nol adalah titik acuan, bilangan positif berada di kanan dan negatif di kiri. Semakin ke kanan semakin besar nilainya. Jarak dari nol disebut nilai mutlak, sehingga −7 lebih kecil daripada −3 walaupun jaraknya dari nol lebih jauh. Angka negatif tidak selalu berarti benda buruk; artinya bergantung konteks."},{"type":"text","heading":"Contoh bertahap 1","body":"Suhu −2°C lebih tinggi daripada −6°C karena −2 berada lebih ke kanan. Jarak −6 dari nol adalah 6 satuan."},{"type":"text","heading":"B. Penjumlahan dan pengurangan","body":"Menambah bilangan positif bergerak ke kanan; menambah negatif bergerak ke kiri. Mengurangi suatu bilangan sama dengan menambahkan lawannya. Lawan 5 adalah −5 dan lawan −5 adalah 5. Gunakan langkah pada garis bilangan untuk memeriksa hasil sebelum memakai aturan singkat."},{"type":"text","heading":"Contoh bertahap 2","body":"−4 + 7 = 3: mulai −4, bergerak tujuh ke kanan. 3 − (−2) = 3 + 2 = 5. Mengurangi negatif berbeda dengan mengurangi positif."},{"type":"text","heading":"C. Perkalian, pembagian, dan urutan operasi","body":"Dua faktor dengan tanda sama menghasilkan positif; tanda berbeda menghasilkan negatif. Aturan yang sama berlaku untuk pembagian dengan pembagi bukan nol. Kerjakan kurung, lalu kali/bagi dari kiri ke kanan, lalu tambah/kurang dari kiri ke kanan. Nilai nol tidak memiliki tanda positif atau negatif."},{"type":"text","heading":"Contoh bertahap 3","body":"−3 × 4 = −12, sedangkan −3 × (−4) = 12. Pada −2 + 3 × 4, hitung perkalian dahulu sehingga hasilnya −2 + 12 = 10."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat garis bilangan −10 sampai 10 di kertas. Gunakan pion untuk memeragakan tambah positif, tambah negatif, dan kurang negatif. Teman membaca langkah sebelum kalian menulis hasil; jangan memakai percobaan suhu dingin ekstrem."},{"type":"text","heading":"Latihan mandiri","body":"1. Urutkan −1, −5, 2 dari kecil.\n2. Hitung −6 + 9.\n3. Hitung 8 − (−3).\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. −5, −1, 2 Posisi kiri menunjukkan nilai lebih kecil.\n2. 3 Sembilan langkah ke kanan dari −6.\n3. 11 Mengurangi negatif tiga sama dengan menambah tiga.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Urutan mengikuti posisi pada garis bilangan. Kurang berarti tambah lawan. Kali/bagi ditentukan tanda dan urutan operasi tetap berlaku."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Bedakan tanda negatif pada bilangan dengan tanda operasi kurang. Jika aturan tanda dihafal tanpa makna, kembali ke pola perkalian dan garis bilangan.\nPeriksa pemodelan, langkah hitung, hasil/satuan dan penjelasan pemeriksaan. Jawaban akhir saja tidak cukup: minta anak menunjukkan gambar, benda atau alasan. Strategi lain yang benar diterima.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('364c064a-8c9f-561a-9a8f-9079d6bcfc35','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Unsur, Keliling, & Luas Lingkaran','petualangan-matematika-kelas-6-bab-2',6,'C','Petualangan · Bab 2','sedang','draft',25,'{"summary":"Pulau Numeria bersama Kapten Rubi: Unsur, Keliling, & Luas Lingkaran. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-matematika-6","mentor":"Kapten Rubi","chapter_number":2,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan pusat, jari-jari, dan diameter dengan contoh dan alasan.","Menjelaskan keliling dan bilangan pi dengan contoh dan alasan.","Menjelaskan luas dan bagian lingkaran dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas VI","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-vi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan pusat, jari-jari, dan diameter dengan contoh dan alasan.\n2. Menjelaskan keliling dan bilangan pi dengan contoh dan alasan.\n3. Menjelaskan luas dan bagian lingkaran dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Lingkaran adalah himpunan titik pada bidang yang berjarak sama dari pusat. Keliling dan luas lingkaran dalam paket ini merupakan perluasan pilihan; guru perlu meninjau penempatan topik dan pendekatan sebelum dipublikasikan."},{"type":"text","heading":"A. Pusat, jari-jari, dan diameter","body":"Jari-jari r menghubungkan pusat ke batas lingkaran. Diameter d melewati pusat dan menghubungkan dua titik batas, sehingga d = 2r. Tali busur menghubungkan dua titik batas tetapi tidak selalu melalui pusat. Semua diameter adalah tali busur, tetapi tidak semua tali busur diameter."},{"type":"text","heading":"Contoh bertahap 1","body":"Jika jari-jari tutup bundar 7 cm, diameternya 14 cm. Garis yang menghubungkan dua titik tepi tanpa melewati pusat bukan diameter."},{"type":"text","heading":"B. Keliling dan bilangan pi","body":"Perbandingan keliling dengan diameter selalu pi (π), sehingga K = πd = 2πr. Pi bilangan tak berhingga yang tidak berulang; 3,14 dan 22/7 adalah pendekatan, bukan nilai tepat pi. Gunakan pendekatan yang diminta soal dan tulis satuan panjang."},{"type":"text","heading":"Contoh bertahap 2","body":"Dengan π≈22/7 dan diameter 14 cm, keliling ≈22/7 ×14 = 44 cm. Pengukuran benang sekeliling benda hanya memberi perkiraan karena ketelitian alat."},{"type":"text","heading":"C. Luas dan bagian lingkaran","body":"Luas lingkaran L = πr². Pastikan yang dikuadratkan adalah jari-jari, bukan diameter. Luas setengah lingkaran adalah setengah luas penuh. Namun keliling setengah daerah lingkaran meliputi busur setengah keliling ditambah diameter lurus; jangan menyamakan keliling dengan panjang busur saja."},{"type":"text","heading":"Contoh bertahap 3","body":"r=10 cm dan π≈3,14 memberi luas ≈314 cm². Keliling daerah setengah lingkaran r=7 dengan π≈22/7 adalah 22 + 14 = 36 cm."},{"type":"text","heading":"Kegiatan penerapan","body":"Ukur diameter dan keliling tiga benda bundar aman memakai benang dan penggaris. Bagi keliling dengan diameter lalu bandingkan hasil mendekati 3,14. Catat kemungkinan galat pengukuran; jangan menuntut semua hasil tepat sama."},{"type":"text","heading":"Latihan mandiri","body":"1. Diameter 18 cm. Berapa jari-jari?\n2. r=7 cm, π≈22/7. Luas?\n3. d=20 cm, π≈3,14. Keliling?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. 9 cm r = d/2.\n2. 154 cm² 22/7×7×7 = 154.\n3. 62,8 cm 3,14×20 = 62,8.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Diameter dua kali jari-jari. K=πd dan L=πr². Pi pada hitungan dasar didekati; keliling bagian lingkaran mencakup semua batasnya."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Tandai r dan d pada gambar sebelum menghitung. Pengayaan: bandingkan pertambahan keliling dan luas ketika jari-jari digandakan.\nPeriksa pemodelan, langkah hitung, hasil/satuan dan penjelasan pemeriksaan. Jawaban akhir saja tidak cukup: minta anak menunjukkan gambar, benda atau alasan. Strategi lain yang benar diterima.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('8a2dd75c-ad8a-5576-a3c7-f3ee370b4bb6','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Gabungan Bangun Ruang','petualangan-matematika-kelas-6-bab-3',6,'C','Petualangan · Bab 3','sedang','draft',25,'{"summary":"Pulau Numeria bersama Kapten Rubi: Gabungan Bangun Ruang. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-matematika-6","mentor":"Kapten Rubi","chapter_number":3,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan memecah menjadi bagian tidak tumpang tindih dengan contoh dan alasan.","Menjelaskan menentukan ukuran yang belum tertulis dengan contoh dan alasan.","Menjelaskan luas permukaan dan bidang pertemuan dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas VI","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-vi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan memecah menjadi bagian tidak tumpang tindih dengan contoh dan alasan.\n2. Menjelaskan menentukan ukuran yang belum tertulis dengan contoh dan alasan.\n3. Menjelaskan luas permukaan dan bidang pertemuan dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Bangun ruang gabungan dapat dipecah menjadi bangun yang lebih sederhana. Gambar, ukuran dan bagian yang saling menempel perlu jelas. Volume dan luas permukaan membutuhkan cara penghitungan berbeda."},{"type":"text","heading":"A. Memecah menjadi bagian tidak tumpang tindih","body":"Pilih potongan yang membentuk balok atau kubus dengan ukuran diketahui. Volume gabungan adalah jumlah volume bagian yang tidak bertumpang tindih. Jika sebuah bagian dihitung dua kali, kurangi volume irisan. Untuk bangun berlubang, kurangi volume lubang dari bangun penuh. Satuan semua ukuran harus sama."},{"type":"text","heading":"Contoh bertahap 1","body":"Dua balok 6×4×3 cm dan 2×4×3 cm ditempel berdampingan tanpa irisan. Volume 72 + 24 = 96 cm³. Panjang gabungan pada arah itu menjadi 8 cm."},{"type":"text","heading":"B. Menentukan ukuran yang belum tertulis","body":"Gunakan hubungan panjang total dan bagian. Jika panjang keseluruhan 12 dan satu bagian 7, bagian lainnya 5. Tandai arah panjang, lebar dan tinggi pada sketsa. Sisi yang tidak terlihat tetap mempunyai ukuran dan tidak boleh diabaikan. Buat tabel dimensi tiap komponen sebelum menggunakan rumus."},{"type":"text","heading":"Contoh bertahap 2","body":"Bangun berbentuk L berasal dari balok 10×6×4 yang dipotong bagian 3×2×4. Volume penuh 240, potongan 24, sisa 216 cm³."},{"type":"text","heading":"C. Luas permukaan dan bidang pertemuan","body":"Permukaan yang saling menempel menjadi bagian dalam dan tidak termasuk permukaan luar gabungan. Untuk dua bangun yang menempel tepat pada satu bidang, jumlahkan luas permukaannya lalu kurangi dua kali luas bidang pertemuan. Rumus ini berbeda dari volume, sebab volume bagian menempel tidak hilang jika tidak ada irisan."},{"type":"text","heading":"Contoh bertahap 3","body":"Dua kubus rusuk 2 cm ditempel satu sisi. Luas permukaan awal 24+24=48 cm². Bidang pertemuan 4 cm² dihitung dua kali; permukaan luar 48−8=40 cm²."},{"type":"text","heading":"Kegiatan penerapan","body":"Tempel dua kotak identik dengan perekat yang mudah dilepas. Warnai hanya bidang yang masih terlihat. Buat sketsa pemecahan, hitung volume dan diskusikan sisi yang tidak boleh dihitung dalam luas permukaan luar."},{"type":"text","heading":"Latihan mandiri","body":"1. Balok 4×3×2 dan 2×3×2 ditempel tanpa irisan. Volume?\n2. Kubus sisi 5 dilubangi balok 1×1×5. Volume sisa?\n3. Dua kubus sisi 3 menempel satu sisi. Luas permukaan luar?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. 36 satuan³ 24 + 12 = 36.\n2. 120 satuan³ 125 − 5 = 120.\n3. 90 satuan² 54 + 54 − 2×9 = 90.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Volume gabungan menjumlah bagian tanpa irisan atau mengurangi lubang. Luas permukaan hanya menghitung bidang luar; bidang pertemuan dikeluarkan."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jangan mengurangi bidang pertemuan dari volume karena bidang tidak mempunyai ketebalan. Pengayaan: cari beberapa pemecahan yang menghasilkan volume sama.\nPeriksa pemodelan, langkah hitung, hasil/satuan dan penjelasan pemeriksaan. Jawaban akhir saja tidak cukup: minta anak menunjukkan gambar, benda atau alasan. Strategi lain yang benar diterima.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('01df5f0b-5572-5669-8008-01e7dd5cd7ac','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Statistika Dasar: Mean, Median, Modus','petualangan-matematika-kelas-6-bab-4',6,'C','Petualangan · Bab 4','sedang','draft',25,'{"summary":"Pulau Numeria bersama Kapten Rubi: Statistika Dasar: Mean, Median, Modus. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-matematika-6","mentor":"Kapten Rubi","chapter_number":4,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan mean atau rata-rata dengan contoh dan alasan.","Menjelaskan median atau nilai tengah dengan contoh dan alasan.","Menjelaskan modus dan pemilihan ukuran dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas VI","url":"https://buku.kemendikdasmen.go.id/katalog/matematika-untuk-sdmi-kelas-vi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan mean atau rata-rata dengan contoh dan alasan.\n2. Menjelaskan median atau nilai tengah dengan contoh dan alasan.\n3. Menjelaskan modus dan pemilihan ukuran dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Mean, median, dan modus merangkum data dengan cara berbeda. Topik ini disertakan sebagai pilihan pendalaman dan perlu ditinjau penempatan fasenya. Selalu baca konteks dan seluruh data sebelum memilih ukuran yang mewakili."},{"type":"text","heading":"A. Mean atau rata-rata","body":"Jumlahkan seluruh nilai lalu bagi banyak data. Mean menggambarkan pembagian total secara merata, bukan selalu satu nilai yang benar-benar ada pada data. Perhatikan satuan dan pastikan setiap data dihitung sekali. Nilai sangat besar atau kecil dapat menarik mean sehingga kurang mewakili nilai kebanyakan."},{"type":"text","heading":"Contoh bertahap 1","body":"Data 4, 6, 8 mempunyai jumlah 18 dan banyak data 3. Mean = 18/3 = 6. Data 2, 2, 20 mempunyai mean 8 meski dua dari tiga nilainya hanya 2."},{"type":"text","heading":"B. Median atau nilai tengah","body":"Urutkan data dari kecil terlebih dahulu. Jika banyak data ganjil, ambil satu nilai tepat di tengah. Jika genap, hitung rata-rata dua nilai tengah. Median bergantung urutan posisi, bukan nilai pada daftar asli yang belum diurutkan. Menambah nilai ekstrem sering memengaruhi mean lebih besar daripada median."},{"type":"text","heading":"Contoh bertahap 2","body":"Data 9, 3, 7, 5 diurutkan 3, 5, 7, 9. Dua nilai tengah 5 dan 7 sehingga median 6. Median tidak harus muncul sebagai nilai asli."},{"type":"text","heading":"C. Modus dan pemilihan ukuran","body":"Modus adalah nilai atau kategori yang paling sering muncul. Data dapat memiliki satu modus, lebih dari satu modus, atau tidak mempunyai modus tunggal bila semua frekuensi sama. Untuk ukuran baju, modus sering berguna karena menunjukkan ukuran paling banyak diminta. Jangan menyebut nilai terbesar sebagai modus kecuali memang paling sering."},{"type":"text","heading":"Contoh bertahap 3","body":"Data 2, 3, 3, 4, 4, 5 memiliki dua modus: 3 dan 4. Pada data 1, 2, 3 masing-masing muncul sekali sehingga tidak ada modus tunggal."},{"type":"text","heading":"Kegiatan penerapan","body":"Gunakan delapan kartu angka rekaan, bukan nilai pribadi teman. Hitung ketiga ukuran lalu ganti satu kartu dengan angka jauh lebih besar. Bandingkan perubahan mean, median, dan modus serta jelaskan ukuran mana yang lebih mewakili data itu."},{"type":"text","heading":"Latihan mandiri","body":"1. Mean dari 5, 7, 9?\n2. Median 8, 2, 6, 4?\n3. Modus 1, 2, 2, 3, 4?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. 7 Jumlah 21 dibagi tiga data.\n2. 5 Urut 2,4,6,8; (4+6)/2 = 5.\n3. 2 Angka 2 muncul dua kali, lainnya sekali.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Mean membagi total dengan banyak data; median memerlukan urutan; modus memakai frekuensi. Pilih ukuran berdasarkan kebutuhan dan sebaran data."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Hitung banyak data, bukan banyak nilai berbeda, untuk penyebut mean. Pengayaan: data dua modus atau data ekstrem yang mengubah mean tetapi tidak banyak mengubah median.\nPeriksa pemodelan, langkah hitung, hasil/satuan dan penjelasan pemeriksaan. Jawaban akhir saja tidak cukup: minta anak menunjukkan gambar, benda atau alasan. Strategi lain yang benar diterima.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('e66cf113-53b6-51b1-93fb-e1e67099af61','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Bunyi Huruf & Suku Kata','petualangan-bahasa-indonesia-kelas-1-bab-1',1,'A','Petualangan · Bab 1','dasar','draft',20,'{"summary":"Pulau Kata bersama Bobo: Bunyi Huruf & Suku Kata. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-bahasa-indonesia-1","mentor":"Bobo","chapter_number":1,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan bunyi dan lambang huruf dengan contoh dan alasan.","Menjelaskan merangkai suku kata dengan contoh dan alasan.","Menjelaskan membaca untuk memahami dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Bahasa Indonesia: Aku Bisa! (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-aku-bisa-untuk-sd-mi-kelas-i-edisi-revisi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan bunyi dan lambang huruf dengan contoh dan alasan.\n2. Menjelaskan merangkai suku kata dengan contoh dan alasan.\n3. Menjelaskan membaca untuk memahami dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Bobo mengajakmu mendengar bunyi lalu menghubungkannya dengan tulisan. Pendamping boleh membacakan petunjuk. Tidak perlu terburu-buru: ucapkan, tunjuk, rangkai, lalu pahami kata yang dibaca."},{"type":"text","heading":"A. Bunyi dan lambang huruf","body":"Huruf adalah lambang yang mewakili bunyi bahasa. Nama huruf berbeda dari bunyinya di dalam kata. Kenali vokal a, i, u, e, o dan konsonan seperti b, m, s. Dengarkan bunyi awal kata, lalu cari lambangnya. Cara mengucapkan e dapat berbeda menurut kata; pendamping memberi contoh lisan."},{"type":"text","heading":"Contoh bertahap 1","body":"Kata mata dimulai bunyi /m/ yang ditulis m. Pada kata susu, dengarkan bunyi awal /s/. Ucapkan kata utuh dahulu agar bunyinya bermakna."},{"type":"text","heading":"B. Merangkai suku kata","body":"Suku kata adalah bagian kata yang diucapkan dalam satu ketukan. Rangkai konsonan dengan vokal secara perlahan, kemudian satukan tanpa jeda panjang. Tepukan membantu menemukan suku kata, tetapi membaca tetap perlu memperhatikan seluruh huruf. Mulailah dari pola sederhana sebelum gabungan yang lebih rumit."},{"type":"text","heading":"Contoh bertahap 2","body":"b bertemu u menjadi bu; k bertemu u menjadi ku. Rangkaikan bu-ku menjadi buku. Kata mama dapat ditepuk ma-ma, dua suku kata."},{"type":"text","heading":"C. Membaca untuk memahami","body":"Setelah bunyi dirangkai, tanyakan arti kata dan tunjuk benda atau gambar yang sesuai. Jangan menebak hanya dari gambar atau huruf pertama karena kata dapat mirip. Baca lagi seluruh kata lalu pakai dalam kalimat pendek. Kesalahan boleh diperbaiki dengan kembali menunjuk huruf satu per satu."},{"type":"text","heading":"Contoh bertahap 3","body":"batu dan bata sama-sama dimulai ba, tetapi huruf terakhir berbeda. Kalimat Aku melihat batu membantu menghubungkan tulisan batu dengan maknanya."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat kartu m, b, t dan vokal a, i, u. Rangkai kata bermakna seperti ibu, mata, atau ubi dengan bantuan pendamping. Tunjuk setiap suku kata ketika membaca dan ceritakan artinya. Jangan menilai anak dari kecepatan saja."},{"type":"text","heading":"Latihan mandiri","body":"1. Tepuk suku kata sapi.\n2. Rangkai bo dan la.\n3. Huruf awal kata meja?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. sa-pi Kata sapi mempunyai dua ketukan.\n2. bola Dua suku kata disatukan menjadi kata bermakna.\n3. m Bunyinya /m/ pada awal meja.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Dengarkan bunyi, cocokkan huruf, rangkai suku kata, lalu pahami kata. Gambar membantu makna tetapi bukan pengganti membaca huruf."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jika anak menyebut nama huruf tetapi belum merangkai, contohkan bunyinya dalam kata. Gunakan dua suku kata sederhana dahulu; pengayaan berupa membedakan dua kata mirip.\nNilai pemahaman dengan bukti teks, keruntutan gagasan, ketepatan bahasa dan perbaikan setelah umpan balik. Tugas berbicara/menulis dinilai dari karya atau penyampaian, bukan skor pilihan ganda saja; bentuk lisan/dikte/alat bantu dapat disesuaikan.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('f26101dc-a030-5a80-ba41-9f131a9b3498','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Kosakata Anggota Tubuh & Keluarga','petualangan-bahasa-indonesia-kelas-1-bab-2',1,'A','Petualangan · Bab 2','dasar','draft',20,'{"summary":"Pulau Kata bersama Bobo: Kosakata Anggota Tubuh & Keluarga. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-bahasa-indonesia-1","mentor":"Bobo","chapter_number":2,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan nama anggota tubuh dan kegunaannya dengan contoh dan alasan.","Menjelaskan kosakata keluarga dan pendamping dengan contoh dan alasan.","Menjelaskan menyusun kalimat pengenalan dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Bahasa Indonesia: Aku Bisa! (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-aku-bisa-untuk-sd-mi-kelas-i-edisi-revisi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan nama anggota tubuh dan kegunaannya dengan contoh dan alasan.\n2. Menjelaskan kosakata keluarga dan pendamping dengan contoh dan alasan.\n3. Menjelaskan menyusun kalimat pengenalan dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Kata membantu kita menyebut bagian tubuh dan orang yang merawat atau hidup bersama kita. Susunan keluarga dapat berbeda. Gunakan sebutan yang sesuai keluargamu tanpa membagikan alamat atau nomor telepon."},{"type":"text","heading":"A. Nama anggota tubuh dan kegunaannya","body":"Sebutkan bagian tubuh yang terlihat seperti kepala, tangan, kaki, mata, telinga dan hidung. Hubungkan kata dengan kegunaan dalam kalimat. Tidak semua orang melakukan kegiatan dengan cara sama; seseorang dapat menggunakan alat bantu atau bantuan orang lain. Bahasa yang sopan menghargai setiap tubuh."},{"type":"text","heading":"Contoh bertahap 1","body":"Tangan memegang kartu. Kaki membantu berdiri atau bergerak. Kalimat Aku memakai tangan untuk menggambar menyebut bagian tubuh dan kegiatan, bukan hanya nama bendanya."},{"type":"text","heading":"B. Kosakata keluarga dan pendamping","body":"Kata ibu, ayah, kakak, adik, nenek, kakek atau wali menunjukkan hubungan dalam keluarga. Kakak biasanya lebih tua daripada orang yang menyebutnya, adik lebih muda. Sebutan bergantung hubungan pembicara. Jangan menganggap semua anak tinggal dengan anggota keluarga yang sama."},{"type":"text","heading":"Contoh bertahap 2","body":"Rani berkata Lala kakakku karena Lala lebih tua darinya. Lala dapat menyebut Rani adikku. Keduanya menceritakan hubungan yang sama dari sudut berbeda."},{"type":"text","heading":"C. Menyusun kalimat pengenalan","body":"Kalimat sederhana dapat menyebut siapa, melakukan apa, dan bila perlu benda atau tempat kegiatan. Gunakan huruf kapital di awal dan titik di akhir kalimat berita. Pilih informasi yang aman dibagikan. Dengarkan teman sampai selesai dan tanyakan dengan sopan bila ada kata yang belum dikenal."},{"type":"text","heading":"Contoh bertahap 3","body":"Nenek membaca buku. Kata Nenek menyebut pelaku, membaca kegiatan, dan buku benda yang dibaca. Kita boleh memperkenalkan diri dengan nama panggilan dan hobi saja."},{"type":"text","heading":"Kegiatan penerapan","body":"Gambar tokoh keluarga rekaan atau orang yang mendampingimu tanpa data pribadi. Beri label hubungan dan tulis dua kalimat kegiatan. Pasangan menunjuk kata anggota tubuh pada gambar karakter dan menjelaskan kegunaannya dengan bahasa menghargai."},{"type":"text","heading":"Latihan mandiri","body":"1. Lengkapi: Kita mendengar bunyi dengan …\n2. Seseorang lebih muda dariku dalam hubungan saudara disebut …\n3. Buat kalimat memakai kata kakek.\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. telinga Kata itu menyebut indra pendengaran.\n2. adik Adik menunjukkan saudara yang lebih muda.\n3. Contoh: Kakek menyiram tanaman. Kalimat menyebut pelaku dan kegiatan; contoh lain yang masuk akal diterima.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Kosakata tubuh menyebut bagian dan kegunaannya. Sebutan keluarga menunjukkan hubungan. Kalimat pengenalan memakai informasi yang aman dan bahasa sopan."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Pendamping menerima variasi keluarga dan cara bergerak anak. Bila anak hanya memberi satu kata, bantu dengan pola siapa melakukan apa. Pengayaan: tambahkan keterangan waktu.\nNilai pemahaman dengan bukti teks, keruntutan gagasan, ketepatan bahasa dan perbaikan setelah umpan balik. Tugas berbicara/menulis dinilai dari karya atau penyampaian, bukan skor pilihan ganda saja; bentuk lisan/dikte/alat bantu dapat disesuaikan.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('ab59c6b1-aaee-5d6f-a5d3-307db035716a','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Membaca Cerita Bergambar','petualangan-bahasa-indonesia-kelas-1-bab-3',1,'A','Petualangan · Bab 3','dasar','draft',20,'{"summary":"Pulau Kata bersama Bobo: Membaca Cerita Bergambar. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-bahasa-indonesia-1","mentor":"Bobo","chapter_number":3,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan mengamati gambar dan membaca teks dengan contoh dan alasan.","Menjelaskan mengurutkan awal, tengah, akhir dengan contoh dan alasan.","Menjelaskan menceritakan kembali dengan kata sendiri dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Bahasa Indonesia: Aku Bisa! (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-aku-bisa-untuk-sd-mi-kelas-i-edisi-revisi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan mengamati gambar dan membaca teks dengan contoh dan alasan.\n2. Menjelaskan mengurutkan awal, tengah, akhir dengan contoh dan alasan.\n3. Menjelaskan menceritakan kembali dengan kata sendiri dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Cerita bergambar memakai tulisan dan gambar untuk membantu menyampaikan kejadian. Kita akan membaca kisah orisinal pendek: Nia membawa biji. Ia menanamnya di pot. Setiap pagi Nia menyiram secukupnya. Beberapa hari kemudian muncul tunas."},{"type":"image","url":"/assets/petualangan-cerita-nia.svg","caption":"Cerita Nia: menanam biji, merawat, lalu muncul tunas setelah beberapa hari."},{"type":"text","heading":"A. Mengamati gambar dan membaca teks","body":"Perhatikan tokoh, benda dan tempat pada gambar, lalu baca tulisan yang menyertainya. Gambar memberi petunjuk, tetapi tidak semua informasi boleh ditebak. Bedakan yang terlihat jelas, yang tertulis, dan yang baru dugaanmu. Jika gambar dan dugaan berbeda, kembali ke bukti tulisan."},{"type":"text","heading":"Contoh bertahap 1","body":"Jika gambar menunjukkan pot dan teks menyebut Nia menanam biji, kita tahu yang ditanam biji. Warna bunga masa depan belum dapat diketahui karena belum disebutkan."},{"type":"text","heading":"B. Mengurutkan awal, tengah, akhir","body":"Tanyakan kejadian apa yang terjadi lebih dulu. Kata lalu, setelah itu, kemudian membantu melihat urutan. Pada cerita Nia, menanam mendahului merawat, dan tunas muncul setelah beberapa hari. Urutan yang masuk akal tidak selalu sama dengan urutan gambar yang diacak; cocokkan dengan teks."},{"type":"text","heading":"Contoh bertahap 2","body":"Awal: Nia membawa biji. Tengah: ia menanam dan merawat. Akhir: tunas muncul. Tunas tidak muncul sebelum biji ditanam dalam kisah tersebut."},{"type":"text","heading":"C. Menceritakan kembali dengan kata sendiri","body":"Sebut tokoh dan kejadian penting, kemudian ceritakan berurutan dalam kalimat pendek. Jangan harus menghafal semua kata. Gunakan pertanyaan siapa, apa dan bagaimana sebagai bantuan. Perasaan tokoh dapat ditafsirkan jika ada bukti; katakan mungkin bila belum jelas, bukan mengaku pasti."},{"type":"text","heading":"Contoh bertahap 3","body":"Nia menanam biji dan menyiramnya. Setelah beberapa hari, biji bertunas. Dua kalimat ini mempertahankan kejadian utama tanpa menyalin seluruh bacaan."},{"type":"text","heading":"Kegiatan penerapan","body":"Gambar tiga panel cerita berbeda tentang mengembalikan buku: meminjam, membaca, mengembalikan. Tulis satu kalimat tiap panel. Acak urutan dan minta teman menyusunnya serta menjelaskan bukti kata/gambar."},{"type":"text","heading":"Latihan mandiri","body":"1. Siapa tokoh pada cerita Nia?\n2. Apa yang terjadi sebelum tunas muncul?\n3. Apakah teks memastikan warna bunga?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Nia Namanya disebut sebagai pelaku kegiatan.\n2. Biji ditanam dan dirawat. Teks menyebut kegiatan itu lebih dahulu.\n3. Tidak Belum ada informasi bunga atau warnanya.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Cocokkan gambar dengan tulisan, temukan urutan, dan ceritakan kembali kejadian penting. Pisahkan bukti dari dugaan."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jika anak menebak dari gambar saja, tutup gambar sebentar dan baca kata bersama. Pengayaan: buat akhir alternatif dengan menandainya sebagai karangan baru.\nNilai pemahaman dengan bukti teks, keruntutan gagasan, ketepatan bahasa dan perbaikan setelah umpan balik. Tugas berbicara/menulis dinilai dari karya atau penyampaian, bukan skor pilihan ganda saja; bentuk lisan/dikte/alat bantu dapat disesuaikan.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('5290774d-c914-5402-a442-fbc48eb9f01d','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Kalimat Tanya & Tanda Baca Dasar','petualangan-bahasa-indonesia-kelas-1-bab-4',1,'A','Petualangan · Bab 4','dasar','draft',20,'{"summary":"Pulau Kata bersama Bobo: Kalimat Tanya & Tanda Baca Dasar. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-bahasa-indonesia-1","mentor":"Bobo","chapter_number":4,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan memilih kata tanya dengan contoh dan alasan.","Menjelaskan titik, tanda tanya, tanda seru dengan contoh dan alasan.","Menjelaskan menjawab sesuai pertanyaan dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Bahasa Indonesia: Aku Bisa! (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-aku-bisa-untuk-sd-mi-kelas-i-edisi-revisi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan memilih kata tanya dengan contoh dan alasan.\n2. Menjelaskan titik, tanda tanya, tanda seru dengan contoh dan alasan.\n3. Menjelaskan menjawab sesuai pertanyaan dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Kalimat tanya digunakan untuk meminta informasi. Tanda baca membantu pembaca memahami tujuan dan jeda tulisan. Bacalah kalimat dengan suara wajar dan perhatikan jawaban seperti apa yang diminta."},{"type":"text","heading":"A. Memilih kata tanya","body":"Siapa menanyakan orang, apa menanyakan benda atau kejadian, di mana tempat, kapan waktu, mengapa alasan, dan bagaimana cara atau keadaan. Pilih sesuai informasi yang ingin diketahui. Bertanya harus sopan dan tidak memaksa orang membuka rahasia pribadi."},{"type":"text","heading":"Contoh bertahap 1","body":"Di mana buku itu? meminta tempat. Mengapa tanaman disiram? meminta alasan. Kedua pertanyaan tidak dapat dijawab dengan nama orang saja."},{"type":"text","heading":"B. Titik, tanda tanya, tanda seru","body":"Kalimat berita sederhana diakhiri titik. Pertanyaan langsung diakhiri tanda tanya. Tanda seru dapat menunjukkan perintah, seruan atau emosi kuat, tetapi tidak harus dipakai pada setiap kalimat. Huruf pertama kalimat dan nama orang memakai kapital. Jeda membaca mengikuti makna, bukan berteriak setiap melihat tanda seru."},{"type":"text","heading":"Contoh bertahap 2","body":"Ini buku Bobo. adalah berita. Siapa pemilik buku ini? adalah pertanyaan. Hati-hati! adalah peringatan singkat."},{"type":"text","heading":"C. Menjawab sesuai pertanyaan","body":"Dengarkan seluruh kalimat sebelum menjawab. Jawaban harus menyediakan jenis informasi yang ditanyakan. Jika belum tahu, katakan belum tahu dan cari bersama. Saat menulis, periksa huruf awal, spasi antarkata, dan tanda akhir. Tanda baca tidak menggantikan pilihan kata yang sopan."},{"type":"text","heading":"Contoh bertahap 3","body":"Kapan perpustakaan buka? dijawab Pukul delapan pagi, bukan Di sebelah kelas. Jawaban kedua menyatakan tempat, bukan waktu."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat kartu kata tanya. Teman mengambil satu kartu dan menyusun pertanyaan tentang cerita rekaan. Jawab dengan informasi yang sesuai, lalu tulis pertanyaan itu memakai kapital dan tanda tanya."},{"type":"text","heading":"Latihan mandiri","body":"1. Pilih kata untuk menanyakan waktu: … kamu datang?\n2. Tambahkan tanda akhir: Di mana pensilmu\n3. Perbaiki: rani membaca buku\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Kapan Kapan meminta informasi waktu.\n2. ? Kalimat tersebut pertanyaan langsung.\n3. Rani membaca buku. Nama dan awal kalimat kapital, berita diakhiri titik.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Kata tanya menunjukkan informasi yang dicari. Gunakan kapital serta tanda akhir sesuai tujuan kalimat dan berikan jawaban yang cocok."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Mulai dari siapa-apa-di mana dengan benda nyata. Lanjut mengapa dan bagaimana ketika anak siap menjelaskan alasan/cara. Pengayaan: membedakan jawaban waktu dan tempat dalam bacaan.\nNilai pemahaman dengan bukti teks, keruntutan gagasan, ketepatan bahasa dan perbaikan setelah umpan balik. Tugas berbicara/menulis dinilai dari karya atau penyampaian, bukan skor pilihan ganda saja; bentuk lisan/dikte/alat bantu dapat disesuaikan.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('e680e126-7b14-5fcf-a562-a044f4660c87','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Kata Ajaib: Tolong, Maaf, Terima Kasih','petualangan-bahasa-indonesia-kelas-2-bab-1',2,'A','Petualangan · Bab 1','dasar','draft',20,'{"summary":"Pulau Kata bersama Bobo: Kata Ajaib: Tolong, Maaf, Terima Kasih. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-bahasa-indonesia-2","mentor":"Bobo","chapter_number":1,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan meminta bantuan dengan tolong dengan contoh dan alasan.","Menjelaskan meminta maaf dan memperbaiki dengan contoh dan alasan.","Menjelaskan berterima kasih dan bergiliran dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Bahasa Indonesia: Keluargaku Unik (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-keluargaku-unik-untuk-sd-mi-kelas-ii-edisi-revisi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan meminta bantuan dengan tolong dengan contoh dan alasan.\n2. Menjelaskan meminta maaf dan memperbaiki dengan contoh dan alasan.\n3. Menjelaskan berterima kasih dan bergiliran dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Tolong, maaf dan terima kasih membuat maksud lebih jelas dan hubungan lebih hangat. Kata-kata itu perlu disertai tindakan yang menghargai orang lain. Orang tetap boleh menolak permintaan yang tidak aman atau tidak dapat dilakukan."},{"type":"text","heading":"A. Meminta bantuan dengan tolong","body":"Sebut bantuan yang diperlukan secara jelas, gunakan tolong dan nada sopan. Berikan kesempatan orang lain menjawab. Meminta bantuan berbeda dari memaksa. Kita dapat mengatakan tidak atau meminta pendamping jika permintaan membuat tidak nyaman, meskipun orang tersebut menggunakan kata tolong."},{"type":"text","heading":"Contoh bertahap 1","body":"Tolong ambilkan buku di rak rendah itu, ya. menyebut tindakan dan benda. Kalimat ini lebih jelas daripada Tolong itu! sambil menunjuk tanpa penjelasan."},{"type":"text","heading":"B. Meminta maaf dan memperbaiki","body":"Maaf digunakan ketika tindakan kita merugikan atau mengganggu. Sebut kesalahan tanpa menyalahkan korban, akui dampaknya, lalu tawarkan perbaikan yang masuk akal. Mengucapkan maaf tidak membuat kita boleh mengulang kesalahan. Jika ada bahaya, hentikan dulu dan mintalah bantuan orang dewasa."},{"type":"text","heading":"Contoh bertahap 2","body":"Maaf, aku tidak sengaja menjatuhkan pensilmu. Aku akan membantu mengambilnya. Kalimat itu mengakui tindakan dan menawarkan perbaikan, bukan sekadar satu kata."},{"type":"text","heading":"C. Berterima kasih dan bergiliran","body":"Terima kasih menyatakan penghargaan atas bantuan atau pemberian. Sebut hal yang dihargai supaya maknanya jelas. Saat berbicara, dengarkan sampai selesai dan tanggapi sesuai maksud. Kesantunan juga terlihat dari tidak mengejek, tidak memotong, dan menghargai jawaban orang lain."},{"type":"text","heading":"Contoh bertahap 3","body":"Terima kasih sudah menjelaskan cara melipat. Aku sekarang bisa mencoba sendiri. Jika bantuan belum dipahami, tambahkan pertanyaan dengan sopan."},{"type":"text","heading":"Kegiatan penerapan","body":"Mainkan tiga percakapan: meminta alat tulis, tidak sengaja menyenggol gambar, dan menerima bantuan. Tukar peran lalu nilai apakah kata, nada dan tindakan sudah sesuai. Semua percakapan memakai kejadian rekaan."},{"type":"text","heading":"Latihan mandiri","body":"1. Buat permintaan meminjam penggaris.\n2. Apa setelah tidak sengaja merobek kertas teman?\n3. Kapan mengatakan terima kasih?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Contoh: Tolong pinjamkan penggarismu sebentar, boleh? Permintaan jelas dan memberi kesempatan menjawab.\n2. Minta maaf dan tawarkan perbaikan. Kata maaf perlu disertai tanggung jawab.\n3. Setelah menerima bantuan atau pemberian. Ucapan menunjukkan penghargaan.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Tolong untuk meminta, maaf untuk mengakui kesalahan, terima kasih untuk menghargai. Tindakan dan penghormatan batas orang lain sama pentingnya."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jangan memaksa anak meminta maaf tanpa memahami kejadian. Modelkan kalimat yang menyebut tindakan dan perbaikan. Pengayaan: menanggapi penolakan dengan sopan.\nNilai pemahaman dengan bukti teks, keruntutan gagasan, ketepatan bahasa dan perbaikan setelah umpan balik. Tugas berbicara/menulis dinilai dari karya atau penyampaian, bukan skor pilihan ganda saja; bentuk lisan/dikte/alat bantu dapat disesuaikan.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('6336579f-a38a-58ad-af11-584cd2d30bae','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Kalimat Berita & Kalimat Perintah','petualangan-bahasa-indonesia-kelas-2-bab-2',2,'A','Petualangan · Bab 2','dasar','draft',20,'{"summary":"Pulau Kata bersama Bobo: Kalimat Berita & Kalimat Perintah. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-bahasa-indonesia-2","mentor":"Bobo","chapter_number":2,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan kalimat berita dengan contoh dan alasan.","Menjelaskan kalimat perintah dan larangan dengan contoh dan alasan.","Menjelaskan mengubah dan menanggapi kalimat dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Bahasa Indonesia: Keluargaku Unik (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-keluargaku-unik-untuk-sd-mi-kelas-ii-edisi-revisi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan kalimat berita dengan contoh dan alasan.\n2. Menjelaskan kalimat perintah dan larangan dengan contoh dan alasan.\n3. Menjelaskan mengubah dan menanggapi kalimat dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Berita menyampaikan informasi, perintah meminta tindakan. Maksud kalimat diketahui dari pilihan kata dan konteks, bukan hanya kerasnya suara. Kita akan menulis keduanya dengan jelas dan sopan."},{"type":"text","heading":"A. Kalimat berita","body":"Kalimat berita menyampaikan keadaan, kejadian atau informasi. Pembaca dapat menanyakan apakah isi berita sesuai bukti. Dalam tulisan, kalimat berita sederhana memakai huruf awal kapital dan titik. Informasi bisa singkat tetapi sebaiknya tidak kehilangan pelaku atau hal yang dibicarakan."},{"type":"text","heading":"Contoh bertahap 1","body":"Pintu kelas sudah tertutup. menyampaikan keadaan pintu. Rani menata buku. menyampaikan kegiatan. Keduanya tidak meminta pembaca melakukan sesuatu."},{"type":"text","heading":"B. Kalimat perintah dan larangan","body":"Perintah meminta orang melakukan tindakan. Kata tolong, silakan atau akhiran -lah dapat membantu menyatakan maksud dengan sopan. Larangan meminta tindakan tidak dilakukan dan sering memakai jangan. Tanda seru dapat dipakai pada perintah tegas, sedangkan permintaan sopan dapat diakhiri titik sesuai bentuknya."},{"type":"text","heading":"Contoh bertahap 2","body":"Tolong tutup pintu itu. meminta tindakan menutup. Jangan berlari di lantai basah! melarang tindakan untuk keselamatan. Ikuti perintah yang aman, bukan semua perintah tanpa berpikir."},{"type":"text","heading":"C. Mengubah dan menanggapi kalimat","body":"Untuk mengubah berita menjadi perintah, tentukan tindakan yang ingin diminta dan siapa yang dituju. Jangan hanya mengganti titik menjadi seru tanpa memperjelas maksud. Tanggapan berita dapat berupa pertanyaan atau informasi lanjutan; tanggapan perintah menunjukkan kesediaan atau alasan penolakan yang wajar."},{"type":"text","heading":"Contoh bertahap 3","body":"Berita: Buku berada di rak. Perintah: Tolong simpan buku di rak. Kedua kalimat membicarakan buku dan rak tetapi mempunyai tujuan berbeda."},{"type":"text","heading":"Kegiatan penerapan","body":"Tuliskan enam kartu kalimat tentang ruang belajar. Kelompokkan menjadi berita, perintah dan larangan. Tukar satu berita menjadi permintaan sopan, lalu jelaskan perubahan maknanya kepada teman."},{"type":"text","heading":"Latihan mandiri","body":"1. Jenis kalimat: Hujan turun sore ini.\n2. Ubah menjadi permintaan: Kamu mengambil pensil.\n3. Buat larangan aman di perpustakaan.\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Berita Kalimat menyampaikan kejadian.\n2. Tolong ambilkan pensil itu. Kata tolong dan bentuk tindakan memperjelas permintaan.\n3. Contoh: Jangan merobek buku! Jawaban lain yang melarang tindakan tidak baik dapat diterima.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Berita memberi informasi, perintah meminta tindakan, larangan meminta tindakan dihindari. Pilih kata dan tanda baca sesuai maksud."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Tanda seru saja tidak otomatis membuat semua kalimat perintah. Periksa makna tindakan yang diminta. Pengayaan: ubah perintah keras menjadi permintaan sopan.\nNilai pemahaman dengan bukti teks, keruntutan gagasan, ketepatan bahasa dan perbaikan setelah umpan balik. Tugas berbicara/menulis dinilai dari karya atau penyampaian, bukan skor pilihan ganda saja; bentuk lisan/dikte/alat bantu dapat disesuaikan.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('f120798a-13ab-5d66-ba02-d0f036ccbcc4','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Membaca Dongeng Hewan (Fabel)','petualangan-bahasa-indonesia-kelas-2-bab-3',2,'A','Petualangan · Bab 3','dasar','draft',20,'{"summary":"Pulau Kata bersama Bobo: Membaca Dongeng Hewan (Fabel). Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-bahasa-indonesia-2","mentor":"Bobo","chapter_number":3,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan tokoh, watak, dan latar dengan contoh dan alasan.","Menjelaskan masalah dan penyelesaian dengan contoh dan alasan.","Menjelaskan pesan dan bukti dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Bahasa Indonesia: Keluargaku Unik (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-keluargaku-unik-untuk-sd-mi-kelas-ii-edisi-revisi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan tokoh, watak, dan latar dengan contoh dan alasan.\n2. Menjelaskan masalah dan penyelesaian dengan contoh dan alasan.\n3. Menjelaskan pesan dan bukti dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Fabel adalah cerita rekaan dengan tokoh hewan yang berperilaku seperti manusia. Baca kisah ini: Kelinci menertawakan langkah Siput. Ketika hujan datang, jalan menjadi licin. Siput mengingatkan Kelinci berjalan hati-hati. Kelinci mendengarkan dan berterima kasih."},{"type":"text","heading":"A. Tokoh, watak, dan latar","body":"Tokoh adalah pelaku cerita. Watak disimpulkan dari ucapan dan tindakan, bukan hanya nama hewan. Latar menyebut tempat, waktu atau suasana. Dalam fabel hewan dapat berbicara, tetapi itu unsur rekaan, bukan informasi ilmiah tentang hewan sebenarnya."},{"type":"text","heading":"Contoh bertahap 1","body":"Kelinci pada awal kisah mengejek, sedangkan Siput memberi peringatan. Jalan licin saat hujan menjadi latar yang memengaruhi kejadian. Bukan berarti semua kelinci nyata mempunyai watak mengejek."},{"type":"text","heading":"B. Masalah dan penyelesaian","body":"Cari peristiwa yang mengganggu tokoh lalu lihat cara tokoh menanggapinya. Urutkan kejadian sebelum menyebut akibat. Pada cerita pendek, penyelesaian bisa berupa tindakan sederhana atau perubahan sikap. Jangan menambahkan kejadian yang tidak diceritakan sebagai fakta kisah."},{"type":"text","heading":"Contoh bertahap 2","body":"Masalahnya jalan licin yang dapat membahayakan Kelinci. Siput memperingatkan dan Kelinci mendengarkan. Teks tidak menyebut Kelinci jatuh, jadi jangan mengaku ia pasti jatuh."},{"type":"text","heading":"C. Pesan dan bukti","body":"Pesan moral adalah pelajaran sikap yang dapat dipikirkan dari cerita. Ada lebih dari satu rumusan masuk akal jika didukung bukti. Hubungkan pesan dengan tindakan tokoh dan situasi sehari-hari. Ringkasan menyebut kejadian, sedangkan pesan menyebut pelajaran; keduanya berbeda."},{"type":"text","heading":"Contoh bertahap 3","body":"Jangan meremehkan orang lain didukung tindakan awal mengejek dan bantuan Siput. Mendengarkan peringatan keselamatan juga didukung keputusan Kelinci. Keduanya dapat dibahas dengan bukti."},{"type":"text","heading":"Kegiatan penerapan","body":"Mainkan dialog Siput dan Kelinci tanpa mengejek teman sungguhan. Setelah itu ubah akhir cerita secara jelas menjadi versi karangan kelompok. Bandingkan pesan versi asli dan versi baru, serta sebutkan tindakan pendukungnya."},{"type":"text","heading":"Latihan mandiri","body":"1. Siapa yang memperingatkan jalan licin?\n2. Apakah hewan berbicara berarti teks laporan sains?\n3. Sebut satu pesan beserta buktinya.\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Siput Tindakan itu disebut langsung dalam kisah.\n2. Tidak Hewan berbicara adalah unsur rekaan fabel.\n3. Hargai orang lain; Siput membantu meski sempat diejek. Pesan dihubungkan dengan tindakan dalam cerita.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Fabel berisi tokoh, latar, masalah dan penyelesaian rekaan. Pesan moral harus mempunyai bukti kejadian, bukan sekadar nasihat acak."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jika anak hanya menyebut judul sebagai pesan, tanyakan apa tindakan tokoh dan apa pelajarannya. Pengayaan: watak tokoh dapat berubah dari awal ke akhir.\nNilai pemahaman dengan bukti teks, keruntutan gagasan, ketepatan bahasa dan perbaikan setelah umpan balik. Tugas berbicara/menulis dinilai dari karya atau penyampaian, bukan skor pilihan ganda saja; bentuk lisan/dikte/alat bantu dapat disesuaikan.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('8448a318-0991-5dad-b9a4-37c4856cf401','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Menulis Cerita Pengalaman Harian','petualangan-bahasa-indonesia-kelas-2-bab-4',2,'A','Petualangan · Bab 4','dasar','draft',20,'{"summary":"Pulau Kata bersama Bobo: Menulis Cerita Pengalaman Harian. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-bahasa-indonesia-2","mentor":"Bobo","chapter_number":4,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan memilih kejadian dan merencanakan dengan contoh dan alasan.","Menjelaskan menulis urutan dan perasaan dengan contoh dan alasan.","Menjelaskan membaca ulang dan memperbaiki dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Bahasa Indonesia: Keluargaku Unik (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-keluargaku-unik-untuk-sd-mi-kelas-ii-edisi-revisi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan memilih kejadian dan merencanakan dengan contoh dan alasan.\n2. Menjelaskan menulis urutan dan perasaan dengan contoh dan alasan.\n3. Menjelaskan membaca ulang dan memperbaiki dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Pengalaman harian dapat menjadi cerita yang menarik jika peristiwanya jelas dan berurutan. Kamu boleh memakai kejadian rekaan jika tidak ingin membagikan pengalaman pribadi. Pembaca tidak membutuhkan alamat atau informasi rahasia."},{"type":"text","heading":"A. Memilih kejadian dan merencanakan","body":"Pilih satu kejadian kecil, misalnya mencoba menanam atau meminjam buku. Catat siapa yang terlibat, kapan secara umum, di mana secara umum, dan apa yang terjadi. Tidak semua kegiatan sepanjang hari harus masuk. Pilih kejadian yang bisa diceritakan dengan awal, tengah dan akhir."},{"type":"text","heading":"Contoh bertahap 1","body":"Kerangka: pagi hari di ruang belajar; aku membuat penanda buku; kertas awal terlipat miring; aku memperbaiki; akhirnya berhasil. Kerangka membantu penulis tidak melompat kejadian."},{"type":"text","heading":"B. Menulis urutan dan perasaan","body":"Gunakan kalimat singkat dan kata urutan seperti mula-mula, kemudian, setelah itu. Perasaan dapat ditambahkan dengan alasan agar tidak hanya daftar kegiatan. Jaga satu sudut pandang, misalnya aku. Cerita pengalaman boleh mempunyai dialog pendek, tetapi peristiwa utamanya tetap mudah diikuti."},{"type":"text","heading":"Contoh bertahap 2","body":"Mula-mula aku melipat kertas. Lipatannya miring sehingga aku kecewa. Aku membuka dan mencobanya lagi. Setelah rapi, aku merasa senang karena tidak menyerah."},{"type":"text","heading":"C. Membaca ulang dan memperbaiki","body":"Baca tulisan dengan suara pelan. Periksa apakah pembaca tahu kejadian sebelum dan sesudahnya, siapa pelakunya, serta bagaimana akhirnya. Perbaiki kapital, spasi dan titik. Sunting isi dahulu bila urutannya rancu, lalu ejaan. Minta tanggapan yang menyebut bagian jelas dan bagian yang perlu penjelasan."},{"type":"text","heading":"Contoh bertahap 3","body":"Tulisan Aku bermain. Pulang. Hujan. dapat diperjelas: Saat bermain, hujan turun. Aku lalu pulang. Perubahan menjelaskan hubungan kejadian tanpa menambah data pribadi."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat cerita 5–7 kalimat tentang kegiatan rekaan tokoh. Gambar tiga kotak awal-tengah-akhir sebelum menulis. Teman membaca dan menunjuk kata urutan serta satu perasaan yang mempunyai alasan; revisi berdasarkan tanggapannya."},{"type":"text","heading":"Latihan mandiri","body":"1. Susun: makan, mencuci tangan, merapikan piring.\n2. Tambahkan alasan: Aku gembira …\n3. Perbaiki: kemarin aku membaca buku\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Mencuci tangan → makan → merapikan piring. Urutan mengikuti kejadian yang masuk akal.\n2. Contoh: karena berhasil menyelesaikan gambar. Alasan membuat perasaan lebih jelas.\n3. Kemarin aku membaca buku. Awal kapital dan akhir titik.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Pilih satu kejadian, buat kerangka, tulis urutan dan perasaan, lalu perbaiki isi dan ejaan. Data pribadi tidak diperlukan agar cerita bermakna."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jika anak kesulitan menulis, izinkan bercerita lisan atau mendiktekan dahulu. Pengayaan: tambahkan satu detail yang membantu pembaca membayangkan suasana tanpa keluar topik.\nNilai pemahaman dengan bukti teks, keruntutan gagasan, ketepatan bahasa dan perbaikan setelah umpan balik. Tugas berbicara/menulis dinilai dari karya atau penyampaian, bukan skor pilihan ganda saja; bentuk lisan/dikte/alat bantu dapat disesuaikan.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('d9c3c20f-a013-5ff3-9ddb-29f6914e8425','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Mencari Ide Pokok Paragraf','petualangan-bahasa-indonesia-kelas-3-bab-1',3,'B','Petualangan · Bab 1','sedang','draft',25,'{"summary":"Pulau Kata bersama Bobo: Mencari Ide Pokok Paragraf. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-bahasa-indonesia-3","mentor":"Bobo","chapter_number":1,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan topik dan ide pokok dengan contoh dan alasan.","Menjelaskan kalimat utama dan pendukung dengan contoh dan alasan.","Menjelaskan meringkas tanpa mengubah makna dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Bahasa Indonesia: Kawan Seiring (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-kawan-seiring-untuk-sdmi-kelas-iii-edisi-revisi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan topik dan ide pokok dengan contoh dan alasan.\n2. Menjelaskan kalimat utama dan pendukung dengan contoh dan alasan.\n3. Menjelaskan meringkas tanpa mengubah makna dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Baca paragraf ini: Kebun sekolah perlu dirawat bersama. Kelompok satu menyiram secukupnya. Kelompok dua mengumpulkan daun kering. Kelompok tiga mencatat pertumbuhan. Semua kegiatan membantu kebun tetap terjaga. Kita akan mencari gagasan yang menaungi rincian tersebut."},{"type":"text","heading":"A. Topik dan ide pokok","body":"Topik menyebut hal yang dibahas, sedangkan ide pokok menyatakan gagasan utama tentang topik itu. Tanyakan seluruh kalimat membicarakan apa dan pesan umum apa yang dijelaskan. Ide pokok dapat dinyatakan dalam satu kalimat sendiri; tidak harus menyalin kalimat pertama. Pilih gagasan yang cukup luas untuk menaungi rincian tanpa keluar dari teks."},{"type":"text","heading":"Contoh bertahap 1","body":"Topiknya kebun sekolah. Ide pokoknya kebun sekolah perlu dirawat bersama. Menyiram secukupnya adalah satu rincian, bukan gagasan yang mencakup seluruh paragraf."},{"type":"text","heading":"B. Kalimat utama dan pendukung","body":"Kalimat utama menyatakan gagasan umum; kalimat pendukung menjelaskan dengan contoh, alasan atau rincian. Kalimat utama bisa berada di awal, akhir, atau tidak ditulis secara langsung. Uji calon gagasan dengan menanyakan apakah rincian lain menerangkannya. Posisi tidak boleh menjadi satu-satunya alasan."},{"type":"text","heading":"Contoh bertahap 2","body":"Dalam paragraf pembuka, kegiatan tiap kelompok mendukung perawatan bersama. Jika kita memilih Kelompok dua mengumpulkan daun, rincian menyiram dan mencatat tidak ternaungi."},{"type":"text","heading":"C. Meringkas tanpa mengubah makna","body":"Tandai kata kunci, hubungkan rincian dengan gagasan, lalu tulis ringkasan singkat memakai kata sendiri. Hapus rincian berulang, tetapi pertahankan informasi penting. Jangan menambah pendapat pribadi sebagai isi bacaan. Setelah menulis, baca kembali paragraf untuk memastikan tidak ada makna berlawanan."},{"type":"text","heading":"Contoh bertahap 3","body":"Ringkasan yang sesuai: Para siswa bekerja sama merawat kebun melalui penyiraman, pembersihan, dan pencatatan pertumbuhan. Teks tidak mengatakan kebun itu paling indah sekota."},{"type":"text","heading":"Kegiatan penerapan","body":"Tulis empat kalimat tentang merawat perpustakaan: satu gagasan umum dan tiga rincian. Tukarkan dengan teman yang menandai ide pokok serta menjelaskan hubungan setiap rincian. Coba pindahkan kalimat utama ke akhir tanpa mengubah maknanya."},{"type":"text","heading":"Latihan mandiri","body":"1. Pada paragraf kebun, apa topiknya?\n2. Sebut satu rincian pendukung.\n3. Apakah ide pokok selalu kalimat pertama?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Kebun sekolah. Semua kalimat mengarah pada kebun.\n2. Contoh: kelompok satu menyiram secukupnya. Rincian menjelaskan cara perawatan bersama.\n3. Tidak. Posisi bervariasi dan kadang gagasan perlu disimpulkan.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Ide pokok menaungi rincian. Temukan hubungan makna, bukan hanya posisi kalimat, lalu ringkas tanpa menambah klaim baru."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jika anak memilih rincian paling menarik, minta ia menguji apakah rincian lain mendukung pilihannya. Pengayaan: paragraf dengan ide pokok tersirat.\nNilai pemahaman dengan bukti teks, keruntutan gagasan, ketepatan bahasa dan perbaikan setelah umpan balik. Tugas berbicara/menulis dinilai dari karya atau penyampaian, bukan skor pilihan ganda saja; bentuk lisan/dikte/alat bantu dapat disesuaikan.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('c2884919-a848-515a-8cf4-616e2065b0e7','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Kalimat Efektif & Kosakata Baru','petualangan-bahasa-indonesia-kelas-3-bab-2',3,'B','Petualangan · Bab 2','sedang','draft',25,'{"summary":"Pulau Kata bersama Bobo: Kalimat Efektif & Kosakata Baru. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-bahasa-indonesia-3","mentor":"Bobo","chapter_number":2,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan kejelasan pelaku dan tindakan dengan contoh dan alasan.","Menjelaskan hemat tanpa menghilangkan makna dengan contoh dan alasan.","Menjelaskan menemukan makna kata baru dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Bahasa Indonesia: Kawan Seiring (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-kawan-seiring-untuk-sdmi-kelas-iii-edisi-revisi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan kejelasan pelaku dan tindakan dengan contoh dan alasan.\n2. Menjelaskan hemat tanpa menghilangkan makna dengan contoh dan alasan.\n3. Menjelaskan menemukan makna kata baru dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Kalimat efektif menyampaikan maksud dengan jelas, hemat dan tepat. Kosakata baru dipahami dari konteks dan diperiksa dalam kamus. Singkat saja belum cukup jika pelaku atau hubungan idenya hilang."},{"type":"text","heading":"A. Kejelasan pelaku dan tindakan","body":"Pastikan pembaca tahu siapa atau apa yang dibicarakan dan kegiatan atau keadaannya. Kata penghubung harus menyatakan hubungan yang tepat. Hindari susunan yang menyebabkan lebih dari satu arti ketika maksudnya hanya satu. Dalam percakapan unsur dapat dipahami dari konteks, tetapi tulisan mandiri biasanya membutuhkan informasi lebih jelas."},{"type":"text","heading":"Contoh bertahap 1","body":"Kalimat Untuk siswa harus membawa buku kurang jelas. Perbaikannya Siswa harus membawa buku. Pelaku siswa langsung terhubung dengan tindakan membawa."},{"type":"text","heading":"B. Hemat tanpa menghilangkan makna","body":"Hilangkan kata yang mengulang makna tanpa fungsi. Bentuk para siswa sudah menyatakan jamak, sehingga tidak perlu para siswa-siswa dalam konteks yang sama. Namun jangan menghapus kata yang membedakan waktu atau sebab. Kalimat panjang boleh efektif bila susunannya jelas dan setiap bagian diperlukan."},{"type":"text","heading":"Contoh bertahap 2","body":"Para peserta masuk ke ruangan lebih hemat daripada Para peserta-peserta masuk ke dalam ruangan untuk konteks biasa. Akan tetapi keterangan sebelum hujan perlu dipertahankan bila penting bagi cerita."},{"type":"text","heading":"C. Menemukan makna kata baru","body":"Baca kalimat sebelum dan sesudah kata. Cari petunjuk contoh, lawan, atau penjelasan. Buat dugaan makna, cek di kamus, kemudian pilih arti yang sesuai konteks karena satu kata bisa bermakna lebih dari satu. Pakai kata baru dalam kalimat sendiri untuk menguji pemahaman."},{"type":"text","heading":"Contoh bertahap 3","body":"Pada Tanaman itu layu karena tidak mendapat air, layu menggambarkan kondisi tidak segar. Makna itu sesuai hubungan kekurangan air, bukan berarti tanaman menjadi batu."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat dua kalimat berulang dan satu kalimat dengan kata baru. Teman menyunting sambil menjelaskan alasan, lalu kalian mengecek apakah informasi penting tetap utuh. Susun kartu kata baru berisi konteks, makna, dan kalimat sendiri."},{"type":"text","heading":"Latihan mandiri","body":"1. Sunting: Para anak-anak berkumpul.\n2. Kata subur pada Tanah subur membuat tanaman tumbuh baik berarti?\n3. Mengapa jangan menghapus semua keterangan?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Anak-anak berkumpul. atau Para anak berkumpul. Penanda jamak tidak perlu digandakan; pilihan pertama lebih lazim.\n2. Baik untuk pertumbuhan tanaman. Konteks menunjukkan kesuburan, bukan warna tertentu.\n3. Sebagian keterangan penting untuk makna. Waktu, sebab, atau tempat dapat membedakan kejadian.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Perjelas unsur kalimat, hematkan pengulangan, dan pilih arti kata sesuai konteks. Sunting dengan menjaga pesan penulis."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jangan menilai efektif hanya dari pendeknya kalimat. Pengayaan: bandingkan dua arti kata kepala pada kepala sekolah dan kepala boneka.\nNilai pemahaman dengan bukti teks, keruntutan gagasan, ketepatan bahasa dan perbaikan setelah umpan balik. Tugas berbicara/menulis dinilai dari karya atau penyampaian, bukan skor pilihan ganda saja; bentuk lisan/dikte/alat bantu dapat disesuaikan.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('4aae3287-9603-5a4d-a7ce-947fa0b239f2','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Membaca Petunjuk & Denah Lokasi','petualangan-bahasa-indonesia-kelas-3-bab-3',3,'B','Petualangan · Bab 3','sedang','draft',25,'{"summary":"Pulau Kata bersama Bobo: Membaca Petunjuk & Denah Lokasi. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-bahasa-indonesia-3","mentor":"Bobo","chapter_number":3,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan urutan petunjuk dan syarat dengan contoh dan alasan.","Menjelaskan legenda dan arah mata angin dengan contoh dan alasan.","Menjelaskan menjelaskan rute dengan acuan dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Bahasa Indonesia: Kawan Seiring (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-kawan-seiring-untuk-sdmi-kelas-iii-edisi-revisi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan urutan petunjuk dan syarat dengan contoh dan alasan.\n2. Menjelaskan legenda dan arah mata angin dengan contoh dan alasan.\n3. Menjelaskan menjelaskan rute dengan acuan dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Petunjuk membantu melakukan langkah; denah menunjukkan letak. Baca seluruh informasi sebelum bergerak. Gunakan denah tempat rekaan untuk belajar dan tetap minta pendamping saat bepergian sungguhan."},{"type":"image","url":"/assets/petualangan-denah.svg","caption":"Denah rekaan: utara di atas; gerbang di selatan taman dan perpustakaan di timur taman. Tidak berskala."},{"type":"text","heading":"A. Urutan petunjuk dan syarat","body":"Petunjuk biasanya memakai langkah bernomor atau kata urutan. Identifikasi alat, tindakan dan syarat keselamatan. Kerjakan menurut urutan bila langkah saling bergantung. Jika ada kalimat jika, perhatikan kondisinya. Setelah melakukan langkah, periksa apakah hasilnya sesuai tujuan, bukan sekadar semua nomor terlewati."},{"type":"text","heading":"Contoh bertahap 1","body":"Petunjuk penanda buku: siapkan kertas, lipat dua, beri nama, lalu hias. Menghias sebelum menulis nama bisa menyulitkan bila ruang nama tertutup."},{"type":"text","heading":"B. Legenda dan arah mata angin","body":"Denah adalah gambaran sederhana letak dilihat dari atas. Baca judul, tanda utara dan legenda simbol. Jika utara di atas, timur berada di kanan, selatan bawah dan barat kiri. Jangan menganggap atas kertas selalu utara jika panah menunjukkan arah lain. Legenda menjelaskan simbol, bukan ukuran sebenarnya."},{"type":"text","heading":"Contoh bertahap 2","body":"Pada denah dengan utara di atas, perpustakaan di sebelah timur kelas berarti di kanan kelas. Kotak bertanda P dapat berarti perpustakaan jika legenda menyatakannya."},{"type":"text","heading":"C. Menjelaskan rute dengan acuan","body":"Tentukan titik awal dan tujuan. Sebut arah gerak serta patokan yang terlihat pada denah. Bedakan belok kanan relatif arah berjalan dengan timur yang tetap menurut mata angin. Periksa rute tidak melewati penghalang. Jarak tepat tidak bisa dihitung dari denah tanpa skala atau informasi panjang."},{"type":"text","heading":"Contoh bertahap 3","body":"Dari gerbang berjalan ke utara sampai taman, lalu ke timur ke perpustakaan. Rute ini lebih jelas daripada ke sana lalu ke situ karena memakai arah dan patokan."},{"type":"text","heading":"Kegiatan penerapan","body":"Gambar denah rekaan empat tempat dengan tanda utara dan legenda. Tuliskan rute dari gerbang ke perpustakaan. Teman mengikuti dengan pion, menunjukkan belokan dan memeriksa apakah ada informasi yang kurang."},{"type":"text","heading":"Latihan mandiri","body":"1. Utara di atas, barat di sisi mana?\n2. Apa fungsi legenda?\n3. Denah tanpa skala dapat memastikan jarak 200 meter?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Kiri. Mata angin pada orientasi itu menempatkan barat di kiri.\n2. Menjelaskan arti simbol. Simbol tidak boleh ditebak tanpa keterangan.\n3. Tidak. Diperlukan skala atau informasi panjang.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Petunjuk memerlukan urutan dan syarat; denah memerlukan orientasi dan legenda. Jelaskan rute dengan titik awal, arah dan patokan."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jika kanan tertukar dengan timur, putar pion dan tunjukkan kanan relatif terhadap arah hadapnya. Pengayaan: denah yang panah utaranya tidak menghadap atas.\nNilai pemahaman dengan bukti teks, keruntutan gagasan, ketepatan bahasa dan perbaikan setelah umpan balik. Tugas berbicara/menulis dinilai dari karya atau penyampaian, bukan skor pilihan ganda saja; bentuk lisan/dikte/alat bantu dapat disesuaikan.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('9b4ecfc3-db9a-51b0-9bf4-a5cfe8b32028','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Mengenal Puisi Anak','petualangan-bahasa-indonesia-kelas-3-bab-4',3,'B','Petualangan · Bab 4','sedang','draft',25,'{"summary":"Pulau Kata bersama Bobo: Mengenal Puisi Anak. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-bahasa-indonesia-3","mentor":"Bobo","chapter_number":4,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan baris, bait, dan suasana dengan contoh dan alasan.","Menjelaskan imaji dan bahasa kias dengan contoh dan alasan.","Menjelaskan membaca dan menulis puisi dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Bahasa Indonesia: Kawan Seiring (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-kawan-seiring-untuk-sdmi-kelas-iii-edisi-revisi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan baris, bait, dan suasana dengan contoh dan alasan.\n2. Menjelaskan imaji dan bahasa kias dengan contoh dan alasan.\n3. Menjelaskan membaca dan menulis puisi dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Puisi dapat mengajak kita merasakan suasana dengan pilihan kata, bunyi dan bentuk baris. Baca puisi orisinal ini: Pagi mengetuk jendela / Embun berkilau di daun / Aku membuka buku / Seperti membuka kebun baru."},{"type":"text","heading":"A. Baris, bait, dan suasana","body":"Baris adalah deretan kata dalam satu larik. Beberapa baris dapat dikelompokkan menjadi bait. Puisi tidak harus mempunyai jumlah baris atau rima yang sama, kecuali mengikuti bentuk tertentu. Perhatikan kata yang membangun perasaan, misalnya hangat, sepi atau riang. Penafsiran perlu dikaitkan dengan kata, bukan hanya dugaan tentang penulis."},{"type":"text","heading":"Contoh bertahap 1","body":"Puisi pembuka mempunyai empat baris dalam satu bait. Kata pagi, berkilau dan kebun baru memberi kesan segar serta ingin tahu; pembaca boleh memberi tafsir lain dengan alasan."},{"type":"text","heading":"B. Imaji dan bahasa kias","body":"Imaji mengajak pembaca membayangkan penglihatan, bunyi, sentuhan atau indra lain. Bahasa kias tidak selalu bermakna harfiah. Ungkapan pagi mengetuk menggambarkan datangnya pagi seperti tamu, bukan pagi memiliki tangan. Jelaskan makna yang masuk akal dari hubungan kata dan konteks."},{"type":"text","heading":"Contoh bertahap 2","body":"Embun berkilau di daun membangun bayangan visual. Seperti membuka kebun baru membandingkan membaca dengan penjelajahan; buku tidak benar-benar berubah menjadi kebun."},{"type":"text","heading":"C. Membaca dan menulis puisi","body":"Baca perlahan dengan lafal jelas dan jeda menurut makna. Suara dan ekspresi membantu tanpa harus berteriak atau meniru semua gerakan. Untuk menulis, pilih satu benda/kejadian, catat pengamatan khusus, lalu pilih kata yang mewakili. Baca ulang untuk menghapus kata yang tidak mendukung suasana."},{"type":"text","heading":"Contoh bertahap 3","body":"Daripada menulis Bunga itu bagus berulang, coba Kelopak kuning menyapa cahaya. Kalimat kedua memberi detail dan citraan; ketepatan pengamatan tetap penting jika menyebut fakta alam."},{"type":"text","heading":"Kegiatan penerapan","body":"Amati benda aman seperti daun atau gelas. Catat tiga ciri yang benar-benar terlihat, lalu buat puisi empat baris. Tandai kata literal dan kias, bacakan, dan minta teman menyebut suasana dengan bukti kata."},{"type":"text","heading":"Latihan mandiri","body":"1. Berapa baris puisi pembuka?\n2. Apakah pagi mengetuk berarti mempunyai tangan?\n3. Buat satu imaji bunyi.\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Empat. Tiap bagian yang dipisahkan garis miring mewakili satu larik.\n2. Tidak. Itu bahasa kias tentang datangnya pagi.\n3. Contoh: Daun berdesir ditiup angin. Kata berdesir mengajak membayangkan bunyi.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Puisi memakai baris, pilihan kata, imaji dan kadang kiasan. Tafsirkan dengan bukti dan bacakan sesuai makna."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Puisi tidak harus berima a-a-a-a. Jika anak bingung kiasan, bandingkan kalimat harfiah dan kias yang menggambarkan kejadian sama. Pengayaan: revisi satu kata untuk mengubah suasana.\nNilai pemahaman dengan bukti teks, keruntutan gagasan, ketepatan bahasa dan perbaikan setelah umpan balik. Tugas berbicara/menulis dinilai dari karya atau penyampaian, bukan skor pilihan ganda saja; bentuk lisan/dikte/alat bantu dapat disesuaikan.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('2ec6984d-6cc5-55ad-a793-0abeee20e12e','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Kalimat Transitif & Intransitif','petualangan-bahasa-indonesia-kelas-4-bab-1',4,'B','Petualangan · Bab 1','sedang','draft',25,'{"summary":"Pulau Kata bersama Bobo: Kalimat Transitif & Intransitif. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-bahasa-indonesia-4","mentor":"Bobo","chapter_number":1,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan pelaku, predikat, dan objek dengan contoh dan alasan.","Menjelaskan kata kerja intransitif dan keterangan dengan contoh dan alasan.","Menjelaskan uji perubahan menjadi pasif dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Panduan Guru Bahasa Indonesia: Lihat Sekitar (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-indonesia-lihat-sekitar-untuk-sd-mi-kelas-iv-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan pelaku, predikat, dan objek dengan contoh dan alasan.\n2. Menjelaskan kata kerja intransitif dan keterangan dengan contoh dan alasan.\n3. Menjelaskan uji perubahan menjadi pasif dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Sebagian kata kerja memerlukan objek, sebagian tidak. Kita akan membedakan kalimat transitif dan intransitif melalui pola kalimat dan uji yang sesuai, bukan hanya mencari kata yang muncul setelah kata kerja."},{"type":"text","heading":"A. Pelaku, predikat, dan objek","body":"Subjek menyatakan pelaku atau hal yang dibicarakan. Predikat menyatakan kegiatan/keadaan. Pada kalimat aktif transitif, predikat kata kerja diikuti objek yang dikenai tindakan dan tidak diawali preposisi. Objek bukan selalu orang; dapat berupa benda atau informasi. Kenali pola dengan kalimat sederhana terlebih dahulu."},{"type":"text","heading":"Contoh bertahap 1","body":"Dina membaca buku. Dina subjek, membaca predikat, buku objek. Dalam konteks ini sesuatu yang dibaca jelas disebut sebagai buku."},{"type":"text","heading":"B. Kata kerja intransitif dan keterangan","body":"Kalimat intransitif tidak memerlukan objek. Setelah kata kerja masih dapat muncul keterangan waktu atau tempat. Frasa yang diawali di, ke atau dari biasanya bukan objek langsung. Ada kata kerja yang dapat dipakai dengan konstruksi berbeda; periksa kalimat lengkapnya, bukan label kata secara terpisah."},{"type":"text","heading":"Contoh bertahap 2","body":"Raka tidur di kamar. Tidur tidak memerlukan objek; di kamar adalah keterangan tempat. Nia berlari pagi ini juga lengkap tanpa objek."},{"type":"text","heading":"C. Uji perubahan menjadi pasif","body":"Pada pola aktif transitif sederhana, objek dapat menjadi subjek pasif. Perubahan mempertahankan makna dasar kejadian. Uji ini membantu membedakan objek dari keterangan, tetapi gunakan contoh yang lazim dan perhatikan bentuk kata kerja. Jangan memaksa setiap frasa setelah predikat menjadi objek."},{"type":"text","heading":"Contoh bertahap 3","body":"Dina membaca buku dapat menjadi Buku dibaca Dina. Raka tidur di kamar tidak diubah menjadi Kamar ditidur Raka karena kamar bukan objek tidur."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat kartu pelaku, kata kerja dan benda/keterangan. Susun tiga kalimat transitif dan tiga intransitif. Tandai unsur, coba bentuk pasif pada contoh transitif, lalu jelaskan mengapa keterangan tempat bukan objek."},{"type":"text","heading":"Latihan mandiri","body":"1. Tentukan objek: Bimo menyiram tanaman.\n2. Apakah Sari berenang di kolam transitif?\n3. Ubah Ibu menutup pintu ke pasif.\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Tanaman. Tanaman dikenai tindakan menyiram dan dapat menjadi subjek pasif.\n2. Intransitif. Berenang tidak memerlukan objek; di kolam keterangan.\n3. Pintu ditutup Ibu. Objek pintu menjadi subjek.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Kalimat transitif memiliki objek langsung; intransitif tidak memerlukannya. Keterangan tempat bukan objek, dan uji pasif membantu pada contoh sederhana."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jangan memakai aturan semua yang setelah predikat adalah objek. Pengayaan: bedakan objek dan pelengkap dengan pendamping pada contoh yang terkontrol.\nNilai pemahaman dengan bukti teks, keruntutan gagasan, ketepatan bahasa dan perbaikan setelah umpan balik. Tugas berbicara/menulis dinilai dari karya atau penyampaian, bukan skor pilihan ganda saja; bentuk lisan/dikte/alat bantu dapat disesuaikan.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('36c8bcce-a7f8-5f49-8989-d59a3141b70d','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Mencari Arti Kata di Kamus','petualangan-bahasa-indonesia-kelas-4-bab-2',4,'B','Petualangan · Bab 2','sedang','draft',25,'{"summary":"Pulau Kata bersama Bobo: Mencari Arti Kata di Kamus. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-bahasa-indonesia-4","mentor":"Bobo","chapter_number":2,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan urutan alfabet dan lema dengan contoh dan alasan.","Menjelaskan memilih arti sesuai konteks dengan contoh dan alasan.","Menjelaskan mencatat dan menggunakan kata dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Panduan Guru Bahasa Indonesia: Lihat Sekitar (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-indonesia-lihat-sekitar-untuk-sd-mi-kelas-iv-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan urutan alfabet dan lema dengan contoh dan alasan.\n2. Menjelaskan memilih arti sesuai konteks dengan contoh dan alasan.\n3. Menjelaskan mencatat dan menggunakan kata dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Kamus membantu memeriksa arti, penulisan dan penggunaan kata. Satu kata dapat mempunyai beberapa makna. Gunakan kamus tepercaya yang tersedia bersama pendamping, lalu pilih makna sesuai kalimat."},{"type":"text","heading":"A. Urutan alfabet dan lema","body":"Kamus cetak menyusun kata menurut abjad. Bandingkan huruf pertama; jika sama, bandingkan huruf berikutnya. Kata yang menjadi judul entri disebut lema. Kata berimbuhan dapat dijelaskan melalui kata dasar atau petunjuk entri. Pada kamus digital gunakan pencarian dan baca entri lengkap, bukan cuplikan pertama saja."},{"type":"text","heading":"Contoh bertahap 1","body":"Batu mendahului buku karena setelah b, a mendahului u. Kata membawa berhubungan dengan kata dasar bawa; petunjuk kamus dapat mengarahkan ke keluarga kata tersebut."},{"type":"text","heading":"B. Memilih arti sesuai konteks","body":"Baca semua arti yang relevan dan cocokkan dengan topik kalimat. Kata bisa mempunyai arti harfiah maupun kias. Jangan mengambil arti pertama secara otomatis. Periksa contoh penggunaan dan kelas kata bila tersedia. Bila arti masih tidak cocok, baca kalimat sebelumnya dan sesudahnya."},{"type":"text","heading":"Contoh bertahap 2","body":"Akar pohon menyerap air memakai arti bagian tumbuhan. Akar masalahnya kurang komunikasi memakai arti asal penyebab masalah. Keduanya memakai tulisan akar tetapi konteks berbeda."},{"type":"text","heading":"C. Mencatat dan menggunakan kata","body":"Tuliskan kata, kalimat asal, arti yang dipilih dan contoh kalimat sendiri. Dengan begitu kita mengingat pemakaian, bukan hanya definisi lepas. Bedakan hasil cek kamus dari dugaan awal. Jika membagikan penjelasan, sebut sumber kamus dan jangan mengaku semua arti baru telah dipahami."},{"type":"text","heading":"Contoh bertahap 3","body":"Catatan: rapat pada Pintu itu tertutup rapat berarti tidak berjarak/tertutup baik, berbeda dari rapat pada kegiatan pertemuan. Kalimat baru menguji apakah pilihan arti masuk akal."},{"type":"text","heading":"Kegiatan penerapan","body":"Pilih lima kata dari bacaan. Susun menurut alfabet, cari kata dasar dan artinya, lalu buat kartu kosakata. Pasangan memilih arti yang cocok pada dua konteks berbeda dan menunjukkan alasan dari kalimat."},{"type":"text","heading":"Latihan mandiri","body":"1. Urutkan: meja, makan, mata.\n2. Arti mata pada mata air?\n3. Mengapa perlu membaca lebih dari satu arti?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. makan, mata, meja. Huruf awal sama; bandingkan a/e, lalu k/t.\n2. Tempat keluarnya air dari dalam tanah. Bukan organ penglihatan; konteks air memilih arti berbeda.\n3. Karena makna bergantung konteks. Kata yang sama dapat digunakan untuk hal berbeda.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Cari lema dengan urutan atau pencarian, baca arti dan contoh, cocokkan konteks, lalu gunakan kata dalam kalimat baru."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jika anak selalu mengambil arti pertama, sediakan dua kalimat dengan kata sama tetapi makna berbeda. Pengayaan: gunakan keterangan kelas kata dan bentuk turunan.\nNilai pemahaman dengan bukti teks, keruntutan gagasan, ketepatan bahasa dan perbaikan setelah umpan balik. Tugas berbicara/menulis dinilai dari karya atau penyampaian, bukan skor pilihan ganda saja; bentuk lisan/dikte/alat bantu dapat disesuaikan.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('9d9a6f16-e209-5086-a6e0-d468dc2ba88e','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Wawancara & Laporan Pengamatan','petualangan-bahasa-indonesia-kelas-4-bab-3',4,'B','Petualangan · Bab 3','sedang','draft',25,'{"summary":"Pulau Kata bersama Bobo: Wawancara & Laporan Pengamatan. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-bahasa-indonesia-4","mentor":"Bobo","chapter_number":3,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan mempersiapkan wawancara dengan contoh dan alasan.","Menjelaskan mencatat pengamatan dan jawaban dengan contoh dan alasan.","Menjelaskan menyusun laporan runtut dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Panduan Guru Bahasa Indonesia: Lihat Sekitar (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-indonesia-lihat-sekitar-untuk-sd-mi-kelas-iv-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan mempersiapkan wawancara dengan contoh dan alasan.\n2. Menjelaskan mencatat pengamatan dan jawaban dengan contoh dan alasan.\n3. Menjelaskan menyusun laporan runtut dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Wawancara mengumpulkan keterangan dari narasumber; pengamatan mencatat apa yang dilihat atau diukur. Laporan yang baik membedakan keduanya dari pendapat penulis. Mintalah izin dan pakai pertanyaan yang aman."},{"type":"text","heading":"A. Mempersiapkan wawancara","body":"Tentukan tujuan, pilih narasumber yang relevan, lalu susun pertanyaan terbuka dan netral. Perkenalkan diri dengan aman, minta waktu dan izin mencatat. Jangan meminta password, nomor identitas atau rahasia pribadi. Pertanyaan tidak menggiring jawaban yang kita inginkan. Berterima kasih setelah selesai."},{"type":"text","heading":"Contoh bertahap 1","body":"Tujuan mengetahui perawatan tanaman dapat memakai Bagaimana cara menentukan kebutuhan air? Pertanyaan Tanaman ini pasti terbaik, kan? menggiring dan kurang membantu memperoleh informasi netral."},{"type":"text","heading":"B. Mencatat pengamatan dan jawaban","body":"Catat waktu, objek, tindakan dan hasil. Tuliskan angka beserta satuannya jika mengukur. Pisahkan kutipan tepat narasumber dari parafrasa; jangan menaruh tanda kutip pada kalimat yang tidak dicatat persis. Pada pengamatan, laporkan yang tampak dan tandai tafsir yang belum pasti."},{"type":"text","heading":"Contoh bertahap 2","body":"Catatan: pukul 09.00, tanah pot A tampak kering di permukaan. Narasumber menjelaskan penyiraman diperiksa dahulu. Kita belum dapat menyimpulkan seluruh akar kering hanya dari permukaan."},{"type":"text","heading":"C. Menyusun laporan runtut","body":"Susun judul, tujuan, cara/sumber informasi, hasil dan simpulan. Simpulan menjawab tujuan dengan bukti hasil. Jangan mengubah jawaban narasumber agar sesuai dugaan. Bila data kurang, nyatakan keterbatasannya. Gunakan kalimat jelas, satu topik per paragraf, lalu cek ejaan dan urutan."},{"type":"text","heading":"Contoh bertahap 3","body":"Laporan pengamatan dua pot hanya menyimpulkan kondisi dua pot pada waktu yang diamati. Klaim semua tanaman sekolah kekurangan air membutuhkan data lebih luas."},{"type":"text","heading":"Kegiatan penerapan","body":"Wawancarai pendamping tentang merawat buku dengan persetujuannya, tanpa merekam jika belum diizinkan. Amati dua buku rekaan atau milik sendiri. Buat laporan singkat yang memberi label hasil wawancara dan hasil pengamatan."},{"type":"text","heading":"Latihan mandiri","body":"1. Buat pertanyaan terbuka tentang perpustakaan.\n2. Bedakan daun berwarna kuning dan tanaman pasti mati.\n3. Apa isi simpulan?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Contoh: Bagaimana cara merawat buku agar awet? Jawabannya dapat dijelaskan, bukan hanya ya/tidak.\n2. Pertama pengamatan; kedua kesimpulan yang perlu bukti. Daun kuning saja belum membuktikan tanaman mati.\n3. Jawaban tujuan berdasarkan hasil. Bukan informasi baru yang tidak diamati.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Tentukan tujuan, minta izin, catat informasi dengan akurat, lalu laporkan cara, hasil dan simpulan yang terbatas pada bukti."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jika anak menulis tafsir sebagai fakta, gunakan kolom terlihat/diukur dan dugaan. Pengayaan: bandingkan jawaban dua narasumber sambil menjaga konteks.\nNilai pemahaman dengan bukti teks, keruntutan gagasan, ketepatan bahasa dan perbaikan setelah umpan balik. Tugas berbicara/menulis dinilai dari karya atau penyampaian, bukan skor pilihan ganda saja; bentuk lisan/dikte/alat bantu dapat disesuaikan.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('0712e670-89d7-5377-a8a6-3476620c8f37','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Memahami Pesan Moral Cerita Rakyat','petualangan-bahasa-indonesia-kelas-4-bab-4',4,'B','Petualangan · Bab 4','sedang','draft',25,'{"summary":"Pulau Kata bersama Bobo: Memahami Pesan Moral Cerita Rakyat. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-bahasa-indonesia-4","mentor":"Bobo","chapter_number":4,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan mengenali unsur cerita dengan contoh dan alasan.","Menjelaskan menafsirkan pesan dengan bukti dengan contoh dan alasan.","Menjelaskan membandingkan versi dan konteks dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Panduan Guru Bahasa Indonesia: Lihat Sekitar (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-indonesia-lihat-sekitar-untuk-sd-mi-kelas-iv-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan mengenali unsur cerita dengan contoh dan alasan.\n2. Menjelaskan menafsirkan pesan dengan bukti dengan contoh dan alasan.\n3. Menjelaskan membandingkan versi dan konteks dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Cerita rakyat diwariskan dan dapat memiliki beberapa versi. Kita membaca untuk memahami kejadian, nilai budaya dan pesan, sambil membedakan kisah rekaan dari bukti sejarah. Gunakan versi yang jelas sumbernya ketika membahas cerita bernama."},{"type":"text","heading":"A. Mengenali unsur cerita","body":"Cari tokoh, latar, masalah, rangkaian peristiwa dan penyelesaian. Perhatikan tindakan yang membawa akibat. Cerita rakyat dapat berisi unsur ajaib; itu bagian cerita dan tidak otomatis fakta alam. Hindari menyimpulkan watak seluruh kelompok masyarakat dari satu tokoh."},{"type":"text","heading":"Contoh bertahap 1","body":"Contoh rekaan untuk latihan: penjaga lumbung menyembunyikan benih lalu desa kekurangan bibit. Ketika ia mengaku dan membagi simpanan, warga menanam bersama. Akibat tindakan membantu menemukan pesan."},{"type":"text","heading":"B. Menafsirkan pesan dengan bukti","body":"Tentukan pilihan tokoh, dampaknya dan perubahan yang terjadi. Rumuskan pesan yang tidak terlalu luas. Dua pembaca dapat memberi pesan berbeda jika masing-masing menunjukkan bukti. Bedakan pesan dari ringkasan alur dan dari hukuman tokoh. Pesan harus masuk akal diterapkan, bukan menyetujui semua tindakan dalam kisah."},{"type":"text","heading":"Contoh bertahap 2","body":"Dari cerita lumbung, kejujuran dan kerja sama membantu memperbaiki kesulitan didukung pengakuan dan penanaman bersama. Pesan semua orang desa jahat tidak didukung teks."},{"type":"text","heading":"C. Membandingkan versi dan konteks","body":"Jika tersedia dua versi, catat persamaan dan perbedaan kejadian serta sumbernya. Jangan mencampur versi tanpa penjelasan. Nilai tindakan dengan mempertimbangkan konteks, keselamatan dan penghormatan terhadap orang lain. Cerita dapat memuat kebiasaan masa lalu yang tidak harus ditiru sekarang."},{"type":"text","heading":"Contoh bertahap 3","body":"Versi pertama mungkin menekankan keberanian, versi kedua kejujuran. Sebut kejadian yang berbeda sebelum membahas perubahan pesan. Nama tokoh sama tidak menjamin seluruh alurnya sama."},{"type":"text","heading":"Kegiatan penerapan","body":"Pilih satu cerita rakyat pendek dari buku pendamping dengan sumber tercatat. Buat tabel tindakan-bukti-akibat-pesan. Ceritakan ulang tanpa mengejek budaya dan jelaskan satu nilai yang dapat dipraktikkan secara aman hari ini."},{"type":"text","heading":"Latihan mandiri","body":"1. Apa beda ringkasan dan pesan?\n2. Mengapa menyebut sumber versi?\n3. Pesan kisah lumbung yang masuk akal?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Ringkasan menyebut kejadian; pesan menyebut pelajaran. Keduanya berhubungan tetapi memiliki tujuan berbeda.\n2. Agar pembaca tahu kisah yang dianalisis. Cerita dapat memiliki variasi alur.\n3. Jujur dan bekerja sama membantu memperbaiki masalah. Pengakuan dan penanaman bersama menjadi bukti.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Temukan unsur dan hubungan tindakan-akibat. Pesan perlu bukti; sebut versi sumber dan hargai konteks budaya tanpa menganggap semua kisah sebagai fakta."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jangan menerima pesan asal terdengar baik tetapi tidak didukung teks. Pengayaan: bandingkan dua penafsiran dan nilai kekuatan buktinya.\nNilai pemahaman dengan bukti teks, keruntutan gagasan, ketepatan bahasa dan perbaikan setelah umpan balik. Tugas berbicara/menulis dinilai dari karya atau penyampaian, bukan skor pilihan ganda saja; bentuk lisan/dikte/alat bantu dapat disesuaikan.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('f2c6c4bf-5f0d-58d4-8c4c-109d16cb874e','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Kata Sifat, Sinonim, dan Antonim','petualangan-bahasa-indonesia-kelas-5-bab-1',5,'C','Petualangan · Bab 1','sedang','draft',25,'{"summary":"Pulau Kata bersama Bobo: Kata Sifat, Sinonim, dan Antonim. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-bahasa-indonesia-5","mentor":"Bobo","chapter_number":1,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan kata sifat dalam deskripsi dengan contoh dan alasan.","Menjelaskan sinonim sesuai konteks dengan contoh dan alasan.","Menjelaskan antonim dan revisi pilihan kata dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Bahasa Indonesia: Bergerak Bersama (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-bergerak-bersama-untuk-sd-mi-kelas-v-edisi-revisi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan kata sifat dalam deskripsi dengan contoh dan alasan.\n2. Menjelaskan sinonim sesuai konteks dengan contoh dan alasan.\n3. Menjelaskan antonim dan revisi pilihan kata dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Kata sifat menerangkan keadaan atau kualitas. Sinonim memiliki makna mirip, antonim berlawanan dalam konteks tertentu. Pilihan kata memengaruhi ketepatan deskripsi dan cara kita menghargai orang lain."},{"type":"text","heading":"A. Kata sifat dalam deskripsi","body":"Kata sifat dapat menerangkan ukuran, warna, keadaan atau kualitas, misalnya panjang, hijau, tenang, dan teliti. Beberapa dapat didahului sangat atau lebih. Gunakan ciri yang dapat dijelaskan, bukan label merendahkan seseorang. Bedakan penilaian subjektif seperti indah dari ukuran yang dapat diukur seperti panjang dua meter."},{"type":"text","heading":"Contoh bertahap 1","body":"Kalimat Pita merah itu panjang memakai merah untuk warna dan panjang untuk ukuran relatif. Menambahkan dibanding pita biru membuat perbandingannya lebih jelas."},{"type":"text","heading":"B. Sinonim sesuai konteks","body":"Sinonim mempunyai makna mirip tetapi tidak selalu dapat saling mengganti dalam semua kalimat. Pertimbangkan tingkat kesopanan, pasangan kata dan arti khusus. Gunakan kamus untuk memeriksa, lalu baca kembali kalimat hasil penggantian. Kata yang sekilas mirip dapat berbeda nuansa atau penggunaannya."},{"type":"text","heading":"Contoh bertahap 2","body":"Pandai dan cerdas berdekatan makna pada anak yang cepat memahami pelajaran. Namun besar dan agung tidak selalu dapat ditukar: sepatu agung tidak lazim untuk menggantikan sepatu besar."},{"type":"text","heading":"C. Antonim dan revisi pilihan kata","body":"Antonim menyatakan pertentangan makna, misalnya panjang-pendek atau ramai-sepi. Lawan bergantung arti kata yang sedang dipakai; ringan pada beban dapat berlawanan dengan berat, sedangkan pada pekerjaan maknanya dapat dekat mudah. Saat menyunting, pilih kata yang tepat lalu pastikan maksud dan tingkat kesantunannya tetap."},{"type":"text","heading":"Contoh bertahap 3","body":"Ruang itu semula ramai, kemudian sepi setelah peserta pulang. Kedua kata mempertentangkan keadaan kegiatan/bunyi, bukan ukuran ruang."},{"type":"text","heading":"Kegiatan penerapan","body":"Pilih satu benda dan tulis lima kata deskripsi. Ganti dua kata dengan sinonim yang tetap cocok, lalu tulis kalimat antonim. Teman menjelaskan apakah penggantian mengubah nuansa atau malah membuat kalimat tidak lazim."},{"type":"text","heading":"Latihan mandiri","body":"1. Sebut antonim panjang.\n2. Ganti pandai pada Ia pandai berhitung dengan kata dekat makna.\n3. Apakah semua sinonim dapat ditukar di semua kalimat?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Pendek. Keduanya membandingkan ukuran panjang.\n2. Contoh: mahir. Mahir berhitung menekankan kemampuan; cek konteks.\n3. Tidak. Konteks dan kelaziman pasangan kata berpengaruh.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Kata sifat memperjelas ciri. Sinonim perlu kecocokan konteks; antonim mempertentangkan makna yang sedang digunakan."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jangan menguji sinonim hanya sebagai pasangan lepas. Pengayaan: dua kalimat dengan kata ringan pada konteks berbeda dan lawan yang sesuai.\nNilai pemahaman dengan bukti teks, keruntutan gagasan, ketepatan bahasa dan perbaikan setelah umpan balik. Tugas berbicara/menulis dinilai dari karya atau penyampaian, bukan skor pilihan ganda saja; bentuk lisan/dikte/alat bantu dapat disesuaikan.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('1739e19b-e7d8-5aa9-a02c-1410cd34dbdb','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Kalimat Langsung & Tidak Langsung','petualangan-bahasa-indonesia-kelas-5-bab-2',5,'C','Petualangan · Bab 2','sedang','draft',25,'{"summary":"Pulau Kata bersama Bobo: Kalimat Langsung & Tidak Langsung. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-bahasa-indonesia-5","mentor":"Bobo","chapter_number":2,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan menulis ucapan langsung dengan contoh dan alasan.","Menjelaskan melaporkan isi ucapan dengan contoh dan alasan.","Menjelaskan menyesuaikan waktu dan tempat dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Bahasa Indonesia: Bergerak Bersama (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-bergerak-bersama-untuk-sd-mi-kelas-v-edisi-revisi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan menulis ucapan langsung dengan contoh dan alasan.\n2. Menjelaskan melaporkan isi ucapan dengan contoh dan alasan.\n3. Menjelaskan menyesuaikan waktu dan tempat dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Kalimat langsung menuliskan ucapan secara langsung; kalimat tidak langsung melaporkan isi ucapan. Penulis perlu menjaga siapa pembicara, siapa pendengar, dan kapan atau di mana ucapan disampaikan."},{"type":"text","heading":"A. Menulis ucapan langsung","body":"Ucapan yang ditulis persis diapit tanda petik. Bagian pengiring menyebut pembicaranya. Perhatikan kapital awal ucapan dan letak tanda baca. Gunakan kutipan hanya jika kata yang ditulis benar-benar sesuai ucapan atau merupakan dialog rekaan yang kamu tulis sendiri. Jangan mengubah pendapat orang lalu tetap menyebutnya kutipan persis."},{"type":"text","heading":"Contoh bertahap 1","body":"Rani berkata, “Aku membawa buku.” Kalimat pengiring Rani berkata diikuti koma; ucapan dimulai kapital dan diapit tanda petik."},{"type":"text","heading":"B. Melaporkan isi ucapan","body":"Kalimat tidak langsung tidak memakai tanda petik untuk isi laporannya. Kata bahwa dapat menghubungkan pengiring dengan isi berita. Kata ganti perlu menyesuaikan pembicara: aku dari Rani menjadi ia ketika diceritakan orang lain. Pertanyaan dapat dilaporkan memakai kata tanya atau apakah tanpa menjadikannya perintah."},{"type":"text","heading":"Contoh bertahap 2","body":"Rani berkata bahwa ia membawa buku. Pertanyaan Bimo, “Kapan kita mulai?” dapat dilaporkan Bimo bertanya kapan kegiatan dimulai, jika konteks kegiatan jelas."},{"type":"text","heading":"C. Menyesuaikan waktu dan tempat","body":"Kata sekarang, besok, di sini dan kata ganti bergantung situasi. Jika laporan dibuat pada waktu atau tempat lain, jelaskan acuannya agar makna tidak berubah. Jangan mengganti secara mekanis tanpa mengetahui siapa yang melapor dan kapan. Setelah mengubah, bandingkan pesan pokok kedua kalimat."},{"type":"text","heading":"Contoh bertahap 3","body":"Ucapan pada Senin, “Aku datang besok,” dilaporkan pada Rabu menjadi Ia mengatakan akan datang pada Selasa. Kata besok saja pada Rabu akan menunjuk Kamis dan mengubah maksud."},{"type":"text","heading":"Kegiatan penerapan","body":"Tulis dialog rekaan dua tokoh tentang meminjam buku. Ubah tiga ucapan menjadi laporan tidak langsung. Tandai perubahan kata ganti, waktu, tempat, dan tanda baca, lalu minta teman memeriksa apakah pesannya tetap."},{"type":"text","heading":"Latihan mandiri","body":"1. Ubah: Dita berkata, “Aku senang.”\n2. Apa tanda yang mengapit ucapan langsung?\n3. Mengapa besok kadang perlu ditulis tanggal/hari?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Dita berkata bahwa ia senang. Aku merujuk Dita sehingga menjadi ia.\n2. Tanda petik. Tanda itu membatasi ucapan yang dikutip.\n3. Agar acuan waktunya tetap. Waktu pelaporan bisa berbeda dari waktu ucapan.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Kutipan langsung menjaga kata dan tanda petik. Laporan tidak langsung menjaga makna sambil menyesuaikan kata ganti serta acuan waktu/tempat."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jika anak hanya menghapus petik, cek siapa yang dimaksud aku atau kami. Pengayaan: melaporkan ucapan pada hari berbeda dengan acuan eksplisit.\nNilai pemahaman dengan bukti teks, keruntutan gagasan, ketepatan bahasa dan perbaikan setelah umpan balik. Tugas berbicara/menulis dinilai dari karya atau penyampaian, bukan skor pilihan ganda saja; bentuk lisan/dikte/alat bantu dapat disesuaikan.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('5c567a0b-f994-5976-af00-1a41b9e204ce','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Membedakan Fakta dan Opini','petualangan-bahasa-indonesia-kelas-5-bab-3',5,'C','Petualangan · Bab 3','sedang','draft',25,'{"summary":"Pulau Kata bersama Bobo: Membedakan Fakta dan Opini. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-bahasa-indonesia-5","mentor":"Bobo","chapter_number":3,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan pernyataan yang dapat diverifikasi dengan contoh dan alasan.","Menjelaskan penilaian dan selera dengan contoh dan alasan.","Menjelaskan memeriksa sumber dan memisahkan campuran dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Bahasa Indonesia: Bergerak Bersama (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-bergerak-bersama-untuk-sd-mi-kelas-v-edisi-revisi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan pernyataan yang dapat diverifikasi dengan contoh dan alasan.\n2. Menjelaskan penilaian dan selera dengan contoh dan alasan.\n3. Menjelaskan memeriksa sumber dan memisahkan campuran dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Fakta adalah pernyataan yang dapat diperiksa dengan bukti; opini berisi penilaian, keyakinan atau selera. Sebuah kalimat terdengar meyakinkan belum tentu benar. Kita perlu memeriksa sumber, waktu dan konteks."},{"type":"text","heading":"A. Pernyataan yang dapat diverifikasi","body":"Tanyakan bukti apa yang dapat mendukung atau membantah kalimat. Angka, tanggal, pengamatan dan catatan dapat membantu, tetapi angka yang dikarang tetap tidak benar. Pernyataan faktual harus diverifikasi sebelum disebut fakta yang terbukti. Bedakan jenis pernyataan dari kebenaran isinya."},{"type":"text","heading":"Contoh bertahap 1","body":"Perpustakaan memiliki 120 buku dapat diperiksa dengan inventaris pada waktu tertentu. Jika belum dicek, itu klaim faktual, bukan otomatis fakta sah hanya karena mengandung angka."},{"type":"text","heading":"B. Penilaian dan selera","body":"Kata paling menarik, lezat, sebaiknya atau menurut saya sering menandai opini. Opini boleh didukung alasan tetapi tidak menjadi fakta universal hanya karena banyak yang setuju. Sebaliknya, tidak semua kalimat tanpa menurut saya adalah fakta. Cari apakah maknanya penilaian atau sesuatu yang bisa diverifikasi."},{"type":"text","heading":"Contoh bertahap 2","body":"Buku ini paling menyenangkan adalah penilaian pembaca. Buku ini terdiri dari 80 halaman adalah klaim yang dapat diperiksa. Keduanya dapat berada pada paragraf sama."},{"type":"text","heading":"C. Memeriksa sumber dan memisahkan campuran","body":"Pecah kalimat campuran menjadi bagian klaim dan penilaian. Cari sumber yang relevan, tanggal, metode atau bukti langsung. Satu gambar tanpa konteks dapat menyesatkan. Jika bukti belum cukup, tulis belum dapat dipastikan. Jangan menyebarkan dugaan tentang orang sebagai fakta."},{"type":"text","heading":"Contoh bertahap 3","body":"Kalimat Kelas menanam 10 pohon dan kegiatannya paling hebat memuat hitungan yang dapat diverifikasi serta penilaian paling hebat. Masing-masing perlu diperlakukan berbeda."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat poster rekaan perpustakaan yang memuat dua klaim terukur dan dua opini beralasan. Beri label tiap bagian dan sebut cara memeriksa klaim terukurnya. Teman mencari kalimat campuran yang perlu dipisah."},{"type":"text","heading":"Latihan mandiri","body":"1. Jenis pernyataan: Menurutku cerita itu lucu.\n2. Bagaimana memeriksa tinggi tanaman 15 cm?\n3. Apakah banyak orang setuju membuat opini pasti fakta?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Opini. Lucu adalah penilaian pribadi.\n2. Ukur dengan alat dan satuan yang tepat pada waktu disebut. Ada prosedur verifikasi.\n3. Tidak. Persetujuan tidak menggantikan bukti.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Pisahkan klaim yang dapat diverifikasi dari penilaian. Periksa bukti, sumber dan konteks; angka atau suara terbanyak tidak menjamin kebenaran."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jangan memakai aturan angka selalu fakta. Pengayaan: kalimat campuran dan klaim faktual yang ternyata salah setelah diperiksa.\nNilai pemahaman dengan bukti teks, keruntutan gagasan, ketepatan bahasa dan perbaikan setelah umpan balik. Tugas berbicara/menulis dinilai dari karya atau penyampaian, bukan skor pilihan ganda saja; bentuk lisan/dikte/alat bantu dapat disesuaikan.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('2ddd68e8-dfb3-579e-8106-08a100e3db22','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Teks Eksplanasi Fenomena Alam','petualangan-bahasa-indonesia-kelas-5-bab-4',5,'C','Petualangan · Bab 4','sedang','draft',25,'{"summary":"Pulau Kata bersama Bobo: Teks Eksplanasi Fenomena Alam. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-bahasa-indonesia-5","mentor":"Bobo","chapter_number":4,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan pernyataan umum dan fokus fenomena dengan contoh dan alasan.","Menjelaskan urutan proses dan hubungan sebab dengan contoh dan alasan.","Menjelaskan menyusun penutup dan menyunting dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Bahasa Indonesia: Bergerak Bersama (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/bahasa-indonesia-bergerak-bersama-untuk-sd-mi-kelas-v-edisi-revisi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan pernyataan umum dan fokus fenomena dengan contoh dan alasan.\n2. Menjelaskan urutan proses dan hubungan sebab dengan contoh dan alasan.\n3. Menjelaskan menyusun penutup dan menyunting dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Teks eksplanasi menjelaskan bagaimana atau mengapa fenomena terjadi. Kita memakai contoh hujan dan penguapan yang aman, lalu memisahkan proses ilmiah dari cerita imajinatif."},{"type":"text","heading":"A. Pernyataan umum dan fokus fenomena","body":"Awali dengan fenomena yang akan dijelaskan, misalnya terbentuknya hujan. Sebut lingkup agar pembaca tahu apa yang dibahas. Eksplanasi tidak sekadar menceritakan pengalaman kehujanan atau memberikan langkah membuat benda. Informasi harus didukung sumber sains yang relevan dan disesuaikan usia pembaca."},{"type":"text","heading":"Contoh bertahap 1","body":"Pernyataan umum: Hujan adalah jatuhnya air dari awan ke permukaan bumi ketika tetes air atau kristal es tumbuh cukup besar. Bagian berikutnya menjelaskan proses yang berkaitan."},{"type":"text","heading":"B. Urutan proses dan hubungan sebab","body":"Susun tahapan secara logis, gunakan kemudian untuk urutan dan karena/sehingga untuk hubungan sebab-akibat. Bedakan kejadian berurutan dari bukti sebab; dua hal terjadi bersamaan belum tentu saling menyebabkan. Jangan menghilangkan syarat penting yang membuat penjelasan keliru."},{"type":"text","heading":"Contoh bertahap 2","body":"Air menguap; uap dapat mendingin dan mengembun menjadi tetes kecil di awan. Tetes tumbuh dan dapat jatuh sebagai hujan. Awan tampak tersusun tetes air/kristal es, bukan sekadar kumpulan uap tak terlihat."},{"type":"text","heading":"C. Menyusun penutup dan menyunting","body":"Penutup merangkum proses atau menjelaskan arti fenomena tanpa menambahkan klaim tak terbukti. Periksa istilah, urutan, kata hubung dan sumber. Gunakan diagram alur jika membantu, tetapi pastikan panah mempunyai arti. Mintalah teman menunjukkan bagian yang kurang jelas dan revisi penjelasan, bukan hanya ejaan."},{"type":"text","heading":"Contoh bertahap 3","body":"Ringkasan: panas membantu penguapan, pendinginan berhubungan dengan pengembunan, dan pertumbuhan tetes memungkinkan hujan. Tidak benar menyatakan semua awan pasti langsung menurunkan hujan."},{"type":"text","heading":"Kegiatan penerapan","body":"Susun teks 3–4 paragraf tentang es yang mencair memakai pengamatan aman. Buat pernyataan umum, urutan dengan sebab, lalu penutup. Tandai sumber informasi dan pisahkan yang diamati dari penjelasan yang dipelajari."},{"type":"text","heading":"Latihan mandiri","body":"1. Apa tujuan eksplanasi?\n2. Kata hubung sebab-akibat?\n3. Perbaiki: Semua awan langsung menjadi hujan.\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Menjelaskan proses atau sebab fenomena. Berbeda dari cerita pengalaman atau instruksi pembuatan.\n2. Contoh: karena, sehingga. Kata ini menyatakan hubungan alasan atau akibat.\n3. Tidak semua awan menghasilkan hujan. Tetes memerlukan kondisi dan pertumbuhan yang cukup.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Eksplanasi berfokus pada fenomena, proses dan sebab yang masuk akal. Tulis runtut dengan istilah tepat dan sumber yang dapat diperiksa."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jika tulisan menjadi prosedur, tanyakan apakah pembaca diminta melakukan langkah atau memahami proses alam. Pengayaan: buat diagram sebab dengan lebih dari satu kondisi.\nNilai pemahaman dengan bukti teks, keruntutan gagasan, ketepatan bahasa dan perbaikan setelah umpan balik. Tugas berbicara/menulis dinilai dari karya atau penyampaian, bukan skor pilihan ganda saja; bentuk lisan/dikte/alat bantu dapat disesuaikan.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('2239e517-6a7e-5dc7-a374-fecbfd91c459','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Ide Pokok & Kesimpulan Teks Laporan','petualangan-bahasa-indonesia-kelas-6-bab-1',6,'C','Petualangan · Bab 1','sedang','draft',25,'{"summary":"Pulau Kata bersama Bobo: Ide Pokok & Kesimpulan Teks Laporan. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-bahasa-indonesia-6","mentor":"Bobo","chapter_number":1,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan membaca tujuan dan hasil dengan contoh dan alasan.","Menjelaskan ide pokok dan rincian bukti dengan contoh dan alasan.","Menjelaskan menyusun simpulan yang terbatas dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Panduan Guru Bahasa Indonesia: Anak-Anak yang Mengubah Dunia","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-indonesia-anak-anak-yang-mengubah-dunia-untuk-sdmi-kelas-vi","audience":"teacher","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan membaca tujuan dan hasil dengan contoh dan alasan.\n2. Menjelaskan ide pokok dan rincian bukti dengan contoh dan alasan.\n3. Menjelaskan menyusun simpulan yang terbatas dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Laporan menyajikan hasil pengamatan atau pengumpulan informasi secara runtut. Ide pokok mengatur satu paragraf, sedangkan simpulan merangkum temuan yang menjawab tujuan laporan. Keduanya harus tetap berpijak pada data."},{"type":"text","heading":"A. Membaca tujuan dan hasil","body":"Temukan objek, tujuan, waktu dan cara pengumpulan data. Baca hasil sebelum menerima simpulan. Informasi tentang dua lokasi tidak otomatis mewakili seluruh daerah. Perhatikan jumlah sampel dan keterbatasan alat. Sumber data membantu pembaca menilai seberapa jauh temuan dapat digunakan."},{"type":"text","heading":"Contoh bertahap 1","body":"Laporan rekaan: enam pot diamati tiga hari; empat pot bertunas. Data ini menyatakan empat dari enam pot pada pengamatan itu, bukan semua benih selalu bertunas dalam tiga hari."},{"type":"text","heading":"B. Ide pokok dan rincian bukti","body":"Tentukan gagasan yang merangkum setiap paragraf dan daftar rincian pendukungnya. Bedakan angka hasil, penafsiran dan saran. Kalimat utama bisa muncul di posisi berbeda. Buat peta gagasan agar hubungan antarparagraf terlihat, lalu cari apakah ada paragraf yang tidak mendukung tujuan."},{"type":"text","heading":"Contoh bertahap 2","body":"Paragraf tentang pertumbuhan memuat tinggi hari pertama, kedua dan ketiga. Ide pokoknya perubahan pertumbuhan selama pengamatan, bukan salah satu angka hari saja."},{"type":"text","heading":"C. Menyusun simpulan yang terbatas","body":"Jawab tujuan dengan temuan paling penting dan sebut lingkup data. Jangan mengulang seluruh tabel atau memberi kepastian melebihi bukti. Jika membandingkan kelompok, jelaskan kondisi dan kemungkinan keterbatasan. Saran boleh diberikan terpisah serta diberi label, bukan dimasukkan sebagai hasil yang sudah terjadi."},{"type":"text","heading":"Contoh bertahap 3","body":"Simpulan sesuai: Pada enam pot yang diamati selama tiga hari, empat menunjukkan tunas. Simpulan tidak sesuai: Semua tanaman di kota tumbuh cepat karena empat pot bertunas."},{"type":"text","heading":"Kegiatan penerapan","body":"Amati jumlah daun pada tiga tanaman milik sendiri dengan izin dan tanpa merusak. Susun satu tabel dan dua paragraf hasil. Tulis ide pokok tiap paragraf serta simpulan yang hanya berlaku pada data pengamatan itu."},{"type":"text","heading":"Latihan mandiri","body":"1. Apa beda ide pokok dan simpulan laporan?\n2. Empat dari enam pot bertunas. Apakah semua pot bertunas?\n3. Mengapa waktu pengamatan dicatat?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Ide pokok menaungi paragraf; simpulan merangkum jawaban tujuan. Skala dan fungsinya berbeda.\n2. Tidak. Data menyebut empat, bukan enam.\n3. Hasil berlaku pada waktu/kondisi yang diamati. Pertumbuhan dan keadaan dapat berubah.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Periksa tujuan, metode dan hasil. Cari ide pokok setiap bagian, lalu simpulkan sesuai bukti dan batas sampel."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jika simpulan terlalu luas, minta siswa menambahkan frasa pada objek dan waktu yang diamati. Pengayaan: kritik simpulan yang tidak didukung data.\nNilai pemahaman dengan bukti teks, keruntutan gagasan, ketepatan bahasa dan perbaikan setelah umpan balik. Tugas berbicara/menulis dinilai dari karya atau penyampaian, bukan skor pilihan ganda saja; bentuk lisan/dikte/alat bantu dapat disesuaikan.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('564ecf78-06ae-54c1-862f-848e2614ee2c','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Menyusun Teks Pidato Persuasif','petualangan-bahasa-indonesia-kelas-6-bab-2',6,'C','Petualangan · Bab 2','sedang','draft',25,'{"summary":"Pulau Kata bersama Bobo: Menyusun Teks Pidato Persuasif. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-bahasa-indonesia-6","mentor":"Bobo","chapter_number":2,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan tujuan, pendengar dan susunan dengan contoh dan alasan.","Menjelaskan alasan, bukti dan tanggapan dengan contoh dan alasan.","Menjelaskan penyampaian dan revisi dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Panduan Guru Bahasa Indonesia: Anak-Anak yang Mengubah Dunia","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-indonesia-anak-anak-yang-mengubah-dunia-untuk-sdmi-kelas-vi","audience":"teacher","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan tujuan, pendengar dan susunan dengan contoh dan alasan.\n2. Menjelaskan alasan, bukti dan tanggapan dengan contoh dan alasan.\n3. Menjelaskan penyampaian dan revisi dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Pidato persuasif mengajak pendengar melakukan tindakan melalui alasan yang dapat dipahami. Ajakan yang baik menghargai pilihan, menggunakan bukti, dan tidak memanipulasi atau merendahkan kelompok lain."},{"type":"text","heading":"A. Tujuan, pendengar dan susunan","body":"Pilih satu tujuan nyata, misalnya mengembalikan buku tepat waktu. Kenali pendengar dan gunakan bahasa sesuai situasi. Susun pembukaan yang mengenalkan topik, isi yang memuat masalah dan alasan, lalu penutup berisi ajakan konkret. Sapaan tidak harus panjang; yang penting tujuan jelas."},{"type":"text","heading":"Contoh bertahap 1","body":"Pembukaan: Teman-teman, mari menjaga buku agar dapat dipakai bersama. Isi membahas akibat keterlambatan dan cara mengingat jadwal. Penutup mengajak memeriksa tanggal pinjam sebelum pulang."},{"type":"text","heading":"B. Alasan, bukti dan tanggapan","body":"Bedakan klaim dari alasan dan bukti. Data yang digunakan perlu sumber dan konteks; jangan membuat angka agar terdengar kuat. Pertimbangkan hambatan pendengar dan beri solusi wajar. Ajakan yang aman tidak memakai rasa takut palsu, hinaan, atau janji yang tidak dapat dipenuhi."},{"type":"text","heading":"Contoh bertahap 2","body":"Alasan: pengembalian tepat waktu memberi kesempatan pembaca lain. Solusi: menulis pengingat. Hindari klaim siapa terlambat pasti tidak peduli karena dapat ada hambatan yang perlu dibantu."},{"type":"text","heading":"C. Penyampaian dan revisi","body":"Latih lafal, volume dan jeda. Kontak mata dan sikap tubuh boleh disesuaikan kebutuhan pembicara; tidak semua orang harus memakai cara yang sama. Minta umpan balik tentang kejelasan ajakan dan kekuatan alasan. Perbaiki bagian membingungkan dan cek durasi tanpa mengorbankan makna."},{"type":"text","heading":"Contoh bertahap 3","body":"Ajakan Mari membawa botol isi ulang ketika memungkinkan lebih konkret daripada Kita harus sempurna. Sebut satu langkah yang dapat dicoba pendengar, lalu beri ruang pertanyaan."},{"type":"text","heading":"Kegiatan penerapan","body":"Tulis pidato 1–2 menit tentang merawat ruang belajar. Tandai klaim, alasan, bukti yang benar-benar tersedia, dan ajakan. Sampaikan kepada kelompok kecil atau rekam hanya dengan persetujuan semua yang terlibat."},{"type":"text","heading":"Latihan mandiri","body":"1. Buat ajakan konkret tentang buku.\n2. Mengapa angka pidato perlu sumber?\n3. Apa fungsi penutup?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Contoh: Periksa tanggal kembali dan siapkan buku malam sebelumnya. Ajakan menyebut tindakan yang dapat dilakukan.\n2. Agar klaim dapat diperiksa. Angka rekaan tidak menjadi bukti.\n3. Merangkum pesan dan mengajak tindakan. Pendengar tahu langkah berikutnya.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Pidato persuasif mempunyai tujuan, alasan berbukti dan ajakan konkret. Bahasa menghargai pendengar serta penyampaian jelas lebih kuat daripada tekanan."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jika naskah hanya slogan, tanyakan mengapa pendengar perlu bertindak dan langkah apa yang bisa dicoba. Pengayaan: tanggapi satu keberatan dengan alasan yang wajar.\nNilai pemahaman dengan bukti teks, keruntutan gagasan, ketepatan bahasa dan perbaikan setelah umpan balik. Tugas berbicara/menulis dinilai dari karya atau penyampaian, bukan skor pilihan ganda saja; bentuk lisan/dikte/alat bantu dapat disesuaikan.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('d4a806a4-ae95-54eb-971f-b3accebb699f','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Membaca Infografis & Data Visual','petualangan-bahasa-indonesia-kelas-6-bab-3',6,'C','Petualangan · Bab 3','sedang','draft',25,'{"summary":"Pulau Kata bersama Bobo: Membaca Infografis & Data Visual. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-bahasa-indonesia-6","mentor":"Bobo","chapter_number":3,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan membaca elemen visual dengan contoh dan alasan.","Menjelaskan mengecek klaim dan sumber dengan contoh dan alasan.","Menjelaskan menyampaikan temuan dengan batas dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Panduan Guru Bahasa Indonesia: Anak-Anak yang Mengubah Dunia","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-indonesia-anak-anak-yang-mengubah-dunia-untuk-sdmi-kelas-vi","audience":"teacher","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan membaca elemen visual dengan contoh dan alasan.\n2. Menjelaskan mengecek klaim dan sumber dengan contoh dan alasan.\n3. Menjelaskan menyampaikan temuan dengan batas dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Infografis menggabungkan teks, angka dan gambar untuk menyampaikan informasi. Tampilan menarik tidak menjamin data benar. Bacalah sumber, tanggal, kategori, satuan dan skala sebelum membuat kesimpulan."},{"type":"text","heading":"A. Membaca elemen visual","body":"Cari judul dan pertanyaan yang dijawab infografis. Periksa legenda warna/simbol, satuan, skala dan periode data. Ikon dapat hanya menjadi hiasan atau mewakili jumlah; legenda membedakannya. Persentase memerlukan keseluruhan yang jelas. Jangan menjumlah persentase dari kelompok dasar berbeda tanpa mengetahui datanya."},{"type":"text","heading":"Contoh bertahap 1","body":"Grafik 60% dari 20 responden berarti 12 orang, berbeda dari 60% dari 100 orang. Gambar ikon besar bukan otomatis menyatakan jumlah lebih besar bila tidak ada kunci."},{"type":"text","heading":"B. Mengecek klaim dan sumber","body":"Cocokkan judul atau slogan dengan angka yang benar-benar ditampilkan. Perhatikan sumbu terpotong, rentang waktu dipilih, atau kelompok yang tidak disertakan. Cari sumber asli bila ingin memeriksa metode. Data kecil dari satu kelas tidak langsung mewakili semua anak Indonesia."},{"type":"text","heading":"Contoh bertahap 2","body":"Infografis bertuliskan Semua anak memilih A tetapi datanya 12 dari 20 memilih A tidak sesuai. Angka itu menunjukkan mayoritas sampel, bukan semua anak."},{"type":"text","heading":"C. Menyampaikan temuan dengan batas","body":"Tulis temuan memakai angka dan konteks, pisahkan dari dugaan penyebab. Bandingkan secara adil menggunakan satuan yang sama. Bila sumber atau total responden hilang, nyatakan keterbatasan sebelum memakai informasi. Kutip sumber ketika membuat ulang visual dan hindari mengubah skala untuk membesar-besarkan pesan."},{"type":"text","heading":"Contoh bertahap 3","body":"Pada survei kelas rekaan dengan 20 responden, 12 memilih A dan 8 memilih B. Selisih empat responden. Mengapa mereka memilih A belum dijelaskan oleh grafik tersebut."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat infografis survei rekaan dua pilihan dengan 20 responden. Sertakan judul, periode, jumlah responden, sumber rekaan berlabel, dan diagram. Teman mengecek apakah slogan, jumlah, dan persentase konsisten."},{"type":"text","heading":"Latihan mandiri","body":"1. 30% dari 40 responden berapa orang?\n2. Apa yang perlu diketahui untuk membaca ikon?\n3. Apakah grafik membuktikan alasan pilihan tanpa pertanyaan alasan?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. 12 orang. 30/100 ×40 = 12.\n2. Apakah ada kunci nilai simbol. Ikon bisa hanya hiasan atau mewakili jumlah.\n3. Tidak. Jumlah pilihan tidak otomatis menjelaskan penyebab.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Baca judul, legenda, skala, satuan, total dan sumber. Pastikan klaim sesuai data dan simpulkan hanya dalam lingkup yang didukung."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jangan menyamakan batang paling besar dengan semua responden. Pengayaan: bandingkan dua infografis data sama dengan skala dan judul berbeda.\nNilai pemahaman dengan bukti teks, keruntutan gagasan, ketepatan bahasa dan perbaikan setelah umpan balik. Tugas berbicara/menulis dinilai dari karya atau penyampaian, bukan skor pilihan ganda saja; bentuk lisan/dikte/alat bantu dapat disesuaikan.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('0df07416-bcce-5b72-b200-fde45b6befbb','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Menulis Surat Resmi & Pribadi','petualangan-bahasa-indonesia-kelas-6-bab-4',6,'C','Petualangan · Bab 4','sedang','draft',25,'{"summary":"Pulau Kata bersama Bobo: Menulis Surat Resmi & Pribadi. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-bahasa-indonesia-6","mentor":"Bobo","chapter_number":4,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan tujuan, penerima dan ragam bahasa dengan contoh dan alasan.","Menjelaskan bagian surat dengan contoh dan alasan.","Menjelaskan menyunting dan mengirim dengan aman dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Urutan empat bab per kelas adalah pilihan aplikasi, bukan daftar isi resmi. Cakupan dan penempatan topik, termasuk ratusan, bilangan negatif, lingkaran dan statistika, menunggu pemeriksaan CP/ATP oleh guru.","source_refs":[{"title":"Panduan Guru Bahasa Indonesia: Anak-Anak yang Mengubah Dunia","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-bahasa-indonesia-anak-anak-yang-mengubah-dunia-untuk-sdmi-kelas-vi","audience":"teacher","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan tujuan, penerima dan ragam bahasa dengan contoh dan alasan.\n2. Menjelaskan bagian surat dengan contoh dan alasan.\n3. Menjelaskan menyunting dan mengirim dengan aman dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Surat menyampaikan pesan kepada penerima tertentu. Surat resmi mengikuti tujuan dan struktur lembaga, sedangkan surat pribadi lebih luwes. Keduanya memerlukan bahasa jelas dan perlindungan informasi pribadi."},{"type":"text","heading":"A. Tujuan, penerima dan ragam bahasa","body":"Tentukan apakah surat untuk teman atau untuk keperluan organisasi/sekolah. Surat resmi memakai ragam baku dan sopan; surat pribadi dapat lebih akrab sesuai hubungan. Isi tetap fokus pada maksud, bukan mencampur banyak permintaan yang tidak berkaitan. Gunakan alamat dan identitas rekaan untuk latihan."},{"type":"text","heading":"Contoh bertahap 1","body":"Surat mengundang kelas lain ke pameran memakai tujuan, jadwal dan penanggung jawab jelas. Surat kepada sahabat dapat menceritakan hobi dan menanyakan kabar tanpa nomor identitas."},{"type":"text","heading":"B. Bagian surat","body":"Surat resmi dapat memuat kepala surat, tanggal, nomor/lampiran/perihal sesuai kebutuhan, alamat tujuan, salam, isi, penutup dan identitas penanggung jawab. Surat pribadi lazim memuat tempat/tanggal, salam, isi, penutup dan nama pengirim. Tidak semua surat memerlukan lampiran; ikuti format lembaga tanpa menambah data yang tidak diperlukan."},{"type":"text","heading":"Contoh bertahap 2","body":"Undangan perlu menyebut kegiatan, hari/tanggal, waktu, tempat dan cara konfirmasi bila ada. Nomor surat membantu pencatatan resmi, bukan menggantikan penjelasan isi."},{"type":"text","heading":"C. Menyunting dan mengirim dengan aman","body":"Periksa nama penerima, tanggal, maksud, ejaan dan lampiran yang benar. Pastikan pengirim berwenang memakai nama lembaga dan tanda tangan. Untuk surat elektronik cek alamat tujuan sebelum mengirim; latihan tidak harus benar-benar dikirim. Jangan memasukkan password atau informasi pribadi pihak lain."},{"type":"text","heading":"Contoh bertahap 3","body":"Jika undangan menulis Senin tetapi tanggalnya jatuh pada hari lain, penerima dapat bingung. Periksa konsistensi jadwal sebelum surat disetujui penanggung jawab."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat dua surat latihan tentang pameran rekaan: undangan resmi dari panitia dan surat pribadi ke teman. Gunakan nama/alamat fiktif, bandingkan struktur serta ragamnya, dan lakukan pemeriksaan berpasangan tanpa mengirim ke orang lain."},{"type":"text","heading":"Latihan mandiri","body":"1. Apa isi penting undangan kegiatan?\n2. Apakah semua surat perlu nomor surat?\n3. Mengapa perlu memeriksa penerima sebelum kirim?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Kegiatan, jadwal, tempat, dan pihak pengundang. Penerima perlu tahu apa, kapan dan di mana.\n2. Tidak. Nomor lazim untuk administrasi resmi, tidak wajib pada surat pribadi.\n3. Agar pesan sampai pihak tepat dan data tidak salah dibagikan. Alamat keliru dapat menyebabkan kebocoran atau salah informasi.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Pilih ragam sesuai tujuan dan penerima. Susun bagian surat, perjelas isi, lalu cek identitas, jadwal, kewenangan dan data sebelum mengirim."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jangan meminta anak memakai alamat rumah asli dalam latihan. Pengayaan: sunting undangan dengan jadwal tidak konsisten dan lampiran yang tidak sesuai.\nNilai pemahaman dengan bukti teks, keruntutan gagasan, ketepatan bahasa dan perbaikan setelah umpan balik. Tugas berbicara/menulis dinilai dari karya atau penyampaian, bukan skor pilihan ganda saja; bentuk lisan/dikte/alat bantu dapat disesuaikan.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('31c9f4db-ff60-521e-b7ad-cb082c09b24e','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Mengenal Panca Indra Kita','petualangan-ipas-kelas-1-bab-1',1,'A','Petualangan · Bab 1','dasar','draft',20,'{"summary":"Pulau Eksplora bersama Ilmuwan Tobi: Mengenal Panca Indra Kita. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-ipas-1","mentor":"Ilmuwan Tobi","chapter_number":1,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan mata dan telinga mengumpulkan informasi dengan contoh dan alasan.","Menjelaskan hidung, lidah, dan kulit dengan contoh dan alasan.","Menjelaskan mencatat hasil, bukan menebak dengan contoh dan alasan."],"enrichment":true,"curriculum_note":"Pengayaan sains kelas 1–2. Bukan klaim CP IPAS wajib Fase A. Pendamping menyesuaikan kegiatan dengan kesiapan anak.","source_refs":[{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan mata dan telinga mengumpulkan informasi dengan contoh dan alasan.\n2. Menjelaskan hidung, lidah, dan kulit dengan contoh dan alasan.\n3. Menjelaskan mencatat hasil, bukan menebak dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Ilmuwan Tobi mengajakmu mengamati benda aman dengan indra. Bab sains kelas 1 ini merupakan pengayaan. Jangan mencicipi, menghirup dekat-dekat, atau menyentuh bahan yang tidak dikenal; mintalah bantuan pendamping."},{"type":"text","heading":"A. Mata dan telinga mengumpulkan informasi","body":"Mata membantu melihat warna, bentuk dan gerak dengan menerima cahaya. Telinga membantu mendengar bunyi. Pengamatan dapat memakai lebih dari satu indra, tetapi tidak harus semua. Orang dapat memakai kacamata, alat bantu dengar atau cara komunikasi berbeda; semua perlu dihargai. Jangan menatap matahari atau mendekatkan bunyi keras ke telinga."},{"type":"text","heading":"Contoh bertahap 1","body":"Kartu merah dikenali melalui penglihatan. Ketukan pelan pada meja dikenali melalui pendengaran. Jika tidak melihat sumber ketukan, kita belum tahu pasti benda mana yang mengetuk."},{"type":"text","heading":"B. Hidung, lidah, dan kulit","body":"Hidung membantu mengenali bau, lidah mengenali rasa pada makanan yang aman, dan kulit merasakan sentuhan serta perubahan suhu. Rasa makanan dipengaruhi juga oleh bau. Jangan memakai indra sebagai alat menguji keselamatan bahan asing. Benda panas, cairan pembersih dan tanaman tidak dikenal tidak boleh dicoba."},{"type":"text","heading":"Contoh bertahap 2","body":"Permukaan kain terasa halus melalui sentuhan kulit. Kita boleh menjelaskan rasa makanan sehari-hari yang sudah diizinkan pendamping, tetapi tidak menjilat benda untuk mengetahui namanya."},{"type":"text","heading":"C. Mencatat hasil, bukan menebak","body":"Gunakan kata yang tepat seperti merah, bulat, pelan atau halus. Pisahkan hasil yang benar-benar diamati dari dugaan. Indra dapat memiliki keterbatasan sehingga perlu alat atau pengamatan lain. Lima kelompok indra pada bab ini membantu mengenali lingkungan; tubuh juga mempunyai kemampuan merasakan keadaan lain yang dipelajari kemudian."},{"type":"text","heading":"Contoh bertahap 3","body":"Benda terasa halus adalah catatan sentuhan. Benda pasti mahal bukan hasil indra itu. Dua orang dapat memakai cara berbeda untuk mengenali bentuk benda secara aman."},{"type":"text","heading":"Kegiatan penerapan","body":"Dengan pendamping, amati tiga benda aman seperti kain, kartu dan sendok tanpa bagian tajam. Catat warna/bentuk, bunyi pelan jika ada, dan tekstur. Jangan gunakan rasa atau bau bahan asing. Jelaskan indra yang dipakai pada tiap catatan."},{"type":"text","heading":"Latihan mandiri","body":"1. Indra apa membantu mengenali warna?\n2. Apakah cairan asing boleh dicicipi untuk dikenal?\n3. Bedakan halus dan pasti mahal.\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Mata/penglihatan. Warna diketahui dari informasi cahaya.\n2. Tidak. Keselamatan tidak ditentukan dengan mencicipi bahan asing.\n3. Halus dapat diamati; mahal perlu informasi harga. Dugaan harga bukan hasil sentuhan.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Indra mengumpulkan informasi, bukan menjamin semua dugaan benar. Pilih cara pengamatan yang aman dan hargai perbedaan kemampuan."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jangan menguji anak dengan menutup akses alat bantu yang diperlukannya. Pengayaan: alat seperti kaca pembesar membantu pengamatan tetapi tetap dipakai aman.\nNilai pertanyaan pengamatan, catatan bukti, penjelasan hubungan, batas kesimpulan dan keselamatan. Bedakan yang diamati dari yang dipelajari dari sumber. Jangan meminta percobaan berisiko atau menilai tubuh/kemampuan pribadi teman.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('9ba273a4-5108-596f-9c7a-b4e3173105ba','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Merawat Tubuh & Kesehatan Gigi','petualangan-ipas-kelas-1-bab-2',1,'A','Petualangan · Bab 2','dasar','draft',20,'{"summary":"Pulau Eksplora bersama Ilmuwan Tobi: Merawat Tubuh & Kesehatan Gigi. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-ipas-1","mentor":"Ilmuwan Tobi","chapter_number":2,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan kebersihan tangan dan tubuh dengan contoh dan alasan.","Menjelaskan gigi, makanan dan perawatan dengan contoh dan alasan.","Menjelaskan kebiasaan seimbang dan meminta bantuan dengan contoh dan alasan."],"enrichment":true,"curriculum_note":"Pengayaan sains kelas 1–2. Bukan klaim CP IPAS wajib Fase A. Pendamping menyesuaikan kegiatan dengan kesiapan anak.","source_refs":[{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/","audience":"teacher"},{"title":"Kemenkes — Cara Mencegah Penyakit Gigi dan Mulut","url":"https://ayosehat.kemkes.go.id/cara-mencegah-penyakit-gigi-dan-mulut","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan kebersihan tangan dan tubuh dengan contoh dan alasan.\n2. Menjelaskan gigi, makanan dan perawatan dengan contoh dan alasan.\n3. Menjelaskan kebiasaan seimbang dan meminta bantuan dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Tubuh memerlukan kebiasaan bersih, makanan beragam, istirahat dan gerak sesuai kemampuan. Kegiatan merawat diri dapat berbeda dan boleh dibantu pendamping. Bab pengayaan ini bukan tempat mendiagnosis penyakit atau mengganti nasihat tenaga kesehatan."},{"type":"text","heading":"A. Kebersihan tangan dan tubuh","body":"Tangan dapat membawa kotoran yang tidak selalu terlihat. Cuci tangan memakai sabun dan air bersih sesuai petunjuk pendamping, terutama sebelum makan dan setelah dari toilet. Bersihkan tubuh dan ganti pakaian kotor. Gunakan alat pribadi dengan benar; jangan mencampur cairan pembersih atau memasukkannya ke mulut."},{"type":"text","heading":"Contoh bertahap 1","body":"Sesudah bermain tanah, tangan tampak kotor. Walau kotoran sudah tidak terlihat, mencuci dengan sabun tetap merupakan kebiasaan penting sebelum memegang makanan."},{"type":"text","heading":"B. Gigi, makanan dan perawatan","body":"Gigi membantu menggigit serta mengunyah. Sisa makanan dan plak perlu dibersihkan dengan menyikat gigi memakai sikat dan pasta gigi sesuai usia serta arahan pendamping/dokter gigi. Anjuran kebiasaan menyikat dua kali sehari mencakup setelah sarapan dan sebelum tidur. Jangan menelan pasta gigi. Pemeriksaan gigi dilakukan bersama orang dewasa."},{"type":"text","heading":"Contoh bertahap 2","body":"Tokoh menyikat seluruh permukaan gigi dengan lembut dan membersihkan alatnya. Menyikat sangat keras bukan berarti lebih bersih dan dapat mengganggu gusi."},{"type":"text","heading":"C. Kebiasaan seimbang dan meminta bantuan","body":"Makanan beragam, minum air sesuai kebutuhan, istirahat dan aktivitas fisik mendukung tubuh. Tidak perlu membandingkan bentuk tubuh atau kemampuan teman. Bila merasa sakit atau menemukan gigi bermasalah, beri tahu pendamping agar dibantu tenaga kesehatan. Jangan memakai obat milik orang lain atau melakukan percobaan pada tubuh."},{"type":"text","heading":"Contoh bertahap 3","body":"Jika gigi terasa sakit, tokoh menceritakan kepada pendamping dan meminta pemeriksaan. Ia tidak mencoba mencabut sendiri atau menganggap semua nyeri mempunyai penyebab sama."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat kartu urutan kebiasaan bersih untuk tokoh rekaan: sesudah toilet, sebelum makan, setelah sarapan dan menjelang tidur. Peragakan menyikat pada gambar/model, bukan memaksa pemeriksaan mulut teman."},{"type":"text","heading":"Latihan mandiri","body":"1. Mengapa tangan perlu dicuci sebelum makan?\n2. Apa fungsi gigi saat makan?\n3. Apa yang dilakukan bila gigi sakit?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Untuk membersihkan kotoran dan mengurangi perpindahan kuman. Tidak semua kotoran terlihat.\n2. Menggigit dan mengunyah. Makanan diperkecil sebelum ditelan.\n3. Beri tahu pendamping untuk mendapat bantuan. Jangan mendiagnosis atau mengobati sendiri dari pelajaran.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Merawat diri berarti kebersihan, perawatan gigi, kebiasaan seimbang dan meminta bantuan saat perlu. Bantuan orang lain bukan tanda gagal."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Gunakan model dan kata netral; hindari mempermalukan kebersihan atau kondisi tubuh anak. Pengayaan: alasan kebiasaan dibanding sekadar menghafal jadwal.\nNilai pertanyaan pengamatan, catatan bukti, penjelasan hubungan, batas kesimpulan dan keselamatan. Bedakan yang diamati dari yang dipelajari dari sumber. Jangan meminta percobaan berisiko atau menilai tubuh/kemampuan pribadi teman.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('e3d22fb8-19e4-5f84-ab1f-8c5dca30fc5a','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Mengenal Hewan & Tumbuhan Sekitar','petualangan-ipas-kelas-1-bab-3',1,'A','Petualangan · Bab 3','dasar','draft',20,'{"summary":"Pulau Eksplora bersama Ilmuwan Tobi: Mengenal Hewan & Tumbuhan Sekitar. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-ipas-1","mentor":"Ilmuwan Tobi","chapter_number":3,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan mengenali makhluk hidup dengan contoh dan alasan.","Menjelaskan membandingkan hewan dan tumbuhan dengan contoh dan alasan.","Menjelaskan mengamati dan merawat dengan bertanggung jawab dengan contoh dan alasan."],"enrichment":true,"curriculum_note":"Pengayaan sains kelas 1–2. Bukan klaim CP IPAS wajib Fase A. Pendamping menyesuaikan kegiatan dengan kesiapan anak.","source_refs":[{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan mengenali makhluk hidup dengan contoh dan alasan.\n2. Menjelaskan membandingkan hewan dan tumbuhan dengan contoh dan alasan.\n3. Menjelaskan mengamati dan merawat dengan bertanggung jawab dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Hewan dan tumbuhan dapat diamati tanpa ditangkap atau dirusak. Sebagai pengayaan kelas 1, kita mengenali ciri yang terlihat, kebutuhan hidup dan cara menjaga makhluk hidup di sekitar."},{"type":"text","heading":"A. Mengenali makhluk hidup","body":"Makhluk hidup menjalankan proses seperti tumbuh, membutuhkan air/nutrisi, bernapas dan menanggapi lingkungan. Gerak berpindah tempat bukan satu-satunya tanda hidup: tumbuhan hidup meski tidak berjalan. Benda bergerak karena didorong atau mesin tidak otomatis hidup. Amati beberapa ciri bersama-sama dan dalam waktu yang cukup."},{"type":"text","heading":"Contoh bertahap 1","body":"Tanaman dalam pot tumbuh dari minggu ke minggu. Mobil mainan bergerak saat didorong tetapi tidak tumbuh atau menjalankan proses kehidupan sendiri."},{"type":"text","heading":"B. Membandingkan hewan dan tumbuhan","body":"Hewan memperoleh makanan dari makhluk hidup lain atau produknya. Tumbuhan hijau umumnya membuat makanan melalui fotosintesis dengan bantuan cahaya. Keduanya memerlukan kondisi lingkungan yang sesuai, bukan semua membutuhkan jumlah air atau cahaya sama. Hindari menyimpulkan tumbuhan makan tanah; akar menyerap air serta mineral."},{"type":"text","heading":"Contoh bertahap 2","body":"Kucing memerlukan makanan dan air, sedangkan tanaman hijau memerlukan air, cahaya, udara dan mineral sesuai jenisnya. Menyiram terus-menerus belum tentu membuat tanaman lebih sehat."},{"type":"text","heading":"C. Mengamati dan merawat dengan bertanggung jawab","body":"Catat nama yang diketahui, bentuk, tempat ditemukan dan perubahan. Bila belum tahu nama, gunakan deskripsi tanpa menebak spesies sebagai pasti. Jangan memberi makan hewan liar, memetik tanaman sembarangan atau menyentuh hewan tidak dikenal. Perawatan hewan/tumbuhan milik orang lain perlu izin."},{"type":"text","heading":"Contoh bertahap 3","body":"Catatan Daun tanaman A bertambah satu dalam tiga hari dapat diperiksa. Menyebut semua tanaman berbunga besok tidak didukung pengamatan tersebut."},{"type":"text","heading":"Kegiatan penerapan","body":"Amati satu tanaman dan gambar hewan dari buku atau dari jarak aman. Buat tabel ciri, kebutuhan dan cara menjaga. Ulangi pengamatan tanaman beberapa hari dengan izin, tanpa memetik daun untuk menghitung."},{"type":"text","heading":"Latihan mandiri","body":"1. Apakah tanaman hidup walau tidak berjalan?\n2. Apakah mobil mainan yang bergerak otomatis hidup?\n3. Sebut tindakan aman mengamati hewan.\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Ya. Tumbuhan tumbuh dan menjalankan proses kehidupan.\n2. Tidak. Gerak saja bukan bukti seluruh proses kehidupan.\n3. Melihat dari jarak aman tanpa mengganggu. Hewan tidak perlu ditangkap untuk belajar cirinya.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Nilai ciri hidup secara bersama, bedakan kebutuhan tiap jenis, dan amati tanpa merusak. Tumbuhan tidak memakan tanah sebagai makanan utamanya."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jangan memakai bergerak sebagai satu-satunya pembeda. Pengayaan: gambar perubahan tanaman selama beberapa hari dan jelaskan bukti pertumbuhannya.\nNilai pertanyaan pengamatan, catatan bukti, penjelasan hubungan, batas kesimpulan dan keselamatan. Bedakan yang diamati dari yang dipelajari dari sumber. Jangan meminta percobaan berisiko atau menilai tubuh/kemampuan pribadi teman.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('3b4b12de-c3df-53d7-a7bd-75e8837ff597','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Benda Siang dan Malam Hari','petualangan-ipas-kelas-1-bab-4',1,'A','Petualangan · Bab 4','dasar','draft',20,'{"summary":"Pulau Eksplora bersama Ilmuwan Tobi: Benda Siang dan Malam Hari. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-ipas-1","mentor":"Ilmuwan Tobi","chapter_number":4,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan cahaya matahari dan kegiatan siang dengan contoh dan alasan.","Menjelaskan bulan, bintang, dan cahaya buatan dengan contoh dan alasan.","Menjelaskan mengapa siang dan malam berganti dengan contoh dan alasan."],"enrichment":true,"curriculum_note":"Pengayaan sains kelas 1–2. Bukan klaim CP IPAS wajib Fase A. Pendamping menyesuaikan kegiatan dengan kesiapan anak.","source_refs":[{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan cahaya matahari dan kegiatan siang dengan contoh dan alasan.\n2. Menjelaskan bulan, bintang, dan cahaya buatan dengan contoh dan alasan.\n3. Menjelaskan mengapa siang dan malam berganti dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Langit sekitar tampak berbeda pada siang dan malam. Kita mengamati dari tempat aman bersama pendamping, tanpa menatap matahari. Sains kelas 1–2 pada paket ini berstatus pengayaan, bukan klaim mapel IPAS wajib Fase A."},{"type":"text","heading":"A. Cahaya matahari dan kegiatan siang","body":"Matahari adalah bintang yang memancarkan cahaya sendiri. Pada siang di daerah kita, matahari menerangi lingkungan sehingga benda lebih mudah terlihat. Bayangan terbentuk ketika cahaya terhalang benda. Keadaan siang dapat berawan atau hujan; siang tidak selalu terasa panas dan tidak berarti semua tempat di bumi sedang siang."},{"type":"text","heading":"Contoh bertahap 1","body":"Pohon menghalangi sebagian cahaya dan membuat bayangan di tanah. Jangan mencari arah matahari dengan menatap langsung, bahkan saat tertutup awan."},{"type":"text","heading":"B. Bulan, bintang, dan cahaya buatan","body":"Bintang lain juga memancarkan cahaya, tetapi pada siang cahaya langit membuatnya sulit terlihat. Bulan tidak membuat cahaya tampak sendiri; cahaya matahari dipantulkannya. Bulan kadang terlihat pada siang, sehingga tidak boleh dijadikan satu-satunya tanda malam. Lampu merupakan sumber cahaya buatan untuk membantu kegiatan."},{"type":"text","heading":"Contoh bertahap 2","body":"Melihat bulan di sore hari tidak aneh. Bentuk terang bulan dapat berubah dari hari ke hari; ini berbeda dari lampu yang dinyalakan manusia."},{"type":"text","heading":"C. Mengapa siang dan malam berganti","body":"Bumi berputar pada porosnya. Bagian yang menghadap matahari mengalami siang, dan bagian yang membelakangi mengalami malam. Model bola dan lampu membantu melihat hubungan ini. Dalam model lampu jangan disamakan dengan matahari sungguhan; ukuran dan jaraknya tidak mewakili skala sebenarnya."},{"type":"text","heading":"Contoh bertahap 3","body":"Putar bola perlahan di depan lampu yang dipegang pendamping. Tanda pada bola masuk daerah terang lalu gelap, seperti pergantian siang-malam karena rotasi bumi."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat dua gambar pemandangan tempat rekaan pada siang dan malam. Beri label sumber cahaya dan benda yang hanya memantulkan cahaya. Amati langit malam dari rumah bersama pendamping tanpa bepergian sendirian atau memakai alat optik ke matahari."},{"type":"text","heading":"Latihan mandiri","body":"1. Apakah bulan memancarkan cahaya tampaknya sendiri?\n2. Apa yang membuat bayangan?\n3. Apa penyebab dasar siang-malam?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Tidak. Cahaya tampaknya berasal dari pantulan matahari.\n2. Cahaya terhalang benda. Daerah di belakang penghalang menerima lebih sedikit cahaya.\n3. Rotasi bumi. Tempat di permukaan bergantian menghadap dan membelakangi matahari.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Matahari dan bintang memancarkan cahaya, bulan memantulkan. Rotasi bumi menyebabkan siang-malam; bulan tidak hanya muncul malam."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Hindari kalimat matahari hilang saat malam. Pengayaan: catat bulan pada waktu berbeda bila aman dan cuaca memungkinkan.\nNilai pertanyaan pengamatan, catatan bukti, penjelasan hubungan, batas kesimpulan dan keselamatan. Bedakan yang diamati dari yang dipelajari dari sumber. Jangan meminta percobaan berisiko atau menilai tubuh/kemampuan pribadi teman.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('2b3b89b8-e05a-5bab-ad72-fb4951f9ea6b','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Benda Padat, Cair, dan Gas','petualangan-ipas-kelas-2-bab-1',2,'A','Petualangan · Bab 1','dasar','draft',20,'{"summary":"Pulau Eksplora bersama Ilmuwan Tobi: Benda Padat, Cair, dan Gas. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-ipas-2","mentor":"Ilmuwan Tobi","chapter_number":1,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan bentuk dan volume benda padat dengan contoh dan alasan.","Menjelaskan benda cair mengikuti wadah dengan contoh dan alasan.","Menjelaskan gas mengisi ruang dengan contoh dan alasan."],"enrichment":true,"curriculum_note":"Pengayaan sains kelas 1–2. Bukan klaim CP IPAS wajib Fase A. Pendamping menyesuaikan kegiatan dengan kesiapan anak.","source_refs":[{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan bentuk dan volume benda padat dengan contoh dan alasan.\n2. Menjelaskan benda cair mengikuti wadah dengan contoh dan alasan.\n3. Menjelaskan gas mengisi ruang dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Benda di sekitar tersusun dari materi. Padat, cair dan gas merupakan tiga wujud yang dipelajari. Amati benda aman tanpa memanaskan wadah tertutup, mencampur bahan, atau menghirup gas tidak dikenal."},{"type":"text","heading":"A. Bentuk dan volume benda padat","body":"Benda padat pada kondisi biasa mempunyai bentuk dan volume yang relatif tetap. Dipindah ke wadah lain tidak otomatis mengikuti seluruh bentuk wadah. Padat dapat keras atau lunak; sifat padat tidak berarti selalu berat. Benda dapat diubah bentuknya dengan gaya, dipotong atau dipanaskan, tetapi cara itu perlu mempertimbangkan keselamatan."},{"type":"text","heading":"Contoh bertahap 1","body":"Penghapus dipindahkan dari kotak ke gelas tetap berbentuk penghapus. Spons dapat ditekan tetapi tetap contoh benda padat berpori."},{"type":"text","heading":"B. Benda cair mengikuti wadah","body":"Cair mempunyai volume relatif tetap tetapi bentuknya mengikuti bagian wadah yang ditempati. Air mengalir dan permukaan tenangnya mendatar di bawah pengaruh gravitasi. Wadah berbeda dapat membuat permukaan terlihat lebih tinggi atau rendah tanpa mengubah jumlah air. Jangan menyimpulkan gelas tinggi selalu berisi lebih banyak."},{"type":"text","heading":"Contoh bertahap 2","body":"Air 100 mL dari gelas sempit dituang ke mangkuk lebar tetap sekitar 100 mL jika tidak tumpah. Bentuk dan tinggi permukaan berubah, volumenya tidak."},{"type":"text","heading":"C. Gas mengisi ruang","body":"Gas tidak mempunyai bentuk dan volume tetap seperti padat/cair; gas dapat mengisi ruang yang tersedia serta dimampatkan lebih mudah. Udara adalah campuran gas dan tetap ada walau tidak terlihat. Gas berbeda dari asap yang mengandung partikel. Jangan meniup balon sampai pecah dekat wajah atau menggunakan kantong untuk menutup kepala."},{"type":"text","heading":"Contoh bertahap 3","body":"Botol yang tampak kosong sebenarnya berisi udara. Gelembung yang keluar saat botol dimiringkan dalam air menunjukkan adanya udara, jika diperagakan aman oleh pendamping."},{"type":"text","heading":"Kegiatan penerapan","body":"Pendamping memindahkan penghapus dan menuang air antara dua wadah aman. Catat apa yang berubah dan tetap. Gunakan gambar balon untuk membahas udara; tidak perlu mencicipi bahan atau melakukan percobaan gas dari bahan kimia."},{"type":"text","heading":"Latihan mandiri","body":"1. Apakah benda padat selalu keras?\n2. Air dipindah tanpa tumpah: apa yang tetap?\n3. Botol tampak kosong berisi apa?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Tidak. Spons dan karet dapat lunak tetapi tetap padat.\n2. Volumenya relatif tetap. Bentuk mengikuti wadah, jumlah tidak otomatis berubah.\n3. Udara. Gas ada meskipun tidak terlihat.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Padat relatif tetap bentuk/volume; cair mengikuti wadah dengan volume relatif tetap; gas mengisi ruang tersedia. Ukuran tampilan bukan selalu banyak materi."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Bedakan cair dengan wadahnya dan gas dengan tidak ada apa-apa. Pengayaan: mengelompokkan beberapa benda dengan alasan, bukan berdasarkan warna.\nNilai pertanyaan pengamatan, catatan bukti, penjelasan hubungan, batas kesimpulan dan keselamatan. Bedakan yang diamati dari yang dipelajari dari sumber. Jangan meminta percobaan berisiko atau menilai tubuh/kemampuan pribadi teman.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('0d3f4d77-acd2-5f4c-a019-0b0ff276cb79','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Bagian-Bagian Tumbuhan & Fungsinya','petualangan-ipas-kelas-2-bab-2',2,'A','Petualangan · Bab 2','dasar','draft',20,'{"summary":"Pulau Eksplora bersama Ilmuwan Tobi: Bagian-Bagian Tumbuhan & Fungsinya. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-ipas-2","mentor":"Ilmuwan Tobi","chapter_number":2,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan akar dan batang dengan contoh dan alasan.","Menjelaskan daun dan pembuatan makanan dengan contoh dan alasan.","Menjelaskan bunga, buah dan biji dengan contoh dan alasan."],"enrichment":true,"curriculum_note":"Pengayaan sains kelas 1–2. Bukan klaim CP IPAS wajib Fase A. Pendamping menyesuaikan kegiatan dengan kesiapan anak.","source_refs":[{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan akar dan batang dengan contoh dan alasan.\n2. Menjelaskan daun dan pembuatan makanan dengan contoh dan alasan.\n3. Menjelaskan bunga, buah dan biji dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Tumbuhan mempunyai bagian dengan fungsi yang saling berkaitan. Tidak semua tumbuhan mempunyai bagian yang tampak persis sama. Gunakan gambar atau amati tanaman dengan izin tanpa mencabutnya."},{"type":"text","heading":"A. Akar dan batang","body":"Akar menambatkan tumbuhan serta menyerap air dan mineral. Pada sebagian tumbuhan akar juga menyimpan cadangan. Batang menopang bagian tumbuhan dan menjadi jalur pengangkutan. Air/mineral bergerak dari akar menuju bagian lain, sedangkan hasil fotosintesis disalurkan ke bagian yang membutuhkan. Akar bukan mulut yang memakan seluruh tanah."},{"type":"text","heading":"Contoh bertahap 1","body":"Batang membantu daun mendapat posisi menerima cahaya. Wortel merupakan contoh akar yang menyimpan cadangan, tetapi tidak semua akar membesar seperti wortel."},{"type":"text","heading":"B. Daun dan pembuatan makanan","body":"Daun banyak tumbuhan hijau menerima cahaya untuk fotosintesis. Tumbuhan menggunakan air dan karbon dioksida untuk membuat gula dengan bantuan energi cahaya; oksigen dihasilkan. Permukaan daun mempunyai struktur pertukaran gas. Jangan menyimpulkan semua daun harus hijau terang atau hanya daun yang pernah menjalankan fotosintesis."},{"type":"text","heading":"Contoh bertahap 2","body":"Tanaman di tempat sesuai kebutuhan cahayanya dapat tumbuh. Menutup seluruh daun terus-menerus dapat mengganggu proses, sehingga pengamatan tidak perlu merusak atau menahan kebutuhan tanaman."},{"type":"text","heading":"C. Bunga, buah dan biji","body":"Pada tumbuhan berbunga, bunga berkaitan dengan perkembangbiakan. Setelah proses yang sesuai, bagian bunga dapat berkembang menjadi buah yang melindungi biji. Biji dapat tumbuh menjadi tumbuhan baru bila syaratnya sesuai. Tidak semua bunga menghasilkan buah dan tidak semua tumbuhan berkembang biak hanya melalui biji."},{"type":"text","heading":"Contoh bertahap 3","body":"Biji kacang dapat berkecambah pada kondisi sesuai. Tumbuhan pisang juga dapat diperbanyak melalui tunas, sehingga biji bukan satu-satunya cara tumbuhan bertambah."},{"type":"text","heading":"Kegiatan penerapan","body":"Gambar satu tanaman berbunga yang dikenal, beri label akar-batang-daun-bunga/buah bila ada, dan hubungkan fungsi dengan panah. Jika bagian tidak terlihat, tulis belum diamati alih-alih mencabut tanaman."},{"type":"text","heading":"Latihan mandiri","body":"1. Fungsi akar yang utama pada banyak tumbuhan?\n2. Apa yang dilindungi buah pada banyak tumbuhan berbunga?\n3. Apakah semua tumbuhan hanya berkembang biak dengan biji?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Menambatkan serta menyerap air dan mineral. Bukan memakan tanah sebagai makanan jadi.\n2. Biji. Buah berkembang terkait bunga dan melindungi biji.\n3. Tidak. Ada tunas, spora dan cara lain tergantung jenisnya.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Akar, batang, daun dan alat perkembangbiakan saling mendukung. Bagian dan cara tumbuh bervariasi menurut jenis tumbuhan."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jangan mewajibkan setiap gambar tumbuhan mempunyai bunga yang sedang mekar. Pengayaan: bandingkan dua tanaman tanpa menganggap bagian tak terlihat pasti tidak ada.\nNilai pertanyaan pengamatan, catatan bukti, penjelasan hubungan, batas kesimpulan dan keselamatan. Bedakan yang diamati dari yang dipelajari dari sumber. Jangan meminta percobaan berisiko atau menilai tubuh/kemampuan pribadi teman.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('674952c8-98cc-59b5-8c8b-ebebc0b9f043','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Tempat Hidup Hewan (Darat & Air)','petualangan-ipas-kelas-2-bab-3',2,'A','Petualangan · Bab 3','dasar','draft',20,'{"summary":"Pulau Eksplora bersama Ilmuwan Tobi: Tempat Hidup Hewan (Darat & Air). Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-ipas-2","mentor":"Ilmuwan Tobi","chapter_number":3,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan kebutuhan dalam habitat dengan contoh dan alasan.","Menjelaskan ciri yang berkaitan dengan tempat hidup dengan contoh dan alasan.","Menjelaskan menjaga habitat dan tidak mengganggu dengan contoh dan alasan."],"enrichment":true,"curriculum_note":"Pengayaan sains kelas 1–2. Bukan klaim CP IPAS wajib Fase A. Pendamping menyesuaikan kegiatan dengan kesiapan anak.","source_refs":[{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan kebutuhan dalam habitat dengan contoh dan alasan.\n2. Menjelaskan ciri yang berkaitan dengan tempat hidup dengan contoh dan alasan.\n3. Menjelaskan menjaga habitat dan tidak mengganggu dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Habitat adalah tempat makhluk hidup memperoleh kebutuhan dan kondisi untuk hidup. Hewan darat, air, serta hewan yang memakai keduanya memiliki ciri beragam. Tempat ditemukan sekali belum selalu menunjukkan seluruh habitatnya."},{"type":"text","heading":"A. Kebutuhan dalam habitat","body":"Hewan membutuhkan makanan, air, tempat berlindung, ruang dan kondisi yang sesuai. Habitat menyediakan kebutuhan itu secara saling berkaitan. Tidak semua perairan sama: air tawar dan laut mempunyai kondisi berbeda. Memindahkan hewan ke tempat yang tampak mirip dapat membahayakan karena kebutuhan spesifiknya belum tentu terpenuhi."},{"type":"text","heading":"Contoh bertahap 1","body":"Ikan air tawar tidak boleh sembarang dipindahkan ke laut. Keduanya berair tetapi kadar garam serta kondisi lain berbeda."},{"type":"text","heading":"B. Ciri yang berkaitan dengan tempat hidup","body":"Bentuk tubuh, alat gerak dan alat pernapasan berhubungan dengan cara hidup. Ikan umumnya bernapas dengan insang, tetapi paus hidup di air dan bernapas dengan paru-paru. Hewan yang terbang tidak menghabiskan seluruh hidup tanpa daratan. Periksa beberapa ciri dan sumber sebelum membuat aturan untuk semua jenis."},{"type":"text","heading":"Contoh bertahap 2","body":"Bebek berenang dan berjalan di darat. Kakinya membantu bergerak di air, tetapi ia tetap perlu tempat lain untuk berbagai kegiatannya."},{"type":"text","heading":"C. Menjaga habitat dan tidak mengganggu","body":"Sampah, pencemaran dan kehilangan tempat berlindung dapat mengganggu hewan. Jaga kebersihan dan amati dari jarak aman. Hewan liar bukan mainan; jangan mengambilnya dari habitat untuk tugas sekolah. Jika melihat hewan terluka, beri tahu pendamping atau petugas yang sesuai tanpa mencoba menangani sendiri."},{"type":"text","heading":"Contoh bertahap 3","body":"Mengamati burung melalui gambar atau dari teras lebih aman daripada mengambil sarangnya. Menutup kembali tempat sampah membantu mengurangi gangguan lingkungan."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat kartu hewan dari buku: ikan air tawar, paus, kucing dan bebek. Catat tempat hidup, alat gerak/pernapasan yang diketahui, serta sumbernya. Buat kelompok dengan alasan dan tandai hewan yang memakai lebih dari satu lingkungan."},{"type":"text","heading":"Latihan mandiri","body":"1. Apa arti habitat?\n2. Apakah semua hewan air bernapas dengan insang?\n3. Bolehkah mengambil sarang untuk diamati?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Tempat dengan kebutuhan dan kondisi hidup organisme. Bukan sekadar alamat sekali terlihat.\n2. Tidak. Paus bernapas dengan paru-paru.\n3. Tidak sembarangan. Pengamatan harus menjaga hewan dan habitatnya.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Habitat menyediakan kebutuhan. Ciri hewan beragam; hindari aturan semua hewan air sama. Menjaga habitat lebih penting daripada mengumpulkan hewan."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Klasifikasi darat/air adalah penyederhanaan awal. Pengayaan: hewan yang memakai lingkungan berbeda pada tahap hidupnya seperti katak.\nNilai pertanyaan pengamatan, catatan bukti, penjelasan hubungan, batas kesimpulan dan keselamatan. Bedakan yang diamati dari yang dipelajari dari sumber. Jangan meminta percobaan berisiko atau menilai tubuh/kemampuan pribadi teman.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('d7bc62ed-d744-503c-91a0-a1461bb3b6c8','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Mengenal Cuaca: Cerah, Berawan, Hujan','petualangan-ipas-kelas-2-bab-4',2,'A','Petualangan · Bab 4','dasar','draft',20,'{"summary":"Pulau Eksplora bersama Ilmuwan Tobi: Mengenal Cuaca: Cerah, Berawan, Hujan. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-ipas-2","mentor":"Ilmuwan Tobi","chapter_number":4,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan mengamati cerah, berawan dan hujan dengan contoh dan alasan.","Menjelaskan cuaca berbeda dari musim dan iklim dengan contoh dan alasan.","Menjelaskan menyesuaikan kegiatan dengan aman dengan contoh dan alasan."],"enrichment":true,"curriculum_note":"Pengayaan sains kelas 1–2. Bukan klaim CP IPAS wajib Fase A. Pendamping menyesuaikan kegiatan dengan kesiapan anak.","source_refs":[{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan mengamati cerah, berawan dan hujan dengan contoh dan alasan.\n2. Menjelaskan cuaca berbeda dari musim dan iklim dengan contoh dan alasan.\n3. Menjelaskan menyesuaikan kegiatan dengan aman dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Cuaca adalah keadaan udara di tempat dan waktu tertentu. Keadaan dapat berubah dalam sehari. Amati dari tempat terlindung; jangan mencari pengalaman badai atau bermain di luar saat petir."},{"type":"text","heading":"A. Mengamati cerah, berawan dan hujan","body":"Cerah berarti langit relatif sedikit awan, berawan berarti awan menutupi sebagian besar sesuai pengamatan, dan hujan berarti air jatuh dari awan. Suhu, angin dan kelembapan juga bagian informasi cuaca. Langit berawan belum pasti segera hujan; jangan membuat kepastian hanya dari satu ciri."},{"type":"text","heading":"Contoh bertahap 1","body":"Pagi cerah dapat berubah berawan lalu hujan sore hari. Catatan perlu menyebut waktu supaya perbedaan tidak dianggap salah satu pengamat pasti keliru."},{"type":"text","heading":"B. Cuaca berbeda dari musim dan iklim","body":"Cuaca menggambarkan kondisi jangka pendek setempat. Musim adalah pola periode dalam setahun; iklim menggambarkan pola jangka panjang. Satu hari hujan tidak membuktikan seluruh musim atau iklim berubah. Pada kelas awal cukup bedakan catatan hari ini dari pola banyak hari."},{"type":"text","heading":"Contoh bertahap 2","body":"Hujan pada satu siang adalah catatan cuaca. Pernyataan suatu daerah biasanya basah pada bulan tertentu memerlukan pengamatan lebih lama, bukan satu foto."},{"type":"text","heading":"C. Menyesuaikan kegiatan dengan aman","body":"Gunakan informasi cuaca untuk memilih perlengkapan dan menyesuaikan kegiatan. Payung atau jas hujan membantu pada hujan biasa, tetapi bukan perlindungan memadai dari petir atau banjir. Ikuti arahan pendamping dan informasi resmi. Jangan menatap matahari untuk menilai cerah atau mengukur angin di tempat berbahaya."},{"type":"text","heading":"Contoh bertahap 3","body":"Jika terdengar petir saat kegiatan luar, tokoh menuju bangunan aman bersama pendamping. Ia tidak berlindung sendirian di bawah pohon tinggi atau bermain di genangan banjir."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat jurnal cuaca lima hari dengan waktu pengamatan yang sama dari jendela aman. Catat cerah/berawan/hujan dan perubahan yang terlihat. Bandingkan catatan tanpa menganggap lima hari sudah cukup menentukan iklim."},{"type":"text","heading":"Latihan mandiri","body":"1. Mengapa catatan cuaca perlu waktu dan tempat?\n2. Berawan selalu pasti hujan?\n3. Apakah satu hari hujan membuktikan iklim?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Karena cuaca berubah dan berbeda antarwilayah. Tanpa acuan, catatan sulit dibandingkan.\n2. Tidak. Awan saja tidak memastikan hujan di tempat itu.\n3. Tidak. Iklim memakai pola jangka panjang.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Catat cuaca dengan waktu/tempat. Bedakan kondisi harian dari pola panjang dan utamakan keselamatan saat merencanakan kegiatan."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jangan menyimpulkan dingin selalu hujan atau cerah selalu panas. Pengayaan: bandingkan informasi prakiraan resmi dengan pengamatan dan jelaskan bahwa prakiraan memiliki ketidakpastian.\nNilai pertanyaan pengamatan, catatan bukti, penjelasan hubungan, batas kesimpulan dan keselamatan. Bedakan yang diamati dari yang dipelajari dari sumber. Jangan meminta percobaan berisiko atau menilai tubuh/kemampuan pribadi teman.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('d46fb087-315c-557e-bb1e-74b2dc81e9dd','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Ciri-Ciri Makhluk Hidup','petualangan-ipas-kelas-3-bab-1',3,'B','Petualangan · Bab 1','sedang','draft',25,'{"summary":"Pulau Eksplora bersama Ilmuwan Tobi: Ciri-Ciri Makhluk Hidup. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-ipas-3","mentor":"Ilmuwan Tobi","chapter_number":1,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan tumbuh dan membutuhkan bahan/energi dengan contoh dan alasan.","Menjelaskan bernapas, bergerak dan merespons dengan contoh dan alasan.","Menjelaskan berkembang biak dan melihat kumpulan ciri dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Paket ini berfokus sains; unsur sosial IPAS tetap perlu paket lain. Topik dan penempatan kelas adalah pilihan aplikasi yang menunggu pemetaan TP/ATP dan review guru.","source_refs":[{"title":"Panduan Guru IPAS Kelas III (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-ilmu-pengetahuan-alam-dan-sosial-untuk-sdmi-kelas-iii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."},{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan tumbuh dan membutuhkan bahan/energi dengan contoh dan alasan.\n2. Menjelaskan bernapas, bergerak dan merespons dengan contoh dan alasan.\n3. Menjelaskan berkembang biak dan melihat kumpulan ciri dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Makhluk hidup dikenali melalui beberapa proses kehidupan, bukan satu ciri tampilan. Kita akan membandingkan organisme dengan benda tak hidup menggunakan pengamatan dan sumber, tanpa mengganggu makhluk hidup."},{"type":"text","heading":"A. Tumbuh dan membutuhkan bahan/energi","body":"Makhluk hidup membutuhkan bahan dan energi untuk menjalankan proses tubuhnya. Hewan makan, tumbuhan hijau membuat gula dengan fotosintesis. Pertumbuhan adalah perubahan ukuran/masa yang terkait proses kehidupan, bukan sekadar benda ditumpuk. Kondisi dan laju pertumbuhan berbeda antarjenis dan tahap hidup."},{"type":"text","heading":"Contoh bertahap 1","body":"Anak tanaman bertambah daun dan tinggi. Tumpukan pasir membesar karena ditambah dari luar, sehingga pertambahan besar itu bukan bukti pasir hidup."},{"type":"text","heading":"B. Bernapas, bergerak dan merespons","body":"Organisme melakukan pertukaran gas atau proses lain yang berkaitan dengan respirasi. Tumbuhan juga bernapas, tidak hanya hewan. Gerak dapat berupa perpindahan, pertumbuhan ke arah tertentu, atau perubahan bagian tubuh. Respons terhadap cahaya/sentuhan menunjukkan hubungan organisme dengan lingkungan, tetapi percobaan tidak boleh merusak."},{"type":"text","heading":"Contoh bertahap 2","body":"Tumbuhan dapat tumbuh condong ke arah cahaya sesuai jenis dan kondisi. Mobil bergerak karena mesin tidak otomatis hidup karena tidak mempunyai seluruh proses kehidupan sebagai organisme."},{"type":"text","heading":"C. Berkembang biak dan melihat kumpulan ciri","body":"Perkembangbiakan menghasilkan individu baru dan menjaga kelangsungan jenis. Tidak semua individu sedang atau dapat berkembang biak, sehingga ciri tersebut dipahami pada daur hidup/jenis, bukan tes tunggal setiap individu. Gunakan gabungan ciri dan sumber yang tepat untuk mengelompokkan. Biji dorman dapat tampak tidak aktif tetapi masih hidup."},{"type":"text","heading":"Contoh bertahap 3","body":"Telur hewan atau biji tidak selalu memperlihatkan gerak yang mudah dilihat. Pengamatan sekali tidak cukup untuk menyatakan semuanya benda mati."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat tabel tanaman, kucing dari gambar, batu dan sepeda. Isi ciri hidup dengan bukti yang dapat dilihat atau dipelajari dari sumber. Gunakan belum diamati untuk hal yang tidak terlihat; jangan mengarang hasil percobaan."},{"type":"text","heading":"Latihan mandiri","body":"1. Mengapa gerak saja tidak cukup?\n2. Apakah tumbuhan melakukan respirasi?\n3. Biji tampak diam pasti mati?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Benda tak hidup dapat digerakkan atau bermesin. Perlu kumpulan proses kehidupan.\n2. Ya. Tumbuhan juga memakai energi melalui proses respirasi.\n3. Tidak. Biji dapat dorman dan memerlukan kondisi untuk tumbuh.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Gunakan beberapa proses kehidupan dan rentang waktu yang sesuai. Bedakan belum terlihat dari tidak ada, serta organisme dari benda yang hanya bergerak."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jangan menjadikan kemampuan satu individu berkembang biak sebagai syarat untuk menghargai bahwa ia hidup. Pengayaan: tahap hidup yang cirinya sulit diamati langsung.\nNilai pertanyaan pengamatan, catatan bukti, penjelasan hubungan, batas kesimpulan dan keselamatan. Bedakan yang diamati dari yang dipelajari dari sumber. Jangan meminta percobaan berisiko atau menilai tubuh/kemampuan pribadi teman.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('c0afab51-c37c-5155-bdf2-46ca2ad02d76','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Siklus Hidup Hewan (Metamorfosis)','petualangan-ipas-kelas-3-bab-2',3,'B','Petualangan · Bab 2','sedang','draft',25,'{"summary":"Pulau Eksplora bersama Ilmuwan Tobi: Siklus Hidup Hewan (Metamorfosis). Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-ipas-3","mentor":"Ilmuwan Tobi","chapter_number":2,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan metamorfosis sempurna dengan contoh dan alasan.","Menjelaskan metamorfosis tidak sempurna dengan contoh dan alasan.","Menjelaskan membandingkan siklus dan kebutuhan dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Paket ini berfokus sains; unsur sosial IPAS tetap perlu paket lain. Topik dan penempatan kelas adalah pilihan aplikasi yang menunggu pemetaan TP/ATP dan review guru.","source_refs":[{"title":"Panduan Guru IPAS Kelas III (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-ilmu-pengetahuan-alam-dan-sosial-untuk-sdmi-kelas-iii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."},{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan metamorfosis sempurna dengan contoh dan alasan.\n2. Menjelaskan metamorfosis tidak sempurna dengan contoh dan alasan.\n3. Menjelaskan membandingkan siklus dan kebutuhan dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Siklus hidup menggambarkan tahapan organisme dari awal kehidupan hingga menghasilkan generasi berikutnya. Metamorfosis adalah perubahan bentuk selama perkembangan pada hewan tertentu. Gunakan gambar, bukan menangkap dan memelihara hewan tanpa pengetahuan."},{"type":"text","heading":"A. Metamorfosis sempurna","body":"Pada serangga seperti kupu-kupu, tahapnya telur, larva, pupa, dewasa. Larva dan dewasa dapat berbeda bentuk, makanan dan tempat hidup. Pupa bukan hewan mati atau sekadar tidur; perubahan berlangsung di dalamnya. Urutan gambar dapat berbentuk lingkaran karena individu dewasa menghasilkan telur generasi baru."},{"type":"text","heading":"Contoh bertahap 1","body":"Telur kupu-kupu menetas menjadi ulat, ulat menjadi pupa, lalu kupu-kupu dewasa keluar. Ulat tidak mempunyai sayap seperti kupu-kupu dewasa."},{"type":"text","heading":"B. Metamorfosis tidak sempurna","body":"Pada belalang, tahapnya telur, nimfa, dewasa; tidak ada tahap pupa. Nimfa mirip dewasa tetapi lebih kecil dan belum memiliki seluruh ciri dewasa. Pergantian kulit terjadi selama pertumbuhan. Istilah tidak sempurna adalah nama pola perkembangan, bukan penilaian bahwa hewannya kurang baik."},{"type":"text","heading":"Contoh bertahap 2","body":"Nimfa belalang mempunyai bentuk dasar seperti belalang dewasa, tetapi sayapnya belum berkembang penuh. Diagramnya tidak boleh ditambah kepompong."},{"type":"text","heading":"C. Membandingkan siklus dan kebutuhan","body":"Bandingkan jumlah tahap, perubahan bentuk dan kebutuhan di tiap tahap. Katak mempunyai telur, berudu dan tahap peralihan menuju dewasa, berbeda dari pola empat tahap serangga. Gangguan habitat pada satu tahap dapat memengaruhi kelangsungan populasi. Jangan menyamakan semua anak hewan dengan miniatur dewasanya."},{"type":"text","heading":"Contoh bertahap 3","body":"Berudu umumnya hidup di air dan menggunakan insang pada tahap awal, sedangkan katak dewasa mempunyai cara bernapas berbeda. Lingkungan yang dibutuhkan sepanjang daur hidup perlu dijaga."},{"type":"text","heading":"Kegiatan penerapan","body":"Susun kartu tahap kupu-kupu dan belalang. Hubungkan dengan panah lalu beri catatan bentuk serta kebutuhan. Jelaskan bahwa panah dari dewasa ke telur berarti reproduksi generasi berikutnya, bukan satu hewan berubah kembali menjadi telur."},{"type":"text","heading":"Latihan mandiri","body":"1. Tahap setelah larva pada kupu-kupu?\n2. Apakah belalang mempunyai pupa?\n3. Apa arti panah dewasa menuju telur?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Pupa. Urutan telur-larva-pupa-dewasa.\n2. Tidak. Pola telur-nimfa-dewasa.\n3. Dewasa menghasilkan generasi baru. Individu yang sama tidak kembali menjadi telur.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Metamorfosis sempurna mempunyai pupa, tidak sempurna tidak. Tahap dan kebutuhan berbeda menurut jenis; jaga habitat seluruh tahap."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jangan menyebut semua hewan bertelur mengalami metamorfosis sempurna. Pengayaan: bandingkan dua spesies dari sumber tepercaya dan tandai perbedaannya.\nNilai pertanyaan pengamatan, catatan bukti, penjelasan hubungan, batas kesimpulan dan keselamatan. Bedakan yang diamati dari yang dipelajari dari sumber. Jangan meminta percobaan berisiko atau menilai tubuh/kemampuan pribadi teman.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('c30d32b6-a80c-5e70-91f7-9da66753c336','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Perubahan Wujud Benda: Mencair, Membeku','petualangan-ipas-kelas-3-bab-3',3,'B','Petualangan · Bab 3','sedang','draft',25,'{"summary":"Pulau Eksplora bersama Ilmuwan Tobi: Perubahan Wujud Benda: Mencair, Membeku. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-ipas-3","mentor":"Ilmuwan Tobi","chapter_number":3,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan mencair dan membeku dengan contoh dan alasan.","Menjelaskan menguap dan mengembun dengan contoh dan alasan.","Menjelaskan mencatat bukti dan mengendalikan perbandingan dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Paket ini berfokus sains; unsur sosial IPAS tetap perlu paket lain. Topik dan penempatan kelas adalah pilihan aplikasi yang menunggu pemetaan TP/ATP dan review guru.","source_refs":[{"title":"Panduan Guru IPAS Kelas III (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-ilmu-pengetahuan-alam-dan-sosial-untuk-sdmi-kelas-iii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."},{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan mencair dan membeku dengan contoh dan alasan.\n2. Menjelaskan menguap dan mengembun dengan contoh dan alasan.\n3. Menjelaskan mencatat bukti dan mengendalikan perbandingan dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Air dapat berbentuk es, cair dan uap. Perubahan wujud berkaitan dengan perpindahan energi panas. Kita mengamati es mencair tanpa kompor; pemanasan dan bahan sangat panas hanya ditangani orang dewasa."},{"type":"text","heading":"A. Mencair dan membeku","body":"Mencair adalah perubahan padat menjadi cair ketika menerima energi yang cukup pada kondisi sesuai. Membeku adalah cair menjadi padat ketika melepaskan energi ke lingkungan. Untuk air murni pada tekanan biasa, titik beku/lebur sekitar 0°C. Campuran dan kondisi lain dapat mengubah suhu perubahan."},{"type":"text","heading":"Contoh bertahap 1","body":"Es di mangkuk menerima panas dari lingkungan lalu menjadi air. Air di freezer dapat melepas energi dan membeku; freezer tidak menambahkan zat bernama dingin."},{"type":"text","heading":"B. Menguap dan mengembun","body":"Menguap adalah cair menjadi gas dan dapat berlangsung pada permukaan tanpa harus mendidih. Mengembun adalah gas menjadi cair ketika kondisinya sesuai, misalnya pendinginan. Uap air gas tidak terlihat; kabut putih dekat air panas tersusun tetes sangat kecil. Jangan mendekatkan wajah ke air panas untuk mengamati."},{"type":"text","heading":"Contoh bertahap 2","body":"Genangan mengering karena sebagian air menguap. Tetes di luar gelas dingin berasal dari uap air udara yang mengembun, bukan otomatis air dari dalam gelas menembus dinding."},{"type":"text","heading":"C. Mencatat bukti dan mengendalikan perbandingan","body":"Bandingkan kondisi dengan hanya satu perbedaan yang hendak diuji, misalnya lokasi teduh dan hangat. Catat ukuran es awal, wadah, waktu dan hasil. Perubahan wujud air tidak berarti air hilang dari alam atau berubah menjadi zat baru. Bila ada tumpahan, jangan mengaku semua berkurang karena menguap."},{"type":"text","heading":"Contoh bertahap 3","body":"Dua es serupa di wadah sama dibandingkan pada tempat berbeda. Waktu mencair dicatat, dan perbedaan ukuran awal menjadi keterbatasan jika tidak benar-benar sama."},{"type":"text","heading":"Kegiatan penerapan","body":"Pendamping menaruh es dalam wadah aman di suhu ruang. Gambar perubahan pada interval waktu tetap. Letakkan gelas dingin lain dan amati bagian luarnya tanpa menjilat tetesan; bedakan bukti yang terlihat dari penjelasan sumber airnya."},{"type":"text","heading":"Latihan mandiri","body":"1. Es menjadi air disebut?\n2. Air menjadi es disebut?\n3. Dari mana tetes luar gelas dingin dapat berasal?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Mencair. Padat berubah menjadi cair.\n2. Membeku. Cair berubah menjadi padat dengan pelepasan energi.\n3. Uap air udara yang mengembun. Permukaan dingin membantu pengembunan.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Kenali arah perubahan: padat-cair, cair-gas dan sebaliknya. Energi berpindah; catatan pengamatan harus mempertimbangkan kondisi dan tumpahan."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jangan menyebut uap air pasti asap putih. Pengayaan: mengapa penguapan dapat terjadi pada pakaian di suhu ruang tanpa mendidih.\nNilai pertanyaan pengamatan, catatan bukti, penjelasan hubungan, batas kesimpulan dan keselamatan. Bedakan yang diamati dari yang dipelajari dari sumber. Jangan meminta percobaan berisiko atau menilai tubuh/kemampuan pribadi teman.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('4ba526cb-270f-5785-96ad-bc5d7766e049','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Sumber Energi di Sekitar Kita','petualangan-ipas-kelas-3-bab-4',3,'B','Petualangan · Bab 4','sedang','draft',25,'{"summary":"Pulau Eksplora bersama Ilmuwan Tobi: Sumber Energi di Sekitar Kita. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-ipas-3","mentor":"Ilmuwan Tobi","chapter_number":4,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan matahari, makanan dan bahan bakar dengan contoh dan alasan.","Menjelaskan bentuk energi dan perpindahannya dengan contoh dan alasan.","Menjelaskan menggunakan energi secara bertanggung jawab dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Paket ini berfokus sains; unsur sosial IPAS tetap perlu paket lain. Topik dan penempatan kelas adalah pilihan aplikasi yang menunggu pemetaan TP/ATP dan review guru.","source_refs":[{"title":"Panduan Guru IPAS Kelas III (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/panduan-guru-ilmu-pengetahuan-alam-dan-sosial-untuk-sdmi-kelas-iii-edisi-revisi","audience":"teacher","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."},{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan matahari, makanan dan bahan bakar dengan contoh dan alasan.\n2. Menjelaskan bentuk energi dan perpindahannya dengan contoh dan alasan.\n3. Menjelaskan menggunakan energi secara bertanggung jawab dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Energi memungkinkan perubahan dan kegiatan. Kita mengenali sumber serta bentuk energi dari contoh sehari-hari. Energi tidak sama dengan benda; benda dapat menyimpan atau menyalurkan energi."},{"type":"text","heading":"A. Matahari, makanan dan bahan bakar","body":"Matahari memberi energi cahaya dan panas. Tumbuhan menggunakan cahaya untuk membuat makanan; hewan dan manusia memperoleh energi kimia dari makanan. Bahan bakar juga menyimpan energi kimia. Kita tidak perlu membakar sesuatu untuk membuktikan energi dan tidak boleh mencicipi bahan bakar."},{"type":"text","heading":"Contoh bertahap 1","body":"Energi untuk bergerak berasal dari proses tubuh menggunakan makanan, bukan dari warna makanannya. Menjemur pakaian memanfaatkan perpindahan energi dari lingkungan dan matahari."},{"type":"text","heading":"B. Bentuk energi dan perpindahannya","body":"Energi dapat dibahas sebagai gerak, panas, cahaya, bunyi, listrik atau energi tersimpan. Pada satu alat beberapa bentuk dapat muncul bersamaan. Panas mengalir karena perbedaan suhu; benda panas tidak selalu bercahaya. Bunyi berasal dari getaran dan dapat membawa energi melalui medium."},{"type":"text","heading":"Contoh bertahap 2","body":"Lampu memakai listrik dan menghasilkan cahaya serta panas. Kipas mengubah sebagian energi listrik menjadi gerak udara, sementara bunyi dan panas juga dapat muncul."},{"type":"text","heading":"C. Menggunakan energi secara bertanggung jawab","body":"Cari layanan yang dibutuhkan, lalu hindari pemakaian sia-sia. Mematikan lampu yang tidak diperlukan mengurangi kebutuhan energi listrik. Sumber dan cara produksi energi memiliki dampak, sehingga penghematan bukan sekadar mematikan semua alat penting. Keselamatan dan kebutuhan kesehatan tetap diutamakan."},{"type":"text","heading":"Contoh bertahap 3","body":"Ruangan dengan cahaya alami cukup dapat mengurangi lampu tanpa mengganggu membaca. Jangan mematikan alat medis atau perangkat penting tanpa arahan penanggung jawab."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat tabel tiga alat: sumber energi masuk, perubahan yang terlihat dan cara menghindari pemborosan. Gunakan gambar atau pengamatan dari luar tanpa membuka alat, menyentuh stopkontak, atau mencoba api."},{"type":"text","heading":"Latihan mandiri","body":"1. Sumber energi tubuh sehari-hari?\n2. Kipas memakai listrik menjadi terutama apa?\n3. Apa contoh hemat energi aman?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Makanan. Tubuh memanfaatkan energi kimia makanan.\n2. Gerak. Motor dan baling-baling menggerakkan udara.\n3. Mematikan lampu yang tidak diperlukan sesuai izin. Hindari mematikan perangkat penting.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Sumber menyediakan energi, bentuk menunjukkan cara energi tampak/tersimpan, dan alat mengubah serta menyalurkannya. Gunakan sesuai kebutuhan."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jangan menyamakan listrik dengan satu-satunya energi. Pengayaan: satu alat dapat mempunyai beberapa keluaran energi, tidak semuanya berguna untuk tujuan utama.\nNilai pertanyaan pengamatan, catatan bukti, penjelasan hubungan, batas kesimpulan dan keselamatan. Bedakan yang diamati dari yang dipelajari dari sumber. Jangan meminta percobaan berisiko atau menilai tubuh/kemampuan pribadi teman.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('95409bc1-4e5d-579d-a60c-9f0258e99204','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Proses Fotosintesis Tumbuhan','petualangan-ipas-kelas-4-bab-1',4,'B','Petualangan · Bab 1','sedang','draft',25,'{"summary":"Pulau Eksplora bersama Ilmuwan Tobi: Proses Fotosintesis Tumbuhan. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-ipas-4","mentor":"Ilmuwan Tobi","chapter_number":1,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan bahan dan energi yang diperlukan dengan contoh dan alasan.","Menjelaskan gula, oksigen dan respirasi dengan contoh dan alasan.","Menjelaskan penyelidikan dan keterbatasan model dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Paket ini berfokus sains; unsur sosial IPAS tetap perlu paket lain. Topik dan penempatan kelas adalah pilihan aplikasi yang menunggu pemetaan TP/ATP dan review guru.","source_refs":[{"title":"Buku Interaktif IPAS Kelas IV (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/buku-interaktif-ilmu-pengetahuan-alam-dan-sosial-untuk-sd-mi-kelas-iv-edisi-revisi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."},{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan bahan dan energi yang diperlukan dengan contoh dan alasan.\n2. Menjelaskan gula, oksigen dan respirasi dengan contoh dan alasan.\n3. Menjelaskan penyelidikan dan keterbatasan model dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Tumbuhan hijau membuat gula melalui fotosintesis. Kita mempelajari bahan, energi dan hasilnya tanpa menyamakan tanah dengan makanan jadi. Peran tumbuhan juga terkait jaringan kehidupan dan kualitas lingkungan."},{"type":"text","heading":"A. Bahan dan energi yang diperlukan","body":"Fotosintesis memakai air dan karbon dioksida dengan energi cahaya yang ditangkap pigmen seperti klorofil. Akar banyak tumbuhan menyerap air dan mineral; karbon dioksida masuk melalui pertukaran gas. Mineral diperlukan tetapi bukan pengganti bahan karbon dioksida dalam pembentukan gula. Kebutuhan cahaya berbeda menurut jenis."},{"type":"text","heading":"Contoh bertahap 1","body":"Tanaman memperoleh air dari lingkungan akar dan karbon dioksida dari udara. Daun menerima cahaya; tanah bukan makanan organik yang ditelan seperti nasi."},{"type":"text","heading":"B. Gula, oksigen dan respirasi","body":"Hasil fotosintesis mencakup gula dan oksigen. Gula dapat digunakan sebagai sumber bahan/energi, diangkut atau disimpan. Tumbuhan juga melakukan respirasi siang dan malam untuk menggunakan energi; tidak benar menyebut tumbuhan hanya bernapas pada malam. Keseimbangan gas yang terukur bergantung banyak proses."},{"type":"text","heading":"Contoh bertahap 2","body":"Sebagian gula dapat disimpan menjadi pati. Tumbuhan tetap membutuhkan proses respirasi walau sedang membuat gula pada saat mendapat cahaya."},{"type":"text","heading":"C. Penyelidikan dan keterbatasan model","body":"Pengamatan pertumbuhan saja tidak langsung mengukur laju fotosintesis. Kondisi air, cahaya, jenis dan umur tumbuhan perlu dipertimbangkan. Percobaan pembuktian pati dengan bahan panas/kimia bukan kegiatan mandiri anak. Gunakan model alur dan data yang disediakan pendamping, serta jaga kebutuhan tanaman."},{"type":"text","heading":"Contoh bertahap 3","body":"Dua tanaman berbeda jenis yang satu lebih tinggi tidak membuktikan cahaya sebagai satu-satunya penyebab. Perbandingan yang adil menjaga faktor lain serupa dan mencatat keterbatasan."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat diagram dengan panah air, karbon dioksida dan cahaya menuju tumbuhan, lalu gula dan oksigen sebagai hasil. Tambahkan catatan respirasi juga berlangsung. Amati tanaman sehat tanpa menutup seluruh cahaya atau merusaknya."},{"type":"text","heading":"Latihan mandiri","body":"1. Dua bahan fotosintesis selain energi cahaya?\n2. Apa salahnya tumbuhan makan tanah?\n3. Kapan tumbuhan berespirasi?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Air dan karbon dioksida. Cahaya memberi energi, bukan bahan yang ditimbang seperti air.\n2. Akar menyerap air/mineral; gula dibuat melalui fotosintesis. Tanah bukan makanan jadi.\n3. Siang dan malam. Respirasi adalah proses penggunaan energi yang terus dibutuhkan.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Cahaya memberi energi untuk membuat gula dari air dan karbon dioksida, dengan oksigen sebagai hasil. Tumbuhan juga berespirasi."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Pisahkan bahan, energi dan hasil pada diagram. Pengayaan: jelaskan mengapa pertumbuhan juga dipengaruhi air, mineral dan kondisi lain, bukan cahaya saja.\nNilai pertanyaan pengamatan, catatan bukti, penjelasan hubungan, batas kesimpulan dan keselamatan. Bedakan yang diamati dari yang dipelajari dari sumber. Jangan meminta percobaan berisiko atau menilai tubuh/kemampuan pribadi teman.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('846fb75e-71dd-57e3-9004-89a79502b282','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Gaya di Sekitar Kita: Otot, Gesek, Magnet','petualangan-ipas-kelas-4-bab-2',4,'B','Petualangan · Bab 2','sedang','draft',25,'{"summary":"Pulau Eksplora bersama Ilmuwan Tobi: Gaya di Sekitar Kita: Otot, Gesek, Magnet. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-ipas-4","mentor":"Ilmuwan Tobi","chapter_number":2,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan gaya otot dan akibat gaya dengan contoh dan alasan.","Menjelaskan gaya gesek dengan contoh dan alasan.","Menjelaskan gaya magnet dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Paket ini berfokus sains; unsur sosial IPAS tetap perlu paket lain. Topik dan penempatan kelas adalah pilihan aplikasi yang menunggu pemetaan TP/ATP dan review guru.","source_refs":[{"title":"Buku Interaktif IPAS Kelas IV (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/buku-interaktif-ilmu-pengetahuan-alam-dan-sosial-untuk-sd-mi-kelas-iv-edisi-revisi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."},{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan gaya otot dan akibat gaya dengan contoh dan alasan.\n2. Menjelaskan gaya gesek dengan contoh dan alasan.\n3. Menjelaskan gaya magnet dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Gaya adalah dorongan atau tarikan yang dapat memengaruhi gerak dan bentuk. Perubahan gerak bergantung resultan gaya serta keadaan benda. Kita memakai benda ringan; tidak mencoba mengangkat beban berat atau bermain magnet kecil tanpa pendamping."},{"type":"text","heading":"A. Gaya otot dan akibat gaya","body":"Otot menghasilkan gaya saat kita mendorong, menarik atau memegang. Gaya dapat membuat benda mulai bergerak, mempercepat, memperlambat, berubah arah atau berubah bentuk. Tidak semua gaya menghasilkan gerak yang terlihat karena dapat seimbang. Menekan dinding tetap memberi gaya meskipun dinding tidak berpindah."},{"type":"text","heading":"Contoh bertahap 1","body":"Mendorong mobil mainan dapat menambah kecepatannya. Dua dorongan berlawanan yang seimbang dapat membuat posisi tetap; ini bukan berarti tidak ada gaya."},{"type":"text","heading":"B. Gaya gesek","body":"Gesekan muncul pada permukaan bersentuhan dan cenderung menghambat gerak relatif. Besarnya dipengaruhi keadaan permukaan serta gaya tekan. Gesekan membantu berjalan dan mengerem, tetapi juga dapat menyebabkan panas atau keausan. Permukaan licin tidak berarti tanpa gesekan sama sekali."},{"type":"text","heading":"Contoh bertahap 2","body":"Sol sepatu bertekstur membantu cengkeraman. Saat buku digeser di atas kain kasar, hambatannya dapat berbeda dibanding meja licin pada kondisi yang sebanding."},{"type":"text","heading":"C. Gaya magnet","body":"Magnet mempunyai kutub yang dapat tarik-menarik atau tolak-menolak: kutub sejenis menolak, berbeda menarik. Magnet menarik bahan tertentu seperti besi, bukan semua logam. Gaya magnet dapat bekerja tanpa sentuhan langsung pada jarak dekat. Jauhkan magnet kecil dari mulut serta perangkat atau implan yang sensitif sesuai arahan pendamping."},{"type":"text","heading":"Contoh bertahap 3","body":"Penjepit kertas besi dapat tertarik, sedangkan kertas dan banyak benda aluminium tidak tertarik seperti besi. Kesimpulan harus menyebut bahan yang diuji, bukan semua logam."},{"type":"text","heading":"Kegiatan penerapan","body":"Dengan benda ringan, bandingkan gerak buku kecil di dua alas sambil menjaga cara dorong serupa. Pendamping dapat menunjukkan magnet besar aman pada benda yang diketahui bahannya. Catat tertarik/tidak dan keterbatasan uji."},{"type":"text","heading":"Latihan mandiri","body":"1. Apakah benda diam berarti tak ada gaya?\n2. Sebut manfaat gesekan.\n3. Apakah semua logam tertarik magnet?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Tidak. Gaya dapat saling seimbang.\n2. Contoh: membantu sepatu mencengkeram lantai. Gesekan tidak selalu merugikan.\n3. Tidak. Magnet kuat menarik bahan tertentu, bukan semua logam.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Gaya dapat mengubah gerak/bentuk atau seimbang. Gesekan bermanfaat dan dapat menghambat; magnet memengaruhi bahan tertentu serta kutubnya."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jangan menyebut gaya selalu membuat bergerak. Pengayaan: gambarkan dua panah gaya berlawanan sama besar dan jelaskan keseimbangannya.\nNilai pertanyaan pengamatan, catatan bukti, penjelasan hubungan, batas kesimpulan dan keselamatan. Bedakan yang diamati dari yang dipelajari dari sumber. Jangan meminta percobaan berisiko atau menilai tubuh/kemampuan pribadi teman.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('08856a61-e5ad-5c53-b125-258b01069725','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Perubahan Bentuk Energi','petualangan-ipas-kelas-4-bab-3',4,'B','Petualangan · Bab 3','sedang','draft',25,'{"summary":"Pulau Eksplora bersama Ilmuwan Tobi: Perubahan Bentuk Energi. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-ipas-4","mentor":"Ilmuwan Tobi","chapter_number":3,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan masukan dan keluaran energi dengan contoh dan alasan.","Menjelaskan perubahan bertahap dengan contoh dan alasan.","Menjelaskan efisiensi dan keputusan hemat dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Paket ini berfokus sains; unsur sosial IPAS tetap perlu paket lain. Topik dan penempatan kelas adalah pilihan aplikasi yang menunggu pemetaan TP/ATP dan review guru.","source_refs":[{"title":"Buku Interaktif IPAS Kelas IV (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/buku-interaktif-ilmu-pengetahuan-alam-dan-sosial-untuk-sd-mi-kelas-iv-edisi-revisi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."},{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan masukan dan keluaran energi dengan contoh dan alasan.\n2. Menjelaskan perubahan bertahap dengan contoh dan alasan.\n3. Menjelaskan efisiensi dan keputusan hemat dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Energi tidak dibuat dari ketiadaan oleh alat. Alat mengubah energi masuk menjadi beberapa bentuk energi keluar. Kita memetakan perubahan itu dengan panah dan membedakan keluaran berguna dari yang tidak menjadi tujuan utama."},{"type":"text","heading":"A. Masukan dan keluaran energi","body":"Tentukan sumber energi masuk, proses alat, dan perubahan yang tampak. Satu alat dapat menghasilkan gerak, panas, bunyi dan cahaya sekaligus. Energi total tetap dilacak, walau sebagian menyebar ke lingkungan sehingga tidak mudah dipakai lagi. Jangan menyebut energi hilang begitu saja tanpa menjelaskan perpindahan."},{"type":"text","heading":"Contoh bertahap 1","body":"Senter memakai energi kimia baterai yang diubah melalui listrik menjadi cahaya dan panas. Cahaya membantu melihat; panas bukan tujuan utama senter."},{"type":"text","heading":"B. Perubahan bertahap","body":"Rangkaian energi dapat melalui beberapa langkah. Pada pembangkit tertentu bahan bakar memanaskan air, uap memutar turbin dan generator menghasilkan listrik. Pada panel surya, energi cahaya diubah menjadi listrik tanpa perlu langkah membakar bahan bakar di panel. Teknologi berbeda mempunyai proses berbeda, tidak semua pembangkit sama."},{"type":"text","heading":"Contoh bertahap 2","body":"Kipas: energi listrik → gerak motor/baling-baling → gerak udara, disertai panas dan bunyi. Menyebut listrik menjadi angin berarti perlu diperjelas sebagai energi gerak udara."},{"type":"text","heading":"C. Efisiensi dan keputusan hemat","body":"Efisiensi membandingkan keluaran yang diinginkan dengan energi masuk. Alat yang lebih efisien dapat memberi layanan sama dengan masukan lebih sedikit. Perbandingan perlu pada layanan setara, bukan hanya ukuran alat. Matikan yang tidak diperlukan dengan izin, rawat alat dan jangan membuka bagian listrik untuk percobaan."},{"type":"text","heading":"Contoh bertahap 3","body":"Dua lampu sama terang dapat memakai daya berbeda. Untuk menilai penghematan, periksa terang yang dibutuhkan dan lama pemakaian, bukan hanya warna kotak lampunya."},{"type":"text","heading":"Kegiatan penerapan","body":"Gambar alur energi senter, kipas dan manusia bersepeda berdasarkan gambar alat. Tandai keluaran utama dan keluaran lain. Buat satu usulan mengurangi pemborosan dengan tetap mempertahankan fungsi yang diperlukan."},{"type":"text","heading":"Latihan mandiri","body":"1. Energi masuk baterai senter tersimpan sebagai?\n2. Apakah panas lampu berarti energi lenyap?\n3. Bandingkan efisiensi dua lampu pada kondisi apa?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Energi kimia. Baterai menyalurkan energi melalui rangkaian listrik.\n2. Tidak. Energi berpindah ke lingkungan sebagai panas.\n3. Layanan cahaya dan waktu yang sebanding. Perbandingan harus adil.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Petakan energi masuk, perubahan dan semua keluaran. Energi menyebar tetapi tidak hilang dari pembukuan; efisiensi dinilai untuk layanan yang sama."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Bunyi dan panas jangan otomatis diabaikan dalam diagram energi. Pengayaan: jelaskan energi yang masih ada namun kurang mudah dimanfaatkan setelah menyebar.\nNilai pertanyaan pengamatan, catatan bukti, penjelasan hubungan, batas kesimpulan dan keselamatan. Bedakan yang diamati dari yang dipelajari dari sumber. Jangan meminta percobaan berisiko atau menilai tubuh/kemampuan pribadi teman.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('88807bad-1c67-5d80-ab27-1419e468d8e2','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Siklus Air & Pelestarian Alam','petualangan-ipas-kelas-4-bab-4',4,'B','Petualangan · Bab 4','sedang','draft',25,'{"summary":"Pulau Eksplora bersama Ilmuwan Tobi: Siklus Air & Pelestarian Alam. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-ipas-4","mentor":"Ilmuwan Tobi","chapter_number":4,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan penguapan dan pembentukan awan dengan contoh dan alasan.","Menjelaskan hujan, aliran dan peresapan dengan contoh dan alasan.","Menjelaskan pelestarian dan bukti tindakan dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Paket ini berfokus sains; unsur sosial IPAS tetap perlu paket lain. Topik dan penempatan kelas adalah pilihan aplikasi yang menunggu pemetaan TP/ATP dan review guru.","source_refs":[{"title":"Buku Interaktif IPAS Kelas IV (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/buku-interaktif-ilmu-pengetahuan-alam-dan-sosial-untuk-sd-mi-kelas-iv-edisi-revisi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."},{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan penguapan dan pembentukan awan dengan contoh dan alasan.\n2. Menjelaskan hujan, aliran dan peresapan dengan contoh dan alasan.\n3. Menjelaskan pelestarian dan bukti tindakan dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Air bergerak melalui udara, permukaan dan tanah dalam siklus. Matahari memberi energi bagi penguapan dan gravitasi membantu air bergerak turun. Menjaga air berarti menjaga jumlah yang tersedia serta kualitas dan tempat peresapannya."},{"type":"image","url":"/assets/petualangan-siklus-air.svg","caption":"Model beberapa jalur air: penguapan, pengembunan, hujan, aliran dan peresapan."},{"type":"text","heading":"A. Penguapan dan pembentukan awan","body":"Air menguap dari laut, danau, sungai atau permukaan lain. Tumbuhan juga melepaskan uap melalui transpirasi. Uap dapat mendingin lalu mengembun menjadi tetes kecil atau membentuk kristal es di awan. Awan terlihat karena tetes/kristal, sedangkan uap air gas tidak terlihat. Tidak semua awan menghasilkan hujan di lokasi yang sama."},{"type":"text","heading":"Contoh bertahap 1","body":"Air jemuran menguap tanpa harus mendidih. Di atmosfer, perubahan kondisi dapat membuat uap menjadi tetes kecil; awan bukan kantong berlubang berisi air."},{"type":"text","heading":"B. Hujan, aliran dan peresapan","body":"Tetes atau kristal yang tumbuh cukup besar dapat jatuh sebagai presipitasi, misalnya hujan. Air dapat mengalir ke sungai/laut, meresap ke tanah, tersimpan atau menguap lagi. Permukaan kedap mengurangi peresapan dan dapat meningkatkan limpasan. Jalur air beragam, tidak semua tetes langsung kembali ke laut."},{"type":"text","heading":"Contoh bertahap 2","body":"Air hujan di taman berpori dapat meresap. Di halaman tertutup beton, lebih banyak air dapat mengalir menuju saluran, tergantung kondisi dan rancangan tempat."},{"type":"text","heading":"C. Pelestarian dan bukti tindakan","body":"Jaga daerah resapan, rawat tanaman sesuai lingkungan, hemat air bersih dan hindari membuang sampah/limbah. Siklus air tidak menjamin air yang tercemar langsung aman diminum. Banjir mempunyai banyak faktor; jangan menyalahkan satu orang atau satu kejadian tanpa data. Tindakan disesuaikan kondisi setempat dengan pendamping."},{"type":"text","heading":"Contoh bertahap 3","body":"Menutup keran setelah dipakai mengurangi pemborosan. Memilah sampah menjaga saluran, tetapi tidak sendirian menyelesaikan seluruh risiko banjir atau pencemaran."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat diagram siklus dengan panah berlabel menguap, mengembun, hujan, mengalir dan meresap. Tambahkan dua titik tindakan pelestarian. Amati peresapan hanya pada tanah/wadah aman bersama pendamping, bukan mendekati saluran banjir."},{"type":"text","heading":"Latihan mandiri","body":"1. Sumber energi utama penguapan pada siklus air?\n2. Apa yang terjadi saat infiltrasi?\n3. Air siklus alam selalu aman diminum langsung?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Matahari. Energi matahari mendukung perubahan air cair menjadi uap.\n2. Air meresap ke tanah. Berbeda dari aliran di permukaan.\n3. Tidak. Kualitas dan pengolahan tetap perlu diperhatikan.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Siklus melibatkan penguapan, pengembunan, presipitasi, aliran dan peresapan. Pelestarian menjaga tempat resapan serta kualitas air."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jangan menggambar siklus hanya satu jalur wajib. Pengayaan: dua daerah dengan permukaan berbeda dan dampaknya pada limpasan/peresapan.\nNilai pertanyaan pengamatan, catatan bukti, penjelasan hubungan, batas kesimpulan dan keselamatan. Bedakan yang diamati dari yang dipelajari dari sumber. Jangan meminta percobaan berisiko atau menilai tubuh/kemampuan pribadi teman.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('affb84ae-1218-56a7-b6ac-57fc2ff7b867','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Cahaya dan Sifatnya & Bunyi','petualangan-ipas-kelas-5-bab-1',5,'C','Petualangan · Bab 1','sedang','draft',25,'{"summary":"Pulau Eksplora bersama Ilmuwan Tobi: Cahaya dan Sifatnya & Bunyi. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-ipas-5","mentor":"Ilmuwan Tobi","chapter_number":1,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan cahaya, bayangan dan bahan dengan contoh dan alasan.","Menjelaskan pemantulan dan pembiasan dengan contoh dan alasan.","Menjelaskan bunyi dari getaran dan medium dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Paket ini berfokus sains; unsur sosial IPAS tetap perlu paket lain. Topik dan penempatan kelas adalah pilihan aplikasi yang menunggu pemetaan TP/ATP dan review guru.","source_refs":[{"title":"IPAS Kelas V (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/ilmu-pengetahuan-alam-dan-sosial-untuk-sd-mi-kelas-v-edisi-revisi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."},{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan cahaya, bayangan dan bahan dengan contoh dan alasan.\n2. Menjelaskan pemantulan dan pembiasan dengan contoh dan alasan.\n3. Menjelaskan bunyi dari getaran dan medium dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Cahaya membantu kita melihat, bunyi membantu mendengar. Keduanya membawa energi tetapi mempunyai sifat rambatan berbeda. Gunakan cermin dan benda ringan dengan pendamping; jangan mengarahkan cahaya kuat/laser ke mata atau membuat bunyi keras."},{"type":"text","heading":"A. Cahaya, bayangan dan bahan","body":"Cahaya merambat lurus pada medium homogen dan dapat dihalangi benda sehingga membentuk bayangan. Bahan transparan meneruskan banyak cahaya, tembus cahaya meneruskan sebagian dengan hamburan, dan opak menghalangi sebagian besar. Benda terlihat ketika cahaya dari sumber atau pantulan masuk mata. Bukan mata yang memancarkan sinar untuk melihat."},{"type":"text","heading":"Contoh bertahap 1","body":"Kaca bening memungkinkan melihat objek di baliknya; kertas karton memberi bayangan. Ketajaman bayangan bergantung juga ukuran sumber dan jarak, bukan hanya nama bahan."},{"type":"text","heading":"B. Pemantulan dan pembiasan","body":"Cahaya dapat dipantulkan oleh permukaan; cermin memberi pantulan teratur. Saat berpindah antara medium berbeda, arah dapat berubah karena pembiasan. Gunakan contoh pengamatan tanpa menyentuh kaca pecah. Pantulan cermin bukan benda kedua yang hidup; model garis membantu menjelaskan arah cahaya."},{"type":"text","heading":"Contoh bertahap 2","body":"Pensil dalam gelas air tampak bengkok karena pembiasan pada batas air/udara. Pensil sebenarnya tidak harus patah. Permukaan air juga dapat memantulkan cahaya."},{"type":"text","heading":"C. Bunyi dari getaran dan medium","body":"Bunyi dihasilkan sumber bergetar dan memerlukan medium seperti udara, air atau padat. Bunyi tidak merambat dalam ruang hampa seperti cahaya dapat merambat. Tinggi nada berkaitan frekuensi; keras-lembut berkaitan amplitudo/intensitas dan jarak. Lindungi pendengaran; jangan mencoba mendengar dengan menempelkan telinga ke benda berbahaya."},{"type":"text","heading":"Contoh bertahap 3","body":"Penggaris plastik yang digetarkan pelan di tepi meja dapat berbunyi. Bagian bebas yang panjang dan pendek dapat menghasilkan nada berbeda, dengan pengawasan agar tidak terpental."},{"type":"text","heading":"Kegiatan penerapan","body":"Amati bayangan kartu dengan cahaya ruangan dan pantulan cermin yang dipegang pendamping. Lalu ketuk wadah ringan sangat pelan dan catat getarannya. Bedakan sumber, medium dan penerima dalam sketsa."},{"type":"text","heading":"Latihan mandiri","body":"1. Mengapa kita dapat melihat buku?\n2. Pensil tampak bengkok dalam air karena?\n3. Apakah bunyi merambat di ruang hampa?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Cahaya pantulan buku masuk mata. Mata menerima cahaya.\n2. Pembiasan. Arah cahaya berubah pada batas medium.\n3. Tidak. Bunyi memerlukan medium.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Cahaya dapat dipantulkan dan dibiaskan serta membentuk bayangan. Bunyi berasal dari getaran dan memerlukan medium; jaga mata/telinga."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Bedakan nada tinggi dari bunyi keras. Pengayaan: tunjukkan bahwa cahaya dan bunyi mempunyai kebutuhan medium yang berbeda.\nNilai pertanyaan pengamatan, catatan bukti, penjelasan hubungan, batas kesimpulan dan keselamatan. Bedakan yang diamati dari yang dipelajari dari sumber. Jangan meminta percobaan berisiko atau menilai tubuh/kemampuan pribadi teman.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('bb5478a1-0e67-58a5-a005-2aac3e0af914','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Rantai Makanan & Jaring Ekosistem','petualangan-ipas-kelas-5-bab-2',5,'C','Petualangan · Bab 2','sedang','draft',25,'{"summary":"Pulau Eksplora bersama Ilmuwan Tobi: Rantai Makanan & Jaring Ekosistem. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-ipas-5","mentor":"Ilmuwan Tobi","chapter_number":2,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan produsen, konsumen dan pengurai dengan contoh dan alasan.","Menjelaskan arah panah dan jaring makanan dengan contoh dan alasan.","Menjelaskan keseimbangan, gangguan dan bukti dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Paket ini berfokus sains; unsur sosial IPAS tetap perlu paket lain. Topik dan penempatan kelas adalah pilihan aplikasi yang menunggu pemetaan TP/ATP dan review guru.","source_refs":[{"title":"IPAS Kelas V (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/ilmu-pengetahuan-alam-dan-sosial-untuk-sd-mi-kelas-v-edisi-revisi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."},{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan produsen, konsumen dan pengurai dengan contoh dan alasan.\n2. Menjelaskan arah panah dan jaring makanan dengan contoh dan alasan.\n3. Menjelaskan keseimbangan, gangguan dan bukti dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Ekosistem mencakup makhluk hidup dan komponen tak hidup yang berinteraksi. Rantai makanan menunjukkan satu jalur aliran energi; jaring makanan menunjukkan banyak hubungan. Diagram adalah model yang perlu sesuai organisme dan lingkungannya."},{"type":"text","heading":"A. Produsen, konsumen dan pengurai","body":"Produsen seperti tumbuhan hijau membuat bahan organik menggunakan energi. Konsumen memperoleh makanan dari organisme lain. Pengurai seperti banyak bakteri/jamur menguraikan sisa dan mengembalikan unsur ke lingkungan. Peran bergantung cara memperoleh bahan dan energi; satu organisme dapat memiliki hubungan makan beragam."},{"type":"text","heading":"Contoh bertahap 1","body":"Padi sebagai produsen dapat dimakan belalang, belalang dimakan katak. Jamur/bakteri menguraikan sisa; mereka tidak muncul hanya pada akhir hidup satu rantai yang lurus."},{"type":"text","heading":"B. Arah panah dan jaring makanan","body":"Panah pada model ini menunjuk dari sumber makanan ke pemakan, menyatakan perpindahan bahan/energi. Satu hewan dapat memakan beberapa jenis dan dimakan lebih dari satu pemangsa, sehingga rantai saling terhubung. Jelaskan aturan panah agar tidak terbalik. Jangan memasukkan pasangan makan yang tidak cocok hanya agar diagram panjang."},{"type":"text","heading":"Contoh bertahap 2","body":"Rumput → belalang → burung berarti belalang memakan rumput dan burung memakan belalang. Tambahan ulat dan pemangsa lain dapat membentuk jaring bila hubungan didukung sumber."},{"type":"text","heading":"C. Keseimbangan, gangguan dan bukti","body":"Perubahan satu populasi dapat memengaruhi yang lain, tetapi arah dan besarnya bergantung banyak hubungan. Hilangnya produsen mengurangi sumber energi dasar. Materi berputar melalui lingkungan dan organisme, sedangkan energi mengalir lalu menyebar sebagai panas; energi tidak berputar sama seperti materi. Gunakan kata dapat bila akibat belum pasti."},{"type":"text","heading":"Contoh bertahap 3","body":"Jika pemangsa berkurang, mangsa dapat bertambah, tetapi makanan, penyakit dan habitat juga berpengaruh. Jangan menyatakan semua perubahan populasi mempunyai satu sebab saja."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat kartu organisme sawah dari sumber pendamping dan susun jaring makanan berpanah berlabel. Lepas satu kartu sebagai simulasi, lalu tulis dua kemungkinan dampak dan data apa yang perlu dicari, tanpa menangkap hewan."},{"type":"text","heading":"Latihan mandiri","body":"1. Arah panah pada padi → tikus berarti?\n2. Apa peran pengurai?\n3. Apakah energi berputar persis seperti materi?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Bahan/energi berpindah dari padi ke tikus yang memakannya. Panah bukan arah tikus berjalan.\n2. Menguraikan sisa dan membantu mengembalikan unsur. Pengurai bagian dari ekosistem.\n3. Tidak. Energi mengalir dan menyebar sebagai panas.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Produsen, konsumen dan pengurai saling terkait. Rantai adalah satu jalur, jaring banyak jalur. Perubahan perlu dinilai dengan konteks dan bukti."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Sebut aturan panah sebelum menggambar. Pengayaan: organisme dengan beberapa sumber makanan dan dampak yang tidak dapat dipastikan dari satu rantai.\nNilai pertanyaan pengamatan, catatan bukti, penjelasan hubungan, batas kesimpulan dan keselamatan. Bedakan yang diamati dari yang dipelajari dari sumber. Jangan meminta percobaan berisiko atau menilai tubuh/kemampuan pribadi teman.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('6b8612f7-2d56-5fea-bd6f-86c9274ebf82','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Organ Pernapasan & Pencernaan Manusia','petualangan-ipas-kelas-5-bab-3',5,'C','Petualangan · Bab 3','sedang','draft',25,'{"summary":"Pulau Eksplora bersama Ilmuwan Tobi: Organ Pernapasan & Pencernaan Manusia. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-ipas-5","mentor":"Ilmuwan Tobi","chapter_number":3,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan jalur udara dan pertukaran gas dengan contoh dan alasan.","Menjelaskan jalur makanan dan pengolahan dengan contoh dan alasan.","Menjelaskan keterkaitan dan kebiasaan merawat dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Paket ini berfokus sains; unsur sosial IPAS tetap perlu paket lain. Topik dan penempatan kelas adalah pilihan aplikasi yang menunggu pemetaan TP/ATP dan review guru.","source_refs":[{"title":"IPAS Kelas V (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/ilmu-pengetahuan-alam-dan-sosial-untuk-sd-mi-kelas-v-edisi-revisi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."},{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan jalur udara dan pertukaran gas dengan contoh dan alasan.\n2. Menjelaskan jalur makanan dan pengolahan dengan contoh dan alasan.\n3. Menjelaskan keterkaitan dan kebiasaan merawat dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Pernapasan dan pencernaan membantu tubuh memperoleh bahan yang diperlukan. Kita menggunakan model, bukan melakukan diagnosis. Perbedaan kondisi tubuh perlu dihargai dan keluhan kesehatan disampaikan kepada pendamping/tenaga kesehatan."},{"type":"text","heading":"A. Jalur udara dan pertukaran gas","body":"Udara masuk melalui hidung atau mulut lalu melewati saluran menuju paru-paru. Pada bagian kecil paru-paru yang disebut alveolus, oksigen berpindah ke darah dan karbon dioksida berpindah untuk dikeluarkan. Diafragma dan otot pernapasan membantu perubahan volume rongga dada. Paru-paru bukan kantong yang menghasilkan oksigen sendiri."},{"type":"text","heading":"Contoh bertahap 1","body":"Saat menarik napas, rongga dada membesar sehingga udara masuk; saat mengembuskan, udara keluar. Oksigen kemudian dibawa darah menuju jaringan, tidak berubah menjadi makanan di paru-paru."},{"type":"text","heading":"B. Jalur makanan dan pengolahan","body":"Makanan dikunyah di mulut dan bercampur air liur, melewati kerongkongan ke lambung, lalu usus halus. Pencernaan mekanis dan kimia memecah makanan sehingga bahan dapat diserap. Usus halus menyerap sebagian besar zat gizi, usus besar terutama menangani sisa serta penyerapan air tertentu. Urutan harus dibedakan dari jalur udara."},{"type":"text","heading":"Contoh bertahap 2","body":"Nasi tidak masuk ke paru-paru dalam jalur makan normal. Mengunyah membantu memperkecil makanan; enzim membantu pemecahan kimia pada tahap yang sesuai."},{"type":"text","heading":"C. Keterkaitan dan kebiasaan merawat","body":"Zat gizi dari pencernaan dan oksigen dari pernapasan didistribusikan untuk proses tubuh menggunakan energi. Hindari asap dan makan dengan tenang sesuai kemampuan. Kebiasaan sehat mendukung sistem, tetapi tidak menjamin seseorang tak pernah sakit. Jangan menahan napas lama, berlomba napas atau mencoba mengukur penyakit melalui aktivitas kelas."},{"type":"text","heading":"Contoh bertahap 3","body":"Tokoh memilih tempat bebas asap dan memberi tahu pendamping ketika merasa tidak nyaman. Pelajaran struktur organ tidak cukup untuk menyatakan penyebab batuk atau nyeri seseorang."},{"type":"text","heading":"Kegiatan penerapan","body":"Gambar dua jalur berbeda dengan warna: udara menuju paru-paru dan makanan menuju lambung/usus. Tandai tempat pertukaran gas serta penyerapan zat gizi. Gunakan kartu organ dan jelaskan hubungan kedua sistem tanpa percobaan pada tubuh teman."},{"type":"text","heading":"Latihan mandiri","body":"1. Tempat pertukaran gas utama di paru-paru?\n2. Sebagian besar zat gizi diserap di mana?\n3. Apakah belajar organ cukup untuk mendiagnosis sakit teman?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Alveolus. Dinding tipis dan pembuluh memungkinkan pertukaran gas.\n2. Usus halus. Pencernaan dan penyerapan memiliki tahapan berbeda.\n3. Tidak. Diagnosis memerlukan tenaga kesehatan dan pemeriksaan.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Paru-paru menukar gas; pencernaan mengolah makanan dan usus halus menyerap zat gizi. Kedua sistem didukung darah dan kebiasaan sehat."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jangan mencampurkan kerongkongan dengan tenggorokan/saluran napas. Pengayaan: diagram hubungan pencernaan-pernapasan-peredaran tanpa menyederhanakan sebagai organ saling bertukar makanan.\nNilai pertanyaan pengamatan, catatan bukti, penjelasan hubungan, batas kesimpulan dan keselamatan. Bedakan yang diamati dari yang dipelajari dari sumber. Jangan meminta percobaan berisiko atau menilai tubuh/kemampuan pribadi teman.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('1e5f1b47-05a6-5d4c-bc17-92906f19e589','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Listrik, Magnet, & Teknologi Sehari-hari','petualangan-ipas-kelas-5-bab-4',5,'C','Petualangan · Bab 4','sedang','draft',25,'{"summary":"Pulau Eksplora bersama Ilmuwan Tobi: Listrik, Magnet, & Teknologi Sehari-hari. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-ipas-5","mentor":"Ilmuwan Tobi","chapter_number":4,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan rangkaian listrik sederhana dengan contoh dan alasan.","Menjelaskan magnet dan elektromagnet dengan contoh dan alasan.","Menjelaskan teknologi, manfaat dan risiko dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Paket ini berfokus sains; unsur sosial IPAS tetap perlu paket lain. Topik dan penempatan kelas adalah pilihan aplikasi yang menunggu pemetaan TP/ATP dan review guru.","source_refs":[{"title":"IPAS Kelas V (Edisi Revisi)","url":"https://buku.kemendikdasmen.go.id/katalog/ilmu-pengetahuan-alam-dan-sosial-untuk-sd-mi-kelas-v-edisi-revisi","audience":"student","usage":"Bacaan pendamping; naskah dan asesmen aplikasi ditulis orisinal, bukan salinan buku."},{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan rangkaian listrik sederhana dengan contoh dan alasan.\n2. Menjelaskan magnet dan elektromagnet dengan contoh dan alasan.\n3. Menjelaskan teknologi, manfaat dan risiko dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Listrik dan magnet dipakai pada banyak teknologi. Memahami prinsipnya membantu menggunakan alat dengan aman. Jangan membuka alat, memasukkan benda ke stopkontak, membuat hubungan singkat atau memakai baterai rusak."},{"type":"text","heading":"A. Rangkaian listrik sederhana","body":"Arus listrik memerlukan jalur tertutup dan sumber energi pada model rangkaian sederhana. Sakelar membuka atau menutup jalur. Konduktor mudah menghantarkan dibanding isolator pada kondisi yang dibahas. Isolator pada kabel harus utuh; karet/kulit basah atau alat rusak tidak menjamin keselamatan. Listrik rumah bukan bahan percobaan anak."},{"type":"text","heading":"Contoh bertahap 1","body":"Diagram baterai-lampu-sakelar menunjukkan lampu menyala ketika jalur lengkap. Kabel yang putus membuat rangkaian terbuka; jangan mencoba membuktikan dengan memegang ujung kabel listrik rumah."},{"type":"text","heading":"B. Magnet dan elektromagnet","body":"Magnet mempunyai kutub dan menarik bahan tertentu. Arus listrik pada kumparan dapat membentuk medan magnet; inti yang sesuai dapat memperkuat efeknya. Ini prinsip elektromagnet pada alat tertentu. Tidak semua benda logam tertarik dan tidak semua alat magnet bekerja dengan listrik. Gunakan diagram atau demonstrasi aman oleh pendamping."},{"type":"text","heading":"Contoh bertahap 2","body":"Bel listrik dan motor tertentu memakai hubungan listrik-magnet. Magnet permanen pada penutup tas tidak membutuhkan arus terus-menerus untuk mempertahankan sifat magnetnya."},{"type":"text","heading":"C. Teknologi, manfaat dan risiko","body":"Alat mengubah energi untuk memenuhi kebutuhan, tetapi membutuhkan perawatan dan pemakaian benar. Perhatikan petunjuk, kondisi kabel dan izin pendamping. Jangan memasang banyak beban sembarangan atau menyentuh alat saat tangan basah. Baterai kecil, magnet kecil dan limbah elektronik tidak boleh masuk mulut atau dibuang sembarangan."},{"type":"text","heading":"Contoh bertahap 3","body":"Ketika kabel pengisi terlihat rusak, tokoh tidak memperbaikinya sendiri. Ia berhenti memakai dan memberi tahu pendamping. Menghemat listrik tidak boleh mengorbankan keselamatan."},{"type":"text","heading":"Kegiatan penerapan","body":"Susun kartu diagram sumber-kabel-sakelar-lampu menjadi rangkaian tertutup, lalu buka satu sambungan pada gambar. Jelaskan perubahan. Buat poster tiga kebiasaan aman tanpa menyalakan atau membongkar alat listrik sungguhan."},{"type":"text","heading":"Latihan mandiri","body":"1. Apa arti rangkaian tertutup?\n2. Apakah semua magnet memerlukan listrik terus-menerus?\n3. Apa saat menemukan kabel rusak?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Jalur arus lengkap. Pada model, arus dapat mengalir melalui beban.\n2. Tidak. Magnet permanen berbeda dari elektromagnet.\n3. Hentikan penggunaan dan beri tahu pendamping. Jangan membuka atau memperbaiki sendiri.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Rangkaian tertutup memungkinkan arus, elektromagnet menghubungkan arus dan medan magnet, dan teknologi harus dipakai sesuai petunjuk aman."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jangan memberi tugas merangkai listrik rumah. Pengayaan: bandingkan diagram magnet permanen dan elektromagnet tanpa memakai arus besar.\nNilai pertanyaan pengamatan, catatan bukti, penjelasan hubungan, batas kesimpulan dan keselamatan. Bedakan yang diamati dari yang dipelajari dari sumber. Jangan meminta percobaan berisiko atau menilai tubuh/kemampuan pribadi teman.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('3e50740b-fac0-5e2c-a0f6-87255602cbc1','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Sistem Rangka, Sendi, & Saraf Manusia','petualangan-ipas-kelas-6-bab-1',6,'C','Petualangan · Bab 1','sedang','draft',25,'{"summary":"Pulau Eksplora bersama Ilmuwan Tobi: Sistem Rangka, Sendi, & Saraf Manusia. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-ipas-6","mentor":"Ilmuwan Tobi","chapter_number":1,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan rangka, perlindungan dan kerja otot dengan contoh dan alasan.","Menjelaskan sendi dan kemungkinan gerak dengan contoh dan alasan.","Menjelaskan saraf, otak dan respons dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Paket ini berfokus sains; unsur sosial IPAS tetap perlu paket lain. Topik dan penempatan kelas adalah pilihan aplikasi yang menunggu pemetaan TP/ATP dan review guru.","source_refs":[{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan rangka, perlindungan dan kerja otot dengan contoh dan alasan.\n2. Menjelaskan sendi dan kemungkinan gerak dengan contoh dan alasan.\n3. Menjelaskan saraf, otak dan respons dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Gerak dan koordinasi tubuh melibatkan rangka, otot, sendi dan sistem saraf. Gunakan model serta gerak ringan sesuai kemampuan. Tidak perlu memaksa posisi sendi, menguji refleks dengan pukulan atau membandingkan kemampuan tubuh teman."},{"type":"text","heading":"A. Rangka, perlindungan dan kerja otot","body":"Rangka membantu menopang bentuk, melindungi organ dan menjadi tempat kerja otot. Tulang mempunyai jaringan hidup, bukan batang mati. Otot menarik tulang melalui hubungan yang sesuai; otot tidak mendorong tulang seperti tongkat. Pasangan/kelompok otot bekerja terkoordinasi untuk arah gerak berbeda."},{"type":"text","heading":"Contoh bertahap 1","body":"Tengkorak melindungi otak dan rangka dada membantu melindungi organ dada. Ketika siku ditekuk, kelompok otot tertentu memendek sementara kelompok lain menyesuaikan; gerak bukan kerja tulang sendirian."},{"type":"text","heading":"B. Sendi dan kemungkinan gerak","body":"Sendi adalah hubungan antar tulang dengan bentuk dan rentang gerak berbeda. Sendi engsel seperti siku terutama memungkinkan gerak menekuk-meluruskan, sedangkan sendi peluru seperti bahu memungkinkan arah lebih beragam. Beberapa hubungan tulang hampir tidak bergerak. Model sederhana tidak mencakup seluruh detail anatomi."},{"type":"text","heading":"Contoh bertahap 2","body":"Pintu memberi analogi engsel, tetapi sendi manusia bukan engsel logam. Jangan memutar siku seperti bahu; bentuk dan jaringan pembatasnya berbeda."},{"type":"text","heading":"C. Saraf, otak dan respons","body":"Sistem saraf menerima informasi, mengolah dan mengirim sinyal. Otak, sumsum tulang belakang dan saraf tepi saling berkaitan. Respons tertentu cepat melalui jalur refleks, tetapi keseluruhan koordinasi tetap kompleks. Kelainan gerak atau rasa tidak dapat didiagnosis dari permainan kelas; laporkan keluhan kepada pendamping/tenaga kesehatan."},{"type":"text","heading":"Contoh bertahap 3","body":"Ketika melihat bola mendekat, informasi penglihatan membantu tubuh menyiapkan gerak. Respons tiap orang dipengaruhi banyak keadaan; satu uji reaksi tidak menilai kecerdasan atau kesehatan seseorang."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat model dua batang karton berengsel aman dan bandingkan dengan gambar sendi bahu. Gambar panah informasi dari indra ke sistem saraf lalu respons otot. Gerak hanya sukarela, ringan dan boleh diganti pengamatan model."},{"type":"text","heading":"Latihan mandiri","body":"1. Sebut dua fungsi rangka.\n2. Mengapa siku tidak diputar paksa seperti bahu?\n3. Apakah satu permainan respons dapat mendiagnosis saraf?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Menopang dan melindungi organ. Rangka juga berperan dalam gerak bersama otot.\n2. Jenis dan rentang sendinya berbeda. Memaksa dapat mencederai jaringan.\n3. Tidak. Pemeriksaan kesehatan memerlukan prosedur profesional.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Rangka menopang/melindungi, sendi memungkinkan gerak tertentu, otot menghasilkan tarikan dan saraf mengoordinasi informasi serta respons."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Hindari tugas menguji refleks pada tubuh teman. Pengayaan: jelaskan keterbatasan analogi engsel dibanding sendi hidup.\nNilai pertanyaan pengamatan, catatan bukti, penjelasan hubungan, batas kesimpulan dan keselamatan. Bedakan yang diamati dari yang dipelajari dari sumber. Jangan meminta percobaan berisiko atau menilai tubuh/kemampuan pribadi teman.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('8688a521-749d-512b-b244-03a5e07d673f','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Sistem Tata Surya, Rotasi, & Revolusi Bumi','petualangan-ipas-kelas-6-bab-2',6,'C','Petualangan · Bab 2','sedang','draft',25,'{"summary":"Pulau Eksplora bersama Ilmuwan Tobi: Sistem Tata Surya, Rotasi, & Revolusi Bumi. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-ipas-6","mentor":"Ilmuwan Tobi","chapter_number":2,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan matahari, planet dan satelit dengan contoh dan alasan.","Menjelaskan rotasi dan akibatnya dengan contoh dan alasan.","Menjelaskan revolusi dan kemiringan sumbu dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Paket ini berfokus sains; unsur sosial IPAS tetap perlu paket lain. Topik dan penempatan kelas adalah pilihan aplikasi yang menunggu pemetaan TP/ATP dan review guru.","source_refs":[{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan matahari, planet dan satelit dengan contoh dan alasan.\n2. Menjelaskan rotasi dan akibatnya dengan contoh dan alasan.\n3. Menjelaskan revolusi dan kemiringan sumbu dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Tata surya mencakup matahari dan benda yang terikat gravitasinya. Model membantu memahami hubungan gerak, tetapi jarak dan ukuran pada gambar sering tidak berskala. Jangan mengamati matahari langsung atau melalui alat tanpa prosedur khusus yang sah."},{"type":"text","heading":"A. Matahari, planet dan satelit","body":"Matahari adalah bintang pusat tata surya. Delapan planet menurut urutan dari matahari ialah Merkurius, Venus, Bumi, Mars, Jupiter, Saturnus, Uranus dan Neptunus. Planet tidak memancarkan cahaya tampak sendiri seperti bintang; kita melihat pantulan. Bulan adalah satelit alami bumi; Pluto diklasifikasikan planet katai, bukan salah satu delapan planet utama."},{"type":"text","heading":"Contoh bertahap 1","body":"Bumi mengorbit matahari, bulan mengorbit bumi, dan keduanya ikut bergerak dalam tata surya. Gambar yang menaruh semua planet berdekatan bukan gambaran jarak nyata."},{"type":"text","heading":"B. Rotasi dan akibatnya","body":"Rotasi adalah putaran benda pada poros. Bumi berotasi sekitar sekali sehari, sehingga bagian permukaan bergantian menghadap matahari. Ini menjelaskan siang-malam dan gerak tampak harian matahari. Perbedaan waktu antarwilayah berkaitan rotasi serta kesepakatan zona waktu. Matahari tidak benar-benar mengelilingi bumi sekali tiap hari."},{"type":"text","heading":"Contoh bertahap 2","body":"Pada model bola berputar di depan lampu, satu titik berpindah dari terang ke gelap. Lampu tetap menjadi model matahari, bukan berkeliling mengitari bola untuk menjelaskan rotasi."},{"type":"text","heading":"C. Revolusi dan kemiringan sumbu","body":"Revolusi adalah gerak mengelilingi benda lain; bumi mengelilingi matahari sekitar satu tahun. Kemiringan sumbu bumi bersama revolusi berkaitan dengan perubahan musim dan lama siang di berbagai lintang. Musim bukan terutama akibat bumi bergantian sangat dekat dan jauh dari matahari. Indonesia mempunyai pola musim yang juga dipengaruhi sirkulasi angin/laut dan letak geografis."},{"type":"text","heading":"Contoh bertahap 3","body":"Dua belahan bumi dapat mengalami musim berbeda pada waktu sama. Model musim perlu mempertahankan arah sumbu saat bumi bergerak, dan menjelaskan bahwa skalanya disederhanakan."},{"type":"text","heading":"Kegiatan penerapan","body":"Gunakan kartu delapan planet untuk urutan. Pendamping memakai bola dan lampu aman untuk model rotasi/revolusi. Labeli gerak, waktu kira-kira dan batas model; jangan menatap lampu kuat atau matahari."},{"type":"text","heading":"Latihan mandiri","body":"1. Planet ketiga dari matahari?\n2. Gerak utama penyebab siang-malam?\n3. Apakah musim terutama karena jarak bumi berubah?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Bumi. Urutannya Merkurius, Venus, Bumi.\n2. Rotasi bumi. Titik permukaan berganti menghadap matahari.\n3. Tidak. Kemiringan sumbu dan revolusi berperan utama pada musim lintang menengah.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Matahari bintang, bumi planet, bulan satelit. Rotasi sekitar sehari; revolusi sekitar setahun. Model perlu menjelaskan skala dan kemiringan sumbu."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Bedakan rotasi dengan revolusi memakai dua gerak terpisah. Pengayaan: mengapa belahan utara dan selatan dapat mengalami musim berlawanan.\nNilai pertanyaan pengamatan, catatan bukti, penjelasan hubungan, batas kesimpulan dan keselamatan. Bedakan yang diamati dari yang dipelajari dari sumber. Jangan meminta percobaan berisiko atau menilai tubuh/kemampuan pribadi teman.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('b6c801f1-5625-59f8-b6e1-8082b2976f9b','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Adaptasi Makhluk Hidup: Bunglon, Kaktus, Teratai','petualangan-ipas-kelas-6-bab-3',6,'C','Petualangan · Bab 3','sedang','draft',25,'{"summary":"Pulau Eksplora bersama Ilmuwan Tobi: Adaptasi Makhluk Hidup: Bunglon, Kaktus, Teratai. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-ipas-6","mentor":"Ilmuwan Tobi","chapter_number":3,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan bentuk, fungsi dan perilaku dengan contoh dan alasan.","Menjelaskan kaktus dan teratai dengan contoh dan alasan.","Menjelaskan bunglon dan penilaian penjelasan dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Paket ini berfokus sains; unsur sosial IPAS tetap perlu paket lain. Topik dan penempatan kelas adalah pilihan aplikasi yang menunggu pemetaan TP/ATP dan review guru.","source_refs":[{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan bentuk, fungsi dan perilaku dengan contoh dan alasan.\n2. Menjelaskan kaktus dan teratai dengan contoh dan alasan.\n3. Menjelaskan bunglon dan penilaian penjelasan dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Adaptasi adalah ciri yang mendukung kehidupan dan perkembangbiakan organisme pada lingkungan tertentu. Ciri berkembang pada populasi sepanjang generasi; individu tidak dapat menghendaki semua ciri baru muncul seketika. Bedakan adaptasi dengan respons atau penyesuaian sementara."},{"type":"text","heading":"A. Bentuk, fungsi dan perilaku","body":"Adaptasi dapat berkaitan bentuk tubuh, proses fisiologi atau perilaku yang mendukung kehidupan. Manfaatnya bergantung lingkungan dan memiliki biaya/kompromi. Jangan menulis hewan ingin sehingga langsung berubah organ. Penjelasan ilmiah menghubungkan ciri, fungsi dan kondisi, bukan sekadar tujuan yang dibayangkan manusia."},{"type":"text","heading":"Contoh bertahap 1","body":"Bentuk paruh dapat berkaitan jenis makanan. Tidak semua paruh panjang mempunyai fungsi persis sama; bandingkan spesies dan lingkungan dari sumber yang tepat."},{"type":"text","heading":"B. Kaktus dan teratai","body":"Banyak kaktus mempunyai batang penyimpan air dan daun yang termodifikasi menjadi duri, membantu hidup pada kondisi kering bersama ciri lain. Duri juga dapat memberi perlindungan. Teratai mempunyai daun yang sesuai hidup di permukaan air dan jaringan yang mendukung pertukaran/ruang udara. Ciri tidak boleh dipindahkan sebagai resep merawat semua tanaman."},{"type":"text","heading":"Contoh bertahap 2","body":"Kaktus tidak berarti tidak butuh air sama sekali. Teratai juga tidak dapat disamakan dengan tumbuhan darat hanya karena sama-sama berdaun; habitat menentukan kebutuhan."},{"type":"text","heading":"C. Bunglon dan penilaian penjelasan","body":"Bunglon dapat mengubah warna melalui mekanisme tubuh. Perubahan warna dapat berkaitan komunikasi, suhu dan kondisi lain, bukan hanya menyamarkan diri dari pemangsa. Kamuflase adalah penyerupaan lingkungan yang mengurangi keterlihatan pada pengamat tertentu. Periksa apakah contoh benar untuk jenis yang dibahas dan hindari generalisasi semua hewan."},{"type":"text","heading":"Contoh bertahap 3","body":"Kalimat Bunglon selalu berubah tepat seperti semua latar terlalu luas. Penjelasan lebih baik menyebut kemampuan perubahan warna dan beberapa fungsinya, dengan variasi antarjenis."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat kartu ciri-lingkungan-manfaat untuk kaktus, teratai dan bunglon dari bacaan pendamping. Tambahkan satu batas penjelasan pada tiap kartu, misalnya kaktus tetap memerlukan air. Tidak perlu menangkap hewan atau menguji kekeringan ekstrem."},{"type":"text","heading":"Latihan mandiri","body":"1. Apakah kaktus tidak butuh air?\n2. Perubahan warna bunglon hanya untuk kamuflase?\n3. Apa tiga unsur penjelasan adaptasi?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Tetap butuh air. Penyimpanan/penghematan membantu bertahan, bukan menghapus kebutuhan.\n2. Tidak. Komunikasi dan pengaturan keadaan/suhu juga berperan.\n3. Ciri, kondisi lingkungan, dan fungsi/manfaat. Hubungan itu perlu sumber, bukan kehendak seketika.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Hubungkan ciri dengan lingkungan dan manfaat, tetapi sebut batasnya. Adaptasi bukan perubahan organ seketika karena ingin, dan satu ciri dapat punya beberapa fungsi."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Hindari kalimat tujuan yang seolah organisme memilih mengubah tubuh sesukanya. Pengayaan: bedakan adaptasi populasi dengan respons individu terhadap keadaan.\nNilai pertanyaan pengamatan, catatan bukti, penjelasan hubungan, batas kesimpulan dan keselamatan. Bedakan yang diamati dari yang dipelajari dari sumber. Jangan meminta percobaan berisiko atau menilai tubuh/kemampuan pribadi teman.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('6c64c02c-c10d-5645-af1f-0b8b2ef00cb0','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Krisis Energi & Energi Terbarukan','petualangan-ipas-kelas-6-bab-4',6,'C','Petualangan · Bab 4','sedang','draft',25,'{"summary":"Pulau Eksplora bersama Ilmuwan Tobi: Krisis Energi & Energi Terbarukan. Tiga subbab, contoh bertahap, kegiatan, latihan mandiri dan kuis.","video_url":null,"package_id":"petualangan-72-2026","course_id":"petualangan-72-2026-ipas-6","mentor":"Ilmuwan Tobi","chapter_number":4,"content_kind":"full_chapter","review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal berdasarkan pilihan topik aplikasi. Draf menunggu review guru; bukan daftar bab resmi nasional.","objectives":["Menjelaskan sumber terbarukan dan tak terbarukan dengan contoh dan alasan.","Menjelaskan dampak, akses dan perbandingan adil dengan contoh dan alasan.","Menjelaskan penghematan dan rencana tindakan dengan contoh dan alasan."],"enrichment":false,"curriculum_note":"Paket ini berfokus sains; unsur sosial IPAS tetap perlu paket lain. Topik dan penempatan kelas adalah pilihan aplikasi yang menunggu pemetaan TP/ATP dan review guru.","source_refs":[{"title":"Panduan mata pelajaran IPAS Fase B dan C, 2025","url":"https://repositori.kemendikdasmen.go.id/33599/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan sumber terbarukan dan tak terbarukan dengan contoh dan alasan.\n2. Menjelaskan dampak, akses dan perbandingan adil dengan contoh dan alasan.\n3. Menjelaskan penghematan dan rencana tindakan dengan contoh dan alasan.\nMulai dengan mengingat contoh sehari-hari yang berkaitan. Bila belum mengenal kata atau langkah pada judul, minta pendamping menjelaskannya dahulu. Tujuan ini masih draf untuk ditinjau guru."},{"type":"text","heading":"Sebelum mulai","body":"Kebutuhan energi melibatkan sumber, teknologi, biaya dan dampak lingkungan. Krisis dapat terkait pasokan, akses atau penggunaan berlebihan. Solusi memerlukan penghematan serta pilihan teknologi yang sesuai kondisi, bukan satu alat ajaib untuk semua tempat."},{"type":"text","heading":"A. Sumber terbarukan dan tak terbarukan","body":"Bahan bakar fosil terbentuk sangat lama sehingga terbatas dalam skala waktu manusia. Energi surya, angin, aliran air dan panas bumi termasuk sumber yang dapat diperbarui/berlanjut pada kondisi yang sesuai. Terbarukan tidak berarti tanpa batas penggunaan atau tanpa dampak; lokasi, cuaca, infrastruktur dan pemeliharaan tetap penting."},{"type":"text","heading":"Contoh bertahap 1","body":"Panel surya memerlukan cahaya dan sistem pengelolaan listrik; keluaran berubah menurut kondisi. Turbin air bergantung aliran dan perlu mempertimbangkan ekosistem serta masyarakat."},{"type":"text","heading":"B. Dampak, akses dan perbandingan adil","body":"Pembakaran fosil menghasilkan gas rumah kaca dan dapat menimbulkan pencemar. Teknologi terbarukan juga membutuhkan material, lahan dan pengelolaan limbah. Bandingkan manfaat serta dampak sepanjang penggunaan dengan sumber yang jelas. Kebutuhan rumah tangga, sekolah dan layanan kesehatan tidak sama, sehingga akses yang adil perlu dipertimbangkan."},{"type":"text","heading":"Contoh bertahap 2","body":"Memilih lampu efisien dapat mengurangi kebutuhan listrik untuk layanan sama. Namun menyuruh mematikan perangkat kesehatan bukan penghematan yang layak karena membahayakan fungsi penting."},{"type":"text","heading":"C. Penghematan dan rencana tindakan","body":"Kurangi pemborosan, gunakan alat efisien dan rencanakan pemakaian sesuai kebutuhan. Ukur hasil jika memungkinkan: lama pemakaian, jumlah alat atau data meter yang dibaca orang dewasa. Jangan memasang panel, membongkar baterai atau membuat pembangkit sendiri tanpa keahlian. Tindakan kecil dibedakan dari klaim menyelesaikan seluruh persoalan energi."},{"type":"text","heading":"Contoh bertahap 3","body":"Rencana kelas: gunakan cahaya alami yang cukup, matikan proyektor saat tidak dipakai dengan izin, dan catat durasinya. Bandingkan sebelum-sesudah sambil mencatat perubahan kegiatan yang dapat memengaruhi hasil."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat audit energi berbasis gambar jadwal rekaan kelas. Pilih dua penghematan dan satu sumber terbarukan yang mungkin sesuai daerah, lalu tulis manfaat, batas dan siapa yang perlu menilai kelayakan. Tidak melakukan instalasi listrik."},{"type":"text","heading":"Latihan mandiri","body":"1. Mengapa fosil disebut tak terbarukan pada skala manusia?\n2. Terbarukan selalu tanpa dampak?\n3. Contoh ukuran hasil penghematan?\nCobalah dahulu tanpa membuka pembahasan. Untuk jawaban terbuka, tunjukkan alasan atau karya; lebih dari satu jawaban dapat diterima jika memenuhi pertanyaan dan didukung bukti."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Pembentukannya sangat lama dibanding pemakaian. Cadangan dapat berkurang lebih cepat daripada terbentuk.\n2. Tidak. Material, lokasi dan pengelolaan tetap memiliki dampak.\n3. Durasi alat yang tak perlu dinyalakan. Pengukuran membantu menilai klaim, dengan kondisi perbandingan dicatat.","collapsible":true},{"type":"text","heading":"Rangkuman bab","body":"Bedakan sumber dan skala pembaruannya. Pilih efisiensi dan energi sesuai kondisi dengan mempertimbangkan lingkungan, akses serta keselamatan."},{"type":"text","heading":"Refleksi belajar","body":"Jelaskan satu gagasan dengan kata sendiri, tunjukkan satu contoh baru, dan sebutkan bagian yang masih perlu bantuan. Periksa kembali contoh jika jawaban belum tepat. Kesalahan memberi petunjuk langkah yang perlu dilatih; kamu boleh mengulang sebelum kuis."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jangan mengajarkan semua sumber terbarukan selalu tersedia tanpa penyimpanan. Pengayaan: bandingkan dua usulan dengan kriteria biaya, keandalan, dampak dan akses.\nNilai pertanyaan pengamatan, catatan bukti, penjelasan hubungan, batas kesimpulan dan keselamatan. Bedakan yang diamati dari yang dipelajari dari sumber. Jangan meminta percobaan berisiko atau menilai tubuh/kemampuan pribadi teman.\nGunakan rubrik 0 = belum tampak, 1 = dengan banyak bantuan, 2 = sebagian mandiri, 3 = mandiri disertai alasan pada tiap kriteria. Catat bukti dan bantuan yang diperlukan; kriteria ketercapaian disepakati guru, bukan otomatis ditentukan XP.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
